For higher-degree correlations, a well-known conjecture of Chowla~\cite{chowla} asserts that, for any $k\geqslant 1$ and distinct integers $h_1, \ldots, h_{k}$, one has
\begin{equation}
\label{conj:chowla}
	\frac{1}{x}\sum_{n\leqslant x} \lambda(n+h_1) \lambda(n+h_2) \cdots \lambda(n+h_k) = o_{x\to \infty}(1).
\end{equation}

In 2021, Helfgott and Radziwi\l\l~\cite{HR} proved the substantial quantitative improvement
\begin{equation}
\label{eq:HRchowla}
\sum_{n\leqslant x} \frac{1}{n}\lambda(n) \lambda(n+1) \ll \frac{\log x}{(\log \log x)^{1/2}}.
\end{equation}

\label{cor:manipulation}
For some absolute constant $c>0$,
\begin{equation*}
\sum_{n\leqslant x} \frac 1n \lambda(n) \lambda(n+1) \ll (\log x)^{1-c}.
\end{equation*}

Using the multiplicativity of $\lambda$, Tao~\cite{T} showed that the problem of bounding $\sum_{n\leqslant x} \frac 1n \lambda(n) \lambda(n+1)$ reduces to bounding 
\begin{equation*}
	\mathbb{E}_{p\in P} \sum_{n\leqslant x} \lambda(n) \lambda(n+p) \left(\ind{p\mid n}-\frac{1}{p}\right)
\end{equation*}
where $P \subset [1, \exp(\sqrt{\log x})]$ is a set of primes.

Following the strategy of Helfgott and Radziwi\l\l~\cite{HR}, it is sufficient to bound the eigenvalues of the matrix $\widetilde{A}|_X$ where $\widetilde{A}$ is the matrix defined by 
\begin{equation*}
	\widetilde{A}_{mn} := \begin{cases} \prod_{p\mid d}\left(\ind{p\mid n}-\frac{1}{p}\right) &\text{if }\abs{m-n}=d\in D,\\ 0&\text{otherwise;}\end{cases}
\end{equation*}
and $X$ is a large subset of $\{1, \ldots, x\}$.

\label{thm:main}
Let $\varepsilon_1>0$ be a sufficiently small absolute constant. Let $H>0$ be sufficiently large in terms of $\varepsilon_1$. Let $J$ be a positive integer with $J \leqslant \varepsilon_1^2 \log \log H$, and let $H_0 = \exp \big((\log H)^{1-\varepsilon_1}\big)$.

Let $C := \exp\big(\varepsilon_1 (\log \log H)/(2J)\big)$. For $1\leqslant i\leqslant J$, let $\mathcal{P}_i$ be the set of all primes $p$ with
\begin{equation*}
C^{2i-2} < \frac{\log p}{\log H_0} < C^{2i-1}
\end{equation*}
and let $V_i := \sum_{p\in \mathcal{P}_i} \frac{1}{p}$.

Let $N$ be an integer such that $\log N \geqslant (\log H)^3$. Then
\begin{equation}
\label{eq:summainthm}
	\sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}}\,  \sum_{\substack{n\in (N, 2N] \\ p_1\cdots p_{J} \mid n}}\lambda(n) \lambda(n+p_1\cdots p_{J}) \ll (V_1\cdots V_{J})^{3/4} N.
\end{equation}

\begin{equation}
\label{eq:summainthm}
	\sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}}\,  \sum_{\substack{n\in (N, 2N] \\ p_1\cdots p_{J} \mid n}}\lambda(n) \lambda(n+p_1\cdots p_{J}) \ll (V_1\cdots V_{J})^{3/4} N.
\end{equation}

\label{rem:withabsval}
The techniques of this paper actually show the slightly stronger result
\begin{equation}
\label{eq:summainthmABSVAL}
	\sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}} \Bigg\lvert \sum_{\substack{n\in (N, 2N] \\ p_1\cdots p_{J} \mid n}}\lambda(n) \lambda(n+p_1\cdots p_{J})  \Bigg\rvert \ll (V_1\cdots V_{J})^{3/4} N.
\end{equation}
To obtain this, all that is required is to reiterate the entire proof, allowing for arbitrary coefficients $c_{p_1, \ldots, p_{J}} \in \{\pm 1\}$ throughout. No other modifications are necessary, and the result becomes
\begin{equation*}
\sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}} c_{p_1, \ldots, p_{J}} \sum_{\substack{n\in (N, 2N] \\ p_1\cdots p_{J} \mid n}}\lambda(n) \lambda(n+p_1\cdots p_{J}) \ll \curlyLexp{3J/4} N,
\end{equation*}
from which \cref{eq:summainthmABSVAL} follows. For the sake of brevity and readability, we will refrain from presenting a detailed proof of \cref{eq:summainthmABSVAL}. Instead, we will concentrate on the seemingly weaker estimate given in \cref{thm:main}, which omits absolute values on the left-hand side. In any case, we will see in the next section that \cref{thm:main} suffices to prove \cref{cor:manipulation}, which is our primary motivation.

\begin{equation}
\label{eq:summainthmABSVAL}
	\sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}} \Bigg\lvert \sum_{\substack{n\in (N, 2N] \\ p_1\cdots p_{J} \mid n}}\lambda(n) \lambda(n+p_1\cdots p_{J})  \Bigg\rvert \ll (V_1\cdots V_{J})^{3/4} N.
\end{equation}

\begin{equation*}
\sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}} c_{p_1, \ldots, p_{J}} \sum_{\substack{n\in (N, 2N] \\ p_1\cdots p_{J} \mid n}}\lambda(n) \lambda(n+p_1\cdots p_{J}) \ll \curlyLexp{3J/4} N,
\end{equation*}

Let $C := \exp\big(\varepsilon_1 (\log \log H)/(2J)\big) \geqslant 20$, so that $\mathcal{P}_i$ is the set of all primes in the interval
\begin{equation*}
\Big(\exp \left(C^{2i-2} \log H_0\right),\  \exp \left(C^{2i-1} \log H_0\right) \Big).
\end{equation*}
Property \cref{item:primesetsm1} is clear. By Mertens' second estimate, we have 
\begin{equation}
\label{eq:approxLi}
V_i = \frac{\varepsilon_1 \log \log H}{2J} + O\left(\frac{1}{\log H_0}\right). 
\end{equation}
This implies property \cref{item:primesets7}. If $(p_1, \ldots, p_{J}) \in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}$, then for all $i\in \sinterval{J}$ we have 
\begin{equation*}
p_1p_2\cdots p_i < \exp \Bigg(\sum_{1\leqslant j\leqslant i} C^{2j-1} \log H_0\Bigg) \leqslant \exp \Big( 2C^{2i-1} \log H_0\Big) \leqslant \exp \bigg( \frac{C^{2i}}{10} \log H_0\bigg).
\end{equation*}
The right-hand side is $\leqslant p_{i+1}^{1/10}$ if $i<J$, and equals $H^{1/10}$ if $i=J$. This proves \cref{item:primesets8}.
Finally, the last two bounds for $V^J$ follow from \cref{item:primesets7} and the fact that the function $J\mapsto (A/J)^J$ is increasing on $[0, A/e]$, for any $A>0$.

\begin{equation*}
p_1p_2\cdots p_i < \exp \Bigg(\sum_{1\leqslant j\leqslant i} C^{2j-1} \log H_0\Bigg) \leqslant \exp \Big( 2C^{2i-1} \log H_0\Big) \leqslant \exp \bigg( \frac{C^{2i}}{10} \log H_0\bigg).
\end{equation*}

\begin{equation}
\label{eq:summainthmBIS}
	S_1 := \sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}} \, \sum_{\substack{n\in (N, 2N] \\ p_1\cdots p_{J} \mid n}}\lambda(n) \lambda(n+p_1\cdots p_{J})
\end{equation}

Let $\varepsilon_1 > 0$ be a sufficiently small constant. Let $H$ be a real number, chosen sufficiently large in terms of $\varepsilon_1$ so that \cref{lem:primesets} applies. We define ${H_0 := \exp \big((\log H)^{1-\varepsilon_1}\big)}$ and $x := \exp\big((\log H)^{6}\big)$. Choose $J$ to be an integer of the form $c \log \log H$ where $\varepsilon_1^2/2\leqslant c \leqslant \varepsilon_1^2$. Let $(\mathcal{P}_i)$ and $(V_i)$ be as in \cref{thm:main}. Let $V := \max_i V_i$. In particular, ${(\log x)^{4\varepsilon_1^2} \ll V^{J} \ll (\log x)^{\varepsilon_1}}$ by \cref{lem:primesets}.

By \cref{thm:main}, we know that 
\begin{equation}
\label{eq:largerangemainthm}
	S_1 = \sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}} \, \sum_{\substack{n\in (N, 2N] \\ p_1\cdots p_{J} \mid n}}\lambda(n) \lambda(n+p_1\cdots p_{J}) \ll \curlyLexp{3J/4} N
\end{equation}
whenever $\log N \geqslant (\log H)^3 = \sqrt{\log x}$. Moreover, when ${\log N \leqslant \sqrt{\log x}}$, trivially bounding $\abs{\lambda} \leqslant 1$ we have
\begin{equation}
\label{eq:smallrangemainthm}
	\sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}} \, \sum_{\substack{n\in (N, 2N] \\ p_1\cdots p_{J} \mid n}}\lambda(n) \lambda(n+p_1\cdots p_{J}) \ll V^{J} N.
\end{equation}
By a suitable dyadic decomposition, \cref{eq:largerangemainthm,eq:smallrangemainthm} together give, for all $M\geqslant 1$, the bound
\begin{equation}
\label{eq:allrangesmainthm}
	\sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}}  \sum_{\substack{m\leqslant M \\ p_1\cdots p_{J} \mid m}}\lambda(m) \lambda(m+p_1\cdots p_{J}) \ll V^{J} \min\!\big(M, e^{\sqrt{\log x}}\big) + \curlyLexp{3J/4} M.
\end{equation}
By partial summation, \cref{eq:allrangesmainthm} and the bound $V^{J}\ll (\log{x})^{\varepsilon_1}$ imply that
\begin{equation}
\label{eq:mainthmpartialsumm}
	\sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}}  \sum_{\substack{m\leqslant x \\ p_1\cdots p_{J} \mid m}}\frac{1}{m} \lambda(m) \lambda(m+p_1\cdots p_{J}) \ll \curlyLexp{3J/4} \log x.
\end{equation}

Let us now relate this estimate \cref{eq:mainthmpartialsumm} to the expression $\sum_{n\leqslant x} \frac 1n \lambda(n) \lambda(n+1)$ we are interested in. For any $(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}$, since $\lambda$ is completely multiplicative and $\lambda^2=1$, we may rewrite
\begin{align*}
\sum_{n\leqslant x} \frac 1n \lambda(n) \lambda(n+1) &=  \sum_{n\leqslant x} \frac 1n \lambda(p_1\cdots p_{J}n) \lambda(p_1\cdots p_{J}n+p_1\cdots p_{J})\\ &= p_1\cdots p_{J} \sum_{\substack{m\leqslant p_1\cdots p_{J}x\\ p_1\cdots p_{J}\mid m}} \frac 1m \lambda(m) \lambda(m+p_1\cdots p_{J}).
\end{align*}
Dividing by $p_1\cdots p_{J}$ and summing over $(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}$ yields
\begin{equation}
\label{eq:manip1}
V_1\cdots V_{J} \sum_{n\leqslant x} \frac 1n \lambda(n) \lambda(n+1) = \sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}}\, \sum_{\substack{m\leqslant p_1\cdots p_{J}x\\ p_1\cdots p_{J}\mid m}} \frac 1m \lambda(m) \lambda(m+p_1\cdots p_{J}). 
\end{equation}
This is almost the expression in \cref{eq:mainthmpartialsumm}, up to an error
\begin{align*}
\Bigg|\sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}}\, \sum_{\substack{x<m\leqslant p_1\cdots p_{J}x\\ p_1\cdots p_{J}\mid m}} \frac 1m \lambda(m) \lambda(m+p_1\cdots p_{J})\Bigg| &\leqslant \sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}}\, \sum_{\substack{x<m\leqslant p_1\cdots p_{J}x\\ p_1\cdots p_{J}\mid m}} \frac 1m\\ 
 &\ll \sum_{(p_1, \ldots, p_{J})\in \mathcal{P}_1\times \cdots \times \mathcal{P}_{J}} \frac{\log(p_1\cdots p_{J})}{p_1\cdots p_{J}}
\end{align*}
which is $\ll V^{J} \log H$. Hence, by \cref{eq:mainthmpartialsumm} and \cref{eq:manip1} we conclude that
\begin{equation*}
\sum_{n\leqslant x} \frac 1n \lambda(n) \lambda(n+1) \ll \frac{1}{V^{J}} \left({\curlyLexp{3J/4} \log x} +V^{J} \log H \right) \ll (\log x)^{1-\varepsilon_1^2}. \qedhere
\end{equation*}

