\label{rem:almostallscales}
Our main result also implies an improved quantitative version of Chowla's conjecture for two-point correlations at \emph{almost all scales}. Namely, for all $e<w\leqslant X$, we have
\begin{equation}
\label{eq:almostallscales}
	\frac{1}{\log w} \int_{X/w}^X \abs{\frac{1}{x} \sum_{n\leqslant x} \lambda(n) \lambda(n+1)} \frac{dx}{x} \ll \frac{1}{(\log w)^c},
\end{equation}
where $c>0$ is an absolute constant. In particular, we get
\begin{equation*}
	\frac{1}{x} \sum_{n\leqslant x} \lambda(n) \lambda(n+1) \ll \frac{1}{(\log X)^{c/2}}
\end{equation*} 
for all $x\in [1, X]$ outside of a set $E_X$ of logarithmic density $O((\log X)^{-c/2})$.\footnote{This means that $\displaystyle{\frac{1}{\log X}\int_1^X \ind{E_X}(x) \frac{dx}{x} \ll (\log X)^{-c/2}}$.}

This almost all scales result \cref{eq:almostallscales} follows from \cref{eq:summainthmABSVAL} by a straightforward adaptation of the proof in \cite[Section~8]{HR} (which is itself inspired from \cite{TT}) to our setting.

We define the `balanced' double sum
\begin{equation}
\label{eq:balanced}
S_2 :=\! \sum_{(p_1,\ldots, p_{J})\in \mathcal{P}_1\times\cdots\times \mathcal{P}_{J}}\, \sum_{n\in (N, 2N]} \left(\ind{p_1\mid n} - \frac{1}{p_1}\right)\cdots \left(\ind{p_{J}\mid n} - \frac{1}{p_{J}}\right) \lambda(n) \lambda(n+p_1\cdots p_{J}).
\end{equation}

\label{prop:differencesum}
Let $\varepsilon_1$, $H$, $J$, $H_0$, $(\mathcal{P}_i)$ and $(V_i)$ be as in \cref{thm:main}. Let $V := \max_i V_i$. 

Let $N \geqslant \exp\big((\log H)^{2}\big)$. With $S_1$ and $S_2$ as in \cref{eq:summainthmBIS} and \cref{eq:balanced}, we have
\begin{equation*}
\left| S_1 - S_2 \right| \ll \frac{N}{(\log H)^{1/2500}}.
\end{equation*}

\label{not:bigP}
We define $\mathcal{P} := \bigsqcup_{j=1}^{J} \mathcal{P}_j$. To shorten the expressions, we define $\mathcal{D}$ to be the set of all products $p_1p_2\cdots p_{J}$ with $p_i\in \mathcal{P}_i$ for all $i\in \sinterval{J}$. We also write $I_N := \mathbb{N} \cap (N, 2N]$.

Thus, $S_1$ and $S_2$ may be rewritten more concisely as
\begin{equation*}
S_1 := \sum_{n\in I_N} \sum_{\substack{d\in \mathcal{D}\\ d\mid n}} \lambda(n) \lambda(n+d)\quad \text{and}\quad S_2 = \sum_{n\in I_N} \sum_{d\in \mathcal{D}} \lambda(n) \lambda(n+d) \prod_{p\mid d} \bigg(\ind{p\mid n} - \frac{1}{p} \bigg).
\end{equation*}

\begin{equation*}
S_1 := \sum_{n\in I_N} \sum_{\substack{d\in \mathcal{D}\\ d\mid n}} \lambda(n) \lambda(n+d)\quad \text{and}\quad S_2 = \sum_{n\in I_N} \sum_{d\in \mathcal{D}} \lambda(n) \lambda(n+d) \prod_{p\mid d} \bigg(\ind{p\mid n} - \frac{1}{p} \bigg).
\end{equation*}

\label{lem:S2toadjacencyop}
Define the weighted graph ${G_0 = (I_N, w_0)}$, where the edge between $n\in I_N$ and $m\in I_N$ has weight 
\begin{equation*}
w_0(m,n) = \begin{cases}
\prod_{p\mid d} \left(\ind{p\mid n} - \frac{1}{p}\right) &\text{if }|m-n| = d \in \mathcal{D},\\
0 & \text{otherwise.}
\end{cases}
\end{equation*}
Let $\mathrm{Ad}_{G_0} = \left(w_0(m,n)\right)_{m,n\in I_N}$ be the weighted adjacency matrix of $G_0$. Let $\boldsymbol{\lambda}$ be the column vector $\left(\lambda(n)\right)_{n\in I_N}$. We have 
\begin{equation*}
S_2 = \tfrac12 \inner{\boldsymbol{\lambda}, \mathrm{Ad}_{G_0}\boldsymbol{\lambda}} + O\big(H^{2}\big).
\end{equation*}

By definition of $\mathrm{Ad}_{G_0}$, we have
\begin{equation*}
	\inner{\boldsymbol{\lambda}, \mathrm{Ad}_{G_0}\boldsymbol{\lambda}} = \sum_{n\in I_N} \sum_{\substack{d\in \pm\mathcal{D}\\ n+ d\in I_N}} \prod_{p\mid d} \left(\ind{p\mid n} - \frac{1}{p}\right) \lambda(n)\lambda(n+ d) = 2S_2 + O \left(\sum_{n\in I_N} \sum_{\substack{d\in \pm\mathcal{D}}} \ind{n+d\not\in I_N}\right).
\end{equation*}
Recalling that $\pm \mathcal{D} \subset [-H, H]$, the error term is $\ll \sum_{n\in I_N} \abs{\mathcal{D}} \ind{\min(n-N, 2N-n) \leqslant H}  \ll H^2$.

\begin{equation*}
	\inner{\boldsymbol{\lambda}, \mathrm{Ad}_{G_0}\boldsymbol{\lambda}} = \sum_{n\in I_N} \sum_{\substack{d\in \pm\mathcal{D}\\ n+ d\in I_N}} \prod_{p\mid d} \left(\ind{p\mid n} - \frac{1}{p}\right) \lambda(n)\lambda(n+ d) = 2S_2 + O \left(\sum_{n\in I_N} \sum_{\substack{d\in \pm\mathcal{D}}} \ind{n+d\not\in I_N}\right).
\end{equation*}

\label{lem:cauchy}
Let $A = (a_{m,n})_{m,n\in I_N}$ be a Hermitian matrix with eigenvalues $\alpha_1 \geqslant \ldots \geqslant \alpha_N$. Let $X\subset I_N$ and let $\beta_1 \geqslant \ldots \geqslant \beta_{N-|X|}$ be the eigenvalues of $A|_{X}$. Then, for $j\in  \sinterval{N-|X|}$, we have 
\begin{equation*}
	\alpha_j \geqslant \beta_j \geqslant \alpha_{j+|X|}.
\end{equation*}

\label{prop:traceeigenvalues}
Let $A  = (a_{m, n})_{m, n\in I_N}$ be a Hermitian matrix such that $a_{m,n} = 0$ whenever $|m-n| > H$. Let $\alpha>0$, $\varepsilon\in (0,1)$, and suppose that $N \geqslant 10H/\varepsilon^2$. Then at least one of the following holds.
\begin{enumerate}
	\item There is a subset $E\subset I_N$ with $|E| \ll \varepsilon N$ such that every eigenvalue of $A|_{I_N\setminus E}$ has absolute value~$\leqslant \alpha$.
	\item For any even integer $R\geqslant 2$, 
	\begin{equation*}
		\mathrm{Tr} \big(A^{R}\big) \geqslant \frac{\varepsilon^2}{H} \alpha^{R}N.
	\end{equation*}
\end{enumerate}

Divide $I_N$ into a sequence of disjoint discrete intervals $B_0, E_0, B_1, E_1, \ldots, B_{q-1}, E_{q-1}, B_q$ (lying in this order in $I_N$), such that the $E_i$ have size $H$ and the $B_i$ have size $\lfloor 1/\varepsilon \rfloor H$, except for the last interval $B_q$ which contains the $<H(1+\lfloor 1/\varepsilon \rfloor )$ remaining elements. Since $N\geqslant 10H/\varepsilon^2$, we have $q\asymp \varepsilon N/H\gg 1/\varepsilon$.

Let $B = \bigsqcup_{i=0}^q B_i$. Since $B_0, \ldots, B_q$ have pairwise distance $> H$, the property of $A$ in the statement implies that the submatrix $A|_{B}$ is block-diagonal with blocks $A|_{B_i}$ for $0\leqslant i\leqslant q$. 

Let $\mathcal{I}$ be the set of all indices $0\leqslant i\leqslant q$ such that $A|_{B_i}$ has an eigenvalue $>\alpha$ in absolute value. 

If $| \mathcal{I} | \leqslant \varepsilon^2N/H$, we are in the first case of the conclusion. Indeed, we can take $E = \bigcup_{i=0}^{q-1}E_i \cup \bigcup_{i\in \mathcal{I}} B_i$ -- clearly, all eigenvalues of $A|_{I_N \setminus E} = A|_{\bigsqcup_{i\not\in \mathcal{I}}B_i}$ have absolute value $\leqslant \alpha$, and 
\begin{equation*}
|E| \leqslant qH + (\varepsilon^2N/H) (2H/\varepsilon) \ll \varepsilon N.
\end{equation*}

Otherwise, $A|_{B}$ has at least $\varepsilon^2N/H$ eigenvalues with absolute value $>\alpha$, counted with multiplicity. By Cauchy's interlacing theorem, the same is true for $A$. Thus, if $(\lambda_i)_{1\leqslant i\leqslant N}$ are the eigenvalues of $A$, we have, for every even integer $R$,
\begin{equation*}
	\mathrm{Tr} \big(A^{R}\big) = \sum_{i} \lambda_i^{R} \geqslant \frac{\varepsilon^2N}{H} \alpha^{R}
\end{equation*}
as all $\lambda_i$ are real.

\label{prop:smalltrace}
There exists a weighted graph $G = (I_N, w)$ with $\norm{w}_{\infty} \leqslant 1$ such that
\begin{enumerate}
