\leqslant \sum_{\substack{\mathcal{S}\sqcup \mathcal{L}\sqcup \mathcal{U} = \sinterval{K}\times\sinterval{J}}}\abs{ \sum_{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}}  \mathbb{E} \left[w_{\boldsymbol{d}}(\mathbf{n}) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right]}.
\end{equation*}
We denote the inner sum (over $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}$) by $\Sigma_{\mathcal{S},\mathcal{L},\mathcal{U}}$.

Summing over all possible sets of single indices, we have
\begin{equation*}
	\sum_{\substack{\boldsymbol{d}\in \mathbf{D}_{\!K}}}\,   \mathbb{E} \left[w_{\boldsymbol{d}}(\mathbf{n}) \right] = \sum_{\substack{\mathcal{S}\subset  \sinterval{K}\times\sinterval{J}}} \,{ \sum_{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}}  \mathbb{E} \left[w_{\boldsymbol{d}}(\mathbf{n}) \right]}.
\end{equation*}
Let us `condition' on the value of the sequence $\big(\ind{\pcomp{i}{j}\mid \mathbf{n}+b_i}\big)_{(i,j)\in (\sinterval{K}\times\sinterval{J})\setminus \mathcal{S}}$. We do this by summing over all possible decompositions of $(\sinterval{K}\times\sinterval{J})\setminus \mathcal{S}$ as a disjoint union $\mathcal{L} \sqcup \mathcal{U}$, which gives
\begin{equation*}
	\sum_{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}}  \mathbb{E} \left[w_{\boldsymbol{d}}(\mathbf{n}) \right] = \sum_{(\sinterval{K}\times\sinterval{J})\setminus \mathcal{S} = \mathcal{L} \sqcup \mathcal{U}}  \sum_{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}} \mathbb{E} \left[w_{\boldsymbol{d}}(\mathbf{n}) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right].
\end{equation*}
The result now follows from the triangle inequality.

\label{lem:unlit}
Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $\sinterval{K}\times\sinterval{J} = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$ and $|\mathcal{U}|\geqslant K^{2\varepsilon_1}$. Then
\begin{equation*}
\Sigma_{\mathcal{S},\mathcal{L},\mathcal{U}} \ll 1.
\end{equation*}

Let $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}$. We start by using the trivial bound
\begin{align*}
\mathbb{E} \left[\abs{w_{\boldsymbol{d}}(\mathbf{n}) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}}} \right] 
&\leqslant \mathbb{E} \left[\ind{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} }  \prod_{(i,j)\in \mathcal{S}} \abs{\ind{\pcomp{i}{j}\mid \mathbf{n} + b_i} - \frac{1}{\pcomp{i}{j}}}  \prod_{(i,j)\in \mathcal{U}}\frac{1}{\pcomp{i}{j}}\right] \\
&\leqslant \prod_{p\mid \fprod{\boldsymbol{d};\mathcal{S} \sqcup \mathcal{L}}} \frac{2}{p} \prod_{(i,j)\in \mathcal{U}}\frac{1}{\pcomp{i}{j}}.
\end{align*}
Next, we observe that, by definition of single, lit and unlit indices,
\begin{equation*}
	\ind{p\mid  \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}} + \tfrac12 \abs{\{(i,j)\in \mathcal{U} : \pcomp{i}{j} = p\}} \geqslant \ind{p\mid \fprod{\boldsymbol{d}}},
\end{equation*}
for all $p\in \mathcal{P}$. Indeed, if $p\mid \fprod{\boldsymbol{d}}$ and $p\nmid \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}$, there are at least two indices $(i,j)$ such that $p = \pcomp{i}{j}$, which must be unlit. 

Since all primes in $\mathcal{P}$ are $\geqslant H_0$, this implies that
\begin{equation*}
\prod_{p\mid \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}} \frac{2}{p} \prod_{(i,j)\in \mathcal{U}}\frac{1}{\pcomp{i}{j}} \leqslant H_0^{-|\mathcal{U}|/2} \prod_{p\mid \fprod{\boldsymbol{d}}} \frac{2}{p}.
\end{equation*}
Therefore, 
\begin{equation*}
\Sigma_{\mathcal{S},\mathcal{L},\mathcal{U}} \leqslant  H_0^{-|\mathcal{U}|/2} \sum_{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}} \prod_{p\mid \fprod{\boldsymbol{d}}} \frac{2}{p},
\end{equation*}
which is $\ll H_0^{-|\mathcal{U}|/2}K^{2K J}$ by \cref{lem:trivialbound}. Recall that ${\log H_0 \gg K^{1-\varepsilon_1}}$, while ${|\mathcal{U}|\geqslant K^{2\varepsilon_1}}$ by assumption. Thus, $H_0^{|\mathcal{U}|/2} \gg \exp\big(K^{1+\tfrac{\varepsilon_1}{2}}\big) \gg K^{2K J}$ and the conclusion follows.

\label{lem:litcond}
