\label{def:backtracking}
Let $\boldsymbol{d} \in \mathbb{Z}^{R}$. We define the \emph{reduced walk} to be the vector $\widetilde{\boldsymbol{d}}$ obtained by recursively removing pairs of consecutive entries $d_i, d_{i+1}$ with $d_{i+1} = -d_i$, until this is no longer possible. 

We write $\widetilde{R}$ for the length of $\widetilde{\boldsymbol{d}}$. Thus, if $\boldsymbol{d} \in \mathbf{D}_{\!R}$, then $\widetilde{\boldsymbol{d}} \in \Dsfmix{\widetilde{R}}$.

\label{lem:reducedlit}
Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $\sinterval{R}\times\sinterval{J} = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$. Let $\boldsymbol{d} \in \mathbf{D}^{\mathcal{S}}_{\!R}$. Let $\boldsymbol{d}'$ be a vector obtained by recursively removing some pairs of backtracking steps from $\boldsymbol{d}$ (but not necessarily all).\footnote{So $\boldsymbol{d}'$ could be the reduced walk $\widetilde{\boldsymbol{d}}$ or any vector obtained at an intermediate stage in the reduction process.} Let $R'$ be the length of $\boldsymbol{d}'$. There is a canonical injection
\begin{equation*}
	\iota : \sinterval{R'} \to \sinterval{R}
\end{equation*}
such that $d'_k = d_{\iota(k)}$ for all $k\in \sinterval{R'}$. 

Define $\mathcal{S}'$ to be the set of single indices of $\boldsymbol{d}'$ (i.e.~the set of pairs $(k,j)\in \sinterval{R'}\times \sinterval{J}$ such that ${d'_{kj}}^2 = {\pcomp{\iota(k)}{j}}^2$ does not divide $\fprod{\boldsymbol{d}'}$). We also define
\begin{align*}
	\mathcal{L}' &:= \{(k,j)\in (\sinterval{R'} \times \sinterval{J}) \setminus \mathcal{S}' : (\iota(k), j)\in \mathcal{L}\}, \\
	\mathcal{U}' &:= \{(k,j)\in (\sinterval{R'} \times \sinterval{J}) \setminus \mathcal{S}' : (\iota(k), j)\in \mathcal{U}\}.
\end{align*}

The following properties hold:
\begin{enumerate}
	\item if $(i,j)\in \mathcal{S}$ then $i = \iota(k)$ for some $k\in \sinterval{R'}$, and $(k,j)\in \mathcal{S}'$;
	\item $\sinterval{R'} \times \sinterval{J} = \mathcal{S}' \sqcup \mathcal{L}' \sqcup \mathcal{U}'$;
	\item $|\mathcal{S}| \leqslant |\mathcal{S}'| \leqslant |\mathcal{S}| + \tfrac13 R J$.
\end{enumerate}

\begin{enumerate}
	\item If $(i,j)\in \mathcal{S}$, then $\pcomp{i}{j}$ cannot appear in the backtracking part of $\boldsymbol{d}$, as otherwise $\pcomp{i}{j}^2$ would divide $\fprod{\boldsymbol{d}}$. Thus, $\pcomp{i}{j} \mid \fprod{\boldsymbol{d}'}$. Clearly, $\pcomp{i}{j}^2 \nmid \fprod{\boldsymbol{d}'}$, as $\fprod{\boldsymbol{d}'} \mid \fprod{\boldsymbol{d}}$ and $(i,j)\in \mathcal{S}$. This means that single indices for $\boldsymbol{d}$ become single indices for $\boldsymbol{d}'$ (through $\iota^{-1}$).
	\item We have just seen that $\mathcal{S}' \supset \{(k,j)\in \sinterval{R'} \times \sinterval{J} : (\iota(k), j)\in \mathcal{S}\}$. By definition of $\mathcal{L}'$ and $\mathcal{U}'$, this implies that $\sinterval{R'} \times \sinterval{J} = \mathcal{S}' \sqcup \mathcal{L}'\sqcup \mathcal{U}'$. 
	\item We have $\abs{\mathcal{S}'} = \abs{\mathcal{S}} + t$, where $t$ is the number of distinct primes $p$ such that $p\mid \fprod{\boldsymbol{d}'}$, $p^2 \nmid \fprod{\boldsymbol{d}'}$ ($p$ corresponds to a single index for $\boldsymbol{d}'$) and $p^2\mid \fprod{\boldsymbol{d}}$ ($p$ does not correspond to a single index for $\boldsymbol{d}$). Let $p$ be a prime with these properties. Then $p$ divides some $d_i$ in the backtracking steps deleted in going from $\boldsymbol{d}$ to $\boldsymbol{d}'$, but since these $d_i$ come in pairs we conclude that 
	\begin{equation*}
		p^2 \mid \frac{\fprod{\boldsymbol{d}}}{\fprod{\boldsymbol{d}'}}.
	\end{equation*}	
	Hence, $p^3 \mid \fprod{\boldsymbol{d}}$. Since $\fprod{\boldsymbol{d}}$ has $RJ$ prime factors (with multiplicity), this shows that $3t\leqslant RJ$, which completes the proof.\qedhere
\end{enumerate}

\label{lem:litcondreduced}
Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $\sinterval{R}\times\sinterval{J} = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$. Suppose that $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!R}$ is such that
\begin{equation}
\label{eq:expectnonzeroreduced}
	\mathbb{E} \left[w_{\boldsymbol{d}}(\mathbf{n}) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right] \neq 0.
\end{equation}
Let $\widetilde{\boldsymbol{d}} \in \Dsfmix{\widetilde{R}}$ be the reduced walk, and let $\widetilde{\mathcal{S}},\widetilde{\mathcal{L}},\widetilde{\mathcal{U}}$ be the sets of single, lit and unlit indices associated to $\widetilde{\boldsymbol{d}}$ (as in \cref{lem:reducedlit}).
\begin{enumerate}
	\setcounter{enumi}{\numexpr3-1\relax}
	\item \label{item:litcond3} 
	For all $k_1 < k_2$ in $\sinterval{R}$ with $k_2-k_1 < L$ and $\interval{k_1}{k_2} \times \sinterval{J} \subset \widetilde{\mathcal{L}}$, neither $(\widetilde{d}_{k_1}, \widetilde{d}_{k_1+1}, \ldots, \widetilde{d}_{k_2})$ nor $(\widetilde{d}_{k_2}, \widetilde{d}_{k_2-1}, \ldots, \widetilde{d}_{k_1})$ are prohibited sequences.
\end{enumerate}

Let $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!R}$ be such that \cref{eq:expectnonzeroreduced} holds. In particular, there exists some $n\in \mathbb{Z}$ such that 
\begin{itemize}
	\item $\pcomp{i}{j}\mid n+b_i$ for all $(i,j)\in \mathcal{L}$,
	\item and $n+b_i\in Y_{\!L}$ for all $i\in \sinterval{R}$.
\end{itemize}

Suppose that \cref{item:litcond3} fails. Thus, there are some $1\leqslant k_1 < k_2\leqslant \widetilde{R}$ with $k_2-k_1<L$, such that ${\interval{k_1}{k_2} \times \sinterval{J} \subset \widetilde{\mathcal{L}}}$ and one of $(\widetilde{d}_{k_1}, \widetilde{d}_{k_1+1}, \ldots, \widetilde{d}_{k_2})$ or $(\widetilde{d}_{k_2}, \widetilde{d}_{k_2-1}, \ldots, \widetilde{d}_{k_1})$ is a prohibited sequence. Without loss of generality, we may assume that one of these two is a primitive prohibited sequence. Since ${\interval{k_1}{k_2} \times \sinterval{J} \subset \widetilde{\mathcal{L}}}$ we know that $\widetilde{d}_{k} \mid n+b_{\iota(k)}$ for all $k\in \interval{k_1}{k_2}$. 

Let $k\in \interval{k_1}{k_2}$. Note that
\begin{equation*}
	n+b_{\iota(k)} = (n+b_{\iota(k_1)}) + \sum_{\iota(k_1)\leqslant i < \iota(k) }d_i = (n+b_{\iota(k_1)}) + \sum_{k_1\leqslant k' < k }\widetilde{d}_{k'}.
\end{equation*}
where the second equality follows from the definition of the reduced walk (the two sums differ by sums of pairs of backtracking steps, which cancel each other out).
Therefore, if $(\widetilde{d}_{k_1}, \widetilde{d}_{k_1+1}, \ldots, \widetilde{d}_{k_2})$ is a primitive prohibited sequence, the fact that 
\begin{equation*}
	\widetilde{d}_{k} \ \Big\vert \ (n+b_{\iota(k_1)}) + \sum_{k_1\leqslant k' < k }\widetilde{d}_{k'}
\end{equation*}
for all $k\in \interval{k_1}{k_2}$ implies that $n+b_{\iota(k_1)}$ belongs to the prohibited progression associated to $(\widetilde{d}_{k_1}, \widetilde{d}_{k_1+1}, \ldots, \widetilde{d}_{k_2})$. This contradicts the assumption that $n+b_{\iota(k_1)}\in Y_{\!L}$. 

Similarly, if $(\widetilde{d}_{k_2}, \widetilde{d}_{k_2-1}, \ldots, \widetilde{d}_{k_1})$ is a primitive prohibited sequence, so is $(-\widetilde{d}_{k_2}, -\widetilde{d}_{k_2-1}, \ldots, -\widetilde{d}_{k_1})$, and the divisibility relations 
\begin{equation*}
	-\widetilde{d}_{k} \ \Big\vert \ n+b_{\iota(k)} + \widetilde{d}_{k} = (n+b_{\iota(k_2)+1}) - \sum_{k < k' \leqslant k_2 }\widetilde{d}_{k'}
\end{equation*}
imply that $n+b_{\iota(k_2)+1}$ belongs to the prohibited progression associated to $(-\widetilde{d}_{k_2}, -\widetilde{d}_{k_2-1}, \ldots, -\widetilde{d}_{k_1})$. Again, this contradicts the assumption that $n+b_{\iota(k_2)+1} \in Y_{\!L}$, and the proof is finished.

By  \cref{cor:traceexpressioncleaned,lem:manip}, we have
\begin{equation*}
	\mathrm{Tr} \big((\mathrm{Ad}_{G})^{K}\big) \leqslant e^{O(KJ)}N \bBigg@{3}( 1+ \sup_{\substack{\mathcal{S}\sqcup \mathcal{L}\sqcup \mathcal{U} = \sinterval{K}\times\sinterval{J}}}\, \sum_{\boldsymbol{d}\in \mathbf{D}_{\!K}}\abs{ \mathbb{E} \left[w_{\boldsymbol{d}}(\mathbf{n}) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right] }\bBigg@{3}).
\end{equation*}
By \cref{lem:unlit}, we may add the condition $|\mathcal{U}| <K^{2\varepsilon_1}$ in the supremum, at the cost of an error term which can be absorbed into the $e^{O(KJ)} N$ term. By \cref{lem:litcond,lem:litcondreduced}, we may restrict the sum to the elements of $\mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}$ only.

\label{def:badsingle}
Let $\mathcal{S}\subset \sinterval{K}\times\sinterval{J}$ and $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}$. Define $\mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})$ to be the set of $(i, j)\in \mathcal{S}$ such that either
\begin{enumerate}
	\item \label{item:bad1} there exists $(i',j')\in \mathcal{S}$ with $b_i = b_{i'}$ and $i\neq i'$, or;
	\item \label{item:bad2} there exists $(i',j')\in \mathcal{S}$ with $b_{i+1} = b_{i'+1}$ and $i\neq i'$, or;
	\item \label{item:bad3} there exists $i' \in \sinterval{K}$ with $\pcomp{i}{j}\mid b_{i'} - b_i$ and $b_{i'} \not\in \{b_i, b_{i+1}\}$.
\end{enumerate}

\label{prop:cancellationAP}
Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $\sinterval{K}\times\sinterval{J} = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$. Let $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}$. Assume that
\begin{equation*}
\big|{\mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})}\big| \leqslant K^{1/2}.
\end{equation*}
Let $R$ be an arithmetic progression whose modulus $q_{R}$ is a square-free product of primes in $\mathcal{P}$. We assume that $q_{R}$ is divisible by at most $K^{1-\varepsilon_1}$ primes $p\mid \fprod{\boldsymbol{d}; \mathcal{S}}$. 

Let
\begin{equation*}
E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R) := \mathbb{E} \left[\,\ind{\mathbf{n}\in R}\, \prod_{i\in \sinterval{K}} W\big(\omega_{\mathcal{P}}(\mathbf{n}+b_i)\big)\prod_{(i,j)\in \mathcal{S}} \left(\ind{\pcomp{i}{j}\mid \mathbf{n} + b_i} - \frac{1}{\pcomp{i}{j}}\right) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right].
\end{equation*}
Then
\begin{equation*}
E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R) \ll e^{O(K J)} V^{-|\mathcal{S}|/2}  \prod_{p\mid q_{R} \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}}\frac{1}{p}.
\end{equation*}

For $p\mid \fprod{\boldsymbol{d}; \mathcal{S}}$, we write $b(p)$ for $b_i$, where $(i,j)$ is the unique index with $\pcomp{i}{j} = p$. Let $\alpha_1, \ldots, \alpha_{K_0}$ be the \emph{distinct} integers appearing in the sequence $b_1, \ldots, b_{K}$, and let $m_1, \ldots, m_{K_0}$ be the corresponding multiplicities. Then
\begin{equation*}
E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R) = \mathbb{E} \left[\,\ind{\mathbf{n}\in R}\, \prod_{1\leqslant k \leqslant K_0} W^{m_{k}}\big(\omega_{\mathcal{P}}(\mathbf{n}+\alpha_{k})\big)\prod_{p\mid \fprod{\boldsymbol{d}; \mathcal{S}}} \left(\ind{p\mid \mathbf{n}+b(p)} - \frac{1}{p} \right) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right].
\end{equation*}

In this proof, we will write $T := J V$ to lighten the notation. We introduce the Laplace transform $\widetilde{W}(z) := \int_0^{\infty} W(t) e^{-zt} \, dt$. Since $W$ is compactly supported, $\widetilde{W}$ is entire. Moreover, for any $a\geqslant 1$, integration by parts yields
\begin{equation*}
\widetilde{W}(z) =\frac{1}{z^a} \int_0^{\infty} W^{(a)} (t) e^{-zt} dt.
\end{equation*}
The same holds for $W^m$ in place of $W$, for any power $m\geqslant 1$. Therefore, if $\mathrm{Re}(z) < 0$, by \cref{lem:smoothcutoff} we have
\begin{equation}
\label{eq:derivativeboundLaplace}
|\widetilde{W^m}(z)| \leqslant \frac{1}{|z|^a}\cdot 2^m \left( \frac{Ca}{T} \right)^a \left( \int_0^{\tfrac12T}  e^{-\mathrm{Re}(z) t} dt +\int_{\tfrac32T}^{2T}  e^{-\mathrm{Re}(z) t} dt \right) \ll 2^m  e^{2T \mathrm{Re}(-z)} \frac{(Ca)^a}{|z|^a T^{a-1}}
\end{equation}
where $C$ is an absolute constant. For any $\sigma\in \mathbb{R}$, the inverse Laplace transform formula says that
\begin{equation*}
W^m(t) = \frac{1}{2\pi i}\int_{\sigma - i\infty}^{\sigma+i\infty} \widetilde{W^m}(z) e^{zt} dz.
\end{equation*}
We use this formula for each term $W^{m_{k}}\big(\omega_{\mathcal{P}}(\mathbf{n}+\alpha_{k})\big)$. Interchanging the integrals and the expected value, the expression $E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R)$ can thus be rewritten as a $K_0$-fold integral 
\begin{equation*}
\iint_{\substack{z_1,\dots,z_{K_0}\\ \mathrm{Re}(z_{k})=\sigma}}  \mathbb{E} \left[ \prod_{p\mid \fprod{\boldsymbol{d}; \mathcal{S}}} \left(\ind{p\mid \mathbf{n}+b(p)} - \frac{1}{p} \right)\prod_{k \leqslant K_0}\exp \bigg(z_{k} \sum_{p\in \mathcal{P}}\ind{p\mid \mathbf{n} + \alpha_{k}}\bigg) \ind{\substack{\mathbf{n}\in R\qquad\qquad\ \\ \pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \,\\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right] \prod_{k \leqslant K_0} \frac{\widetilde{W^{m_{k}}}(z_{k})}{2\pi i} \, dz_{k}.
\end{equation*}

By independence of the variables $\mathbf{n} \!\pmod p$ for different primes $p$, we can rewrite $E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R)$ as
\begin{equation}
\label{eq:cancel1}
\iint_{\substack{z_1,\dots,z_{K_0}\\ \mathrm{Re}(z_{k})=\sigma}} 
 \prod_{\substack{p\mid \fprod{\boldsymbol{d}; \mathcal{S}}\\ p\nmid q_R}} \mathbb{E} \left[\left(\ind{p \mid \mathbf{n}+b(p)} - \frac{1}{p}\right) \exp \bigg(\sum_{k \leqslant K_0} z_{k} \ind{p\mid \mathbf{n} + \alpha_{k}}\bigg) \right] \cdot Z \cdot
  \prod_{k \leqslant K_0}\frac{\widetilde{W^{m_{k}}}(z_{k})}{2\pi i} \, dz_{k},
\end{equation}
where
\begin{equation*}
Z =  \mathbb{E} \left[\ind{\substack{\mathbf{n}\in R\qquad\qquad\ \\ \pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \,\\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}}  \,\prod_{\substack{p\mid \fprod{\boldsymbol{d}; \mathcal{S}}\\ p \mid q_{R}}}\left(\ind{p \mid \mathbf{n}+b(p)} - \frac{1}{p}\right)  \prod_{\substack{p\in \mathcal{P}\\ p\nmid \frac{\fprod{\boldsymbol{d}; \mathcal{S}}}{(\fprod{\boldsymbol{d}; \mathcal{S}}, q_R)}}} \exp \bigg(\sum_{k \leqslant K_0} z_{k} \ind{p\mid \mathbf{n} + \alpha_{k}}\bigg)  \right].
\end{equation*}
We choose $\sigma = {-1}/{T}$; as this is negative we can bound $Z$ trivially by 
\begin{equation}
\label{eq:cancel2}
|Z| \leqslant \mathbb{E} \left[ \ind{\substack{\mathbf{n}\in R\qquad\qquad\ \\ \pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L}}}\right] \leqslant \prod_{p\mid q_{R}\fprod{\boldsymbol{d}; \mathcal{L}}} \frac 1p.
\end{equation}

We now estimate
\begin{equation}
\label{eq:expectationtocompute}
	\mathbb{E} \left[\left(\ind{p \mid \mathbf{n}+b(p)} - \frac{1}{p}\right) \exp \bigg(\sum_{k \leqslant K_0} z_{k} \ind{p\mid \mathbf{n} + \alpha_{k}}\bigg) \right]
\end{equation}
for each $p \mid \frac{\fprod{\boldsymbol{d}; \mathcal{S}}}{(\fprod{\boldsymbol{d}; \mathcal{S}}, q_R)}$ (this simply means that $p\mid \fprod{\boldsymbol{d}; \mathcal{S}}$ and $p\nmid q_R$ as $\fprod{\boldsymbol{d}; \mathcal{S}}$ and $q_R$ are square-free). For such a prime $p$, define 
\begin{equation}
\label{eq:insingleproof}
M_{p} := \{k \leqslant K_0 : p\mid \alpha_{k} - b(p)\}.
\end{equation}
We can directly compute that 
\begin{equation*}
	\mathbb{E} \left[\ind{\mathbf{n} \equiv -b(p) \!\!\!\!\pmod{p}} \left(\ind{p \mid \mathbf{n}+b(p)} - \frac{1}{p}\right) \exp \bigg(\sum_{k \leqslant K_0} z_{k} \ind{p\mid \mathbf{n} + \alpha_{k}}\bigg) \right] = \frac{1}{p} \left(1- \frac{1}{p}\right) \exp \bigg(\sum_{k \in M_p} z_{k}\bigg),
\end{equation*}
and
\begin{equation*}
	\mathbb{E} \left[\ind{\mathbf{n} \not\equiv -\alpha_1,\ldots, -\alpha_{K_0} \!\!\!\!\pmod{p}} \left(\ind{p \mid \mathbf{n}+b(p)} - \frac{1}{p}\right) \exp \bigg(\sum_{k \leqslant K_0} z_{k} \ind{p\mid \mathbf{n} + \alpha_{k}}\bigg) \right] =  \left(1- \frac{O(K_0)}{p}\right) \frac{-1}{p}.
\end{equation*}
Finally, the contribution for when $\mathbf{n} \equiv -\alpha_k \pmod{p}$ for some $\alpha_k \not\equiv b(p) \pmod{p}$ is $O(K_0/p^2)$. We conclude that \cref{eq:expectationtocompute} is
\begin{equation*}
	\frac{1}{p} \left(1- \frac{1}{p}\right) \exp \bigg(\sum_{k \in M_p} z_{k}\bigg) - \frac{1}{p} + O \bigg(\frac{K_0}{p^2}\bigg) = \frac{1}{p} \bigg( \exp \bigg(\sum_{k \in M_p}z_{k}\bigg) - 1\bigg) + O \bigg(\frac{K_0}{p^2}\bigg).
\end{equation*}
Observe that $\left|\exp \left(\sum_{k \in M_p} z_{k} \right)-1\right| \geqslant \left| \exp \left( -\sum_{k \in M_p} \tfrac{1}{T} \right) - 1 \right| \gg T^{-1}$. This is $\geqslant K_0/p$ by our choices of parameters, since $p\geqslant H_0$ and $T = J V$. Therefore,
\begin{equation}
\label{eq:cancel3}
\mathbb{E} \left[\left(\ind{p \mid \mathbf{n}+b(p)} - \frac{1}{p}\right) \exp \bigg(\sum_{k \leqslant K_0} z_{k} \ind{p\mid \mathbf{n} + \alpha_{k}}\bigg) \right] \ll \frac{1}{p} \Bigg|\exp \bigg(\sum_{\substack{k \in M_p} }z_{k}\bigg)-1\Bigg|.
\end{equation}
Substituting \cref{eq:cancel2,eq:cancel3} into \cref{eq:cancel1}, we obtain that $E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R)$ is, in absolute value, at most 
\begin{equation}
\label{eq:remainingint}
e^{O(|\mathcal{S}|)} \Bigg(\prod_{p\mid q_{R} \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}} \frac 1p\Bigg) \iint_{\substack{z_1,\dots,z_{K_0}\,\,\,\,\,\,\,\,\,\\ \mathrm{Re}(z_{k})=-1/T}}  \, \prod_{\substack{p\mid \fprod{\boldsymbol{d}; \mathcal{S}}\\ p\nmid q_R}} \Bigg|\exp \bigg(\sum_{\substack{k \in M_p} }z_{k}\bigg)-1\Bigg|   \prod_{k \leqslant K_0} \abs{\widetilde{W^{m_{k}}}(z_{k})} |dz_{k}|.
\end{equation}

To bound the expression $\lvert\exp (\sum_{\substack{k \in M_p} }z_{k})-1\rvert$ non-trivially, we decompose the ranges of integration to be able to tell when each $z_k$ is small or large. The multiple integral in \cref{eq:remainingint} is thus
\begin{equation}
\label{eq:remainingint2}
\sum_{X \subset \sinterval{K_0}}  \iint_{\substack{\\ z_1,\dots,z_{K_0} \,\,\,\,\,\, \,\,\,\,\,\,\,\,\,  \,\,\,\,\,\,\,\,\, \\ \mathrm{Re}(z_{k})=-1/T \qquad \\ \!\!\!\! |z_{k}|\leqslant V^{-1/2}\, \forall k \in X\\ \!\!\!\! |z_{k}|> V^{-1/2}\, \forall k \notin X}} \prod_{\substack{p\mid \fprod{\boldsymbol{d}; \mathcal{S}}\\ p\nmid q_R}} \Bigg|\exp \bigg(\sum_{k \in M_p} z_{k}\bigg)-1\Bigg|   \prod_{k \leqslant K_0} |\widetilde{W^{m_{k}}}(z_{k}) |  |dz_{k}|.
\end{equation}
Thus $X$ is the set of all $k\in \sinterval{K_0}$ such that $|z_k| \leqslant V^{-1/2}$. By Taylor expansion, we have
\begin{equation*}
\Bigg|\exp \bigg(\sum_{k \in M_p} z_{k} \bigg)-1\Bigg| \ll \begin{cases}
 \sum_{k \in M_p} |z_{k}| \ll V^{-1/2} &\text{if }M_p\subset X\text{ and }|M_p| \leqslant 2,\\
 1 &\text{otherwise.}
\end{cases}
\end{equation*}
Thus, \cref{eq:remainingint2} is bounded by
\begin{equation}
\label{eq:laplace3}
e^{O(|\mathcal{S}|)}\!\!\!\sum_{\substack{X \subset \sinterval{K_0} }} \bBigg@{4}[\prod_{\substack{p \mid \frac{\fprod{\boldsymbol{d}; \mathcal{S}}}{(\fprod{\boldsymbol{d}; \mathcal{S}}, q_R)}\\ M_p\subset X,\  |M_p|\leqslant 2}}\!\!\!\!\!\!  V^{-1/2} \bBigg@{4}] \prod_{k \in X}\bigg(\int_{I_{\leqslant}} |\widetilde{W^{m_{k}}}(z)| |dz|\bigg)\prod_{k \notin X} \bigg(\int_{I_>} |\widetilde{W^{m_{k}}}(z)| |dz|\bigg),
\end{equation}
where $I_{\leqslant} = \left\{z: \mathrm{Re}(z)=-1/T,\ |z|\leqslant  V^{-1/2}\right\}$ and $I_{>} =\left\{z: \mathrm{Re}(z)=-1/T,\ |z|>  V^{-1/2}\right\}$.

By \cref{eq:derivativeboundLaplace} with $a=2$, we have
\begin{equation*}
\int_{I_{\leqslant}} |\widetilde{W^{m_{k}}}(z)||dz| \ll \frac{2^{m_{k}}}{T} \int_{\mathrm{Re}(z)={-1/T}} {|z|^{-2}} |dz| \ll 2^{m_{k}}.
\end{equation*}
For the integral over $I_>$ we have, for any $a\geqslant 2$, using \cref{eq:derivativeboundLaplace},
\begin{equation*}
\int_{I_>} |\widetilde{W^{m_{k}}}(z)||dz| \ll 2^{m_{k}}\frac{(Ca)^{a}}{T^{a-1}} \int_{I_>} {|z|^{-a}} |dz| \ll 2^{m_{k}}  \left(\frac{C aV^{1/2}}{T}\right)^{a-1}. 
\end{equation*}
Choosing $a = \left\lfloor {T}/{(eCV^{1/2})} \right\rfloor$, we obtain the bound
\begin{equation*}
\int_{I_>} |\widetilde{W^{m_{k}}}(z)||dz| \ll 2^{m_{k}} e^{- a} \leqslant 2^{m_{k}} V^{-J},
\end{equation*}
where the last inequality holds provided that $V$ is larger than some absolute constant, which is the case if $\varepsilon_1$ is sufficiently small, by \cref{lem:primesets}. 

Notice that $\prod_{k \leqslant K_0} 2^{m_{k}} = 2^{K}$. Putting everything together, we deduce that \cref{eq:laplace3} is at most
\begin{equation}
\label{eq:laplace4}
 e^{O(K J)} \sum_{\substack{X \subset \sinterval{K_0} }}\bBigg@{4}[\prod_{\substack{p \mid \frac{\fprod{\boldsymbol{d}; \mathcal{S}}}{(\fprod{\boldsymbol{d}; \mathcal{S}}, q_R)}\\ M_p\subset X,\  |M_p|\leqslant 2}}\!\!\!\!\!\!  V^{-1/2} \bBigg@{4}]  \big(V^{-J}\big)^{K_0 - |X|}.
\end{equation}
 We claim that
\begin{equation}
\label{eq:countingineq}
\abs{ \left\{p \mid \tfrac{\fprod{\boldsymbol{d}; \mathcal{S}}}{(\fprod{\boldsymbol{d}; \mathcal{S}}, q_R)} : M_p \subset X,\, |M_p| \leqslant 2\right\} } \geqslant |\mathcal{S}| - 2 J (K_0 - |X|) - O\big(K^{1-\varepsilon_1}\big).
\end{equation}
Assuming \cref{eq:countingineq}, we conclude that \cref{eq:laplace4} is bounded by
\begin{equation*}
 e^{O(K J)}\!\!\! \sum_{\substack{X\subset \sinterval{K_0} }}V^{-|\mathcal{S}|/2} V^{J(K_0- |X|)}V^{O(K^{1-\varepsilon_1})}  \big(V^{-J}\big)^{K_0 - |X|} \ll  e^{O(K J)} V^{-|\mathcal{S}|/2},
\end{equation*}
which implies the desired bound on $E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R)$.

It remains to prove \cref{eq:countingineq}. This is where we will use our assumptions on $q_R$ and on the number of bad single indices. Since $q_{R}$ has at most $K^{1-\varepsilon_1}$ prime factors $p\mid \fprod{\boldsymbol{d}; \mathcal{S}}$, we have 
\begin{align*}
\abs{ \left\{p \mid \tfrac{\fprod{\boldsymbol{d}; \mathcal{S}}}{(\fprod{\boldsymbol{d}; \mathcal{S}}, q_R)} : M_p \subset X,\, |M_p| \leqslant 2\right\} } &\geqslant  \abs{ \{p\mid \fprod{\boldsymbol{d}; \mathcal{S}} :  M_p \subset X,\, |M_p| \leqslant 2\} } - K^{1-\varepsilon_1}\\
&\geqslant |\mathcal{S}| - \abs{ \{p\mid \fprod{\boldsymbol{d}; \mathcal{S}} :  M_p \not\subset X\} }  - \abs{ \{p\mid \fprod{\boldsymbol{d}; \mathcal{S}} :  |M_p|>2\}} -K^{1-\varepsilon_1}.
\end{align*}
Observe that $\{p\mid \fprod{\boldsymbol{d}; \mathcal{S}} :  |M_p|>2\}\subset \mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})$. Indeed, suppose that $(i,j)\in \mathcal{S}$ is such that $|M_{\pcomp{i}{j}}|>2$. This implies that there are elements $i_1, i_2, i_3\in \sinterval{K}$ with $b_{i_1}, b_{i_2}, b_{i_3}$ pairwise distinct such that 
\begin{equation*}
b_{i_1} - b_{i} \equiv b_{i_2} - b_{i} \equiv b_{i_3} - b_{i} \equiv 0 \pmod{\pcomp{i}{j}}.
\end{equation*}
Since $b_{i_1}, b_{i_2}, b_{i_3}$ are distinct, one of them is not in $\{b_i, b_{i+1}\}$. By case \cref{item:bad3} of \cref{def:badsingle}, this is only possible if $(i,j)\in \mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})$. Recall that $\abs{\mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})} \leqslant K^{1/2}$ by assumption. Therefore,
\begin{equation*}
\abs{ \left\{p \mid \tfrac{\fprod{\boldsymbol{d}; \mathcal{S}}}{(\fprod{\boldsymbol{d}; \mathcal{S}}, q_R)} : M_p \subset X,\, |M_p| \leqslant 2\right\} }  \geqslant |\mathcal{S}| -  \abs{ \{p\mid \fprod{\boldsymbol{d}; \mathcal{S}} :  M_p \not\subset X\} }  -O\big(K^{1-\varepsilon_1}\big).
\end{equation*}
Hence, to prove \cref{eq:countingineq}, it suffices to show that, for all $j\in \sinterval{J}$ and $k \in \sinterval{K_0} \setminus X$,
\begin{equation*}
\abs{\{ i\in \sinterval{K} : (i,j)\in \mathcal{S}\setminus \mathcal{S}_{\mathrm{bad}}(\boldsymbol{d}),\, M_{\pcomp{i}{j}}\ni k\} } \leqslant 2.
\end{equation*}
Suppose otherwise. Then, there are distinct $i_1, i_2, i_3\in \sinterval{K}$ with ${(i_1,j), (i_2,j), (i_3,j)\in \mathcal{S}\setminus \mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})}$, and moreover $\pcomp{i_1}{j} \mid \alpha_{k} - b_{i_1}$, $\pcomp{i_2}{j} \mid \alpha_{k} - b_{i_2}$ and $\pcomp{i_3}{j} \mid \alpha_{k} - b_{i_3}$. By case \cref{item:bad3} of \cref{def:badsingle}, these divisibilities imply that 
\begin{equation*}
\alpha_{k} \in \{b_{i_1},b_{i_1+1} \} \cap \{b_{i_2},b_{i_2+1} \} \cap \{b_{i_3},b_{i_3+1} \}.
\end{equation*}
However, this intersection is empty by cases \cref{item:bad1} and \cref{item:bad2} of \cref{def:badsingle}. This is a contradiction. This finishes the proof of \cref{eq:countingineq} and hence that of \cref{prop:cancellationAP}.

