\label{def:Qintersect}
Let $\boldsymbol{d} \in \mathbf{D}^{\mathcal{S}}_{\!K}$ and let $\boldsymbol{b}$ be the associated vector of partial sums. We write 
\begin{equation*}
{\mathcal{Y}-\boldsymbol{b} := \{P-b_i : P \in \mathcal{Y}, \,i\in \sinterval{K}\}}.
\end{equation*}
We also define 
\begin{equation*}
(\mathcal{Y}-\boldsymbol{b})^{\cap} := \bigg\{\bigcap_{P\in X}P : X \subset \mathcal{Y}-\boldsymbol{b}\bigg\},
\end{equation*}
the set of all possible intersections of such shifted progressions (with the convention $\bigcap_{P\in \emptyset}P := \mathbb{Z}$).

\label{lem:existencerank}
Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $\sinterval{K}\times\sinterval{J} = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$. For every $\boldsymbol{d} \in \mathbf{D}^{\mathcal{S}}_{\!K}$, there exists a function 
\begin{equation*}
	\mathrm{rank}_{\boldsymbol{d}} : (\mathcal{Y}-\boldsymbol{b})^{\cap} \to \mathbb{Z}^{\geqslant 0} \cup \{+\infty\}
\end{equation*}
satisfying the following properties. 

Define the arithmetic progression $A_{\boldsymbol{d}} := \{n\in \mathbb{Z} : \forall (i,j)\in \mathcal{L}, \ \pcomp{i}{j} \mid n+b_i\}$. 

Let~$X_{\boldsymbol{d}}$ be the set of all $R\in (\mathcal{Y}-\boldsymbol{b})^{\cap}$ such that ${\mathrm{rank}_{\boldsymbol{d}}(R) < K^{5\varepsilon_1}}$. Let $\partial X_{\boldsymbol{d}}$ be the set of all $R\in (\mathcal{Y}-\boldsymbol{b})^{\cap}\setminus X_{\boldsymbol{d}}$ of the form $R = R'\cap P$ for some $R'\in X_{\boldsymbol{d}}$ and $P\in \mathcal{Y}-\boldsymbol{b}$.
\begin{enumerate}
	\item \label{item:rank2} (Primes dividing the modulus) For every $R\in (\mathcal{Y}-\boldsymbol{b})^{\cap}$, 
	\begin{equation*}
		\omega(q_{R}) \leqslant L J \, \mathrm{rank}_{\boldsymbol{d}}(R) + K J.
	\end{equation*}
	\item \label{item:rank2bis} (Primes $p\mid \fprod{\boldsymbol{d}; \mathcal{S}}$ dividing the modulus) For every $R\in (\mathcal{Y}-\boldsymbol{b})^{\cap}$, 
	\begin{equation*}
		\abs{ \{p: p\mid q_{R},\, p\mid \fprod{\boldsymbol{d}; \mathcal{S}}\}}\leqslant L J \, \mathrm{rank}_{\boldsymbol{d}}(R).
	\end{equation*}
	\item \label{item:ranksieve} (Combinatorial sieve) Let $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S}}_{\!K}$. For all $n\in \mathbb{Z}$, we have 
	\begin{equation*}
		\ind{\substack{\forall i,\,n+b_i \in Y_{\!L} \, \mathrm{ and }\, n\in A_{\boldsymbol{d}}}}  = \sum_{\substack{R\in X_{\boldsymbol{d}}}} c_{R,\boldsymbol{d}}  \ind{n\in R\cap A_{\boldsymbol{d}}}\,  +\,  O\Bigg(  3^{3K J}  \!\!\!\! \sum_{\substack{R\in \partial X_{\boldsymbol{d}} \\ R\cap A_{\boldsymbol{d}} \neq \emptyset}} \!\!\!\! \ind{n\in R\cap A_{\boldsymbol{d}}} \Bigg),
	\end{equation*}
	where the coefficients $c_{R,\boldsymbol{d}}$ are independent of $n$ and satisfy $|c_{R,\boldsymbol{d}}| \leqslant 2^{2K J}$.
	\item \label{item:rank4} (Main term bound) We have
        \begin{equation*}
        		\sum_{\substack{R\in X_{\boldsymbol{d}}}} \prod_{\substack{p\mid q_{R}\\ p\nmid \fprod{\boldsymbol{d}}}}\frac{1}{p} \ll e^{O(K J)}.
        \end{equation*}
	\item \label{item:rank3} (Remainder term bound) Suppose $|\mathcal{U}| \leqslant K^{2\varepsilon_1}$. Then
	\begin{equation*}
	 \sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}}} \sum_{\substack{R\in \partial X_{\boldsymbol{d}} \\ R\cap A_{\boldsymbol{d}} \neq \emptyset}}\, \prod_{\substack{p\mid q_{R} \fprod{\boldsymbol{d}}}}\frac{1}{p} \ll 1.
	 \end{equation*}
\end{enumerate}

\begin{equation*}
		\ind{\substack{\forall i,\,n+b_i \in Y_{\!L} \, \mathrm{ and }\, n\in A_{\boldsymbol{d}}}}  = \sum_{\substack{R\in X_{\boldsymbol{d}}}} c_{R,\boldsymbol{d}}  \ind{n\in R\cap A_{\boldsymbol{d}}}\,  +\,  O\Bigg(  3^{3K J}  \!\!\!\! \sum_{\substack{R\in \partial X_{\boldsymbol{d}} \\ R\cap A_{\boldsymbol{d}} \neq \emptyset}} \!\!\!\! \ind{n\in R\cap A_{\boldsymbol{d}}} \Bigg),
	\end{equation*}

By \cref{lem:summaryfourlemmas}, we have
\begin{equation}
\label{eq:summaryfourlemmas}
	\mathrm{Tr} \big((\mathrm{Ad}_{G})^{K}\big) \leqslant e^{O(KJ)}N \bBigg@{3}( 1+ \sup_{\substack{\mathcal{S}\sqcup \mathcal{L}\sqcup \mathcal{U} = \sinterval{K}\times\sinterval{J}\\ |\mathcal{U}| <K^{2\varepsilon_1}}}\, \sum_{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}}\abs{ \mathbb{E} \left[w_{\boldsymbol{d}}(\mathbf{n}) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right] }\bBigg@{3}).
\end{equation}
We can ignore those $\boldsymbol{d}$ for which $|{\mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})}| >K^{1/2}$ as, by the triangle inequality and \cref{lem:badsingle},
\begin{equation*}
\sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}\\ |{\mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})}| >K^{1/2}}}\abs{\mathbb{E} \left[w_{\boldsymbol{d}}(\mathbf{n}) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right] }\leqslant \sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}\\ |{\mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})}| >K^{1/2}}} \prod_{p\mid \fprod{\boldsymbol{d}}} \frac{1}{p} \ll 1.
\end{equation*}
Thus, \cref{eq:summaryfourlemmas} becomes
\begin{equation}
\label{eq:aftersbad}
\mathrm{Tr} \big((\mathrm{Ad}_{G})^{K}\big) \leqslant e^{O(KJ)}N \bBigg@{3}( 1+ \sup_{\substack{\mathcal{S}\sqcup \mathcal{L}\sqcup \mathcal{U} = \sinterval{K}\times\sinterval{J}\\ |\mathcal{U}| <K^{2\varepsilon_1}}}\, \sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}\\ |{\mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})}| \leqslant K^{1/2}}}\abs{ \mathbb{E} \left[w_{\boldsymbol{d}}(\mathbf{n}) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right] } \bBigg@{3}).
\end{equation}

Fix $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}$ with $|{\mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})}| \leqslant K^{1/2}$. By definition of $w_{\boldsymbol{d}}(\mathbf{n})$ we have
\begin{equation*}
\abs{\mathbb{E} \left[w_{\boldsymbol{d}}(\mathbf{n}) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right]} 
\leqslant \Bigg(\prod_{p\mid \fprod{\boldsymbol{d}; \mathcal{U}}} \frac{1}{p}\Bigg) E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}),
\end{equation*}
where $E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d})$ is defined by
\begin{equation*}
E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}) := \mathbb{E} \left[\prod_{i\in \sinterval{K}} \ind{\mathbf{n}+b_i\in Y_{\!L}} W\big(\omega_{\mathcal{P}}(\mathbf{n}+b_i)\big)\prod_{(i,j)\in \mathcal{S}} \left(\ind{\pcomp{i}{j}\mid \mathbf{n} + b_i} - \frac{1}{\pcomp{i}{j}}\right) \ind{\substack{\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L} \\ \pcomp{i}{j}\nmid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{U}}} \right].
\end{equation*}
By part \cref{item:ranksieve} of \cref{lem:existencerank}, we can write
\begin{equation}
\label{eq:usesieve}
E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}) = \sum_{\substack{R\in X_{\boldsymbol{d}}}} c_{R,\boldsymbol{d}}\, E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R) + \sum_{\substack{R\in \partial X_{\boldsymbol{d}} \\ R\cap A_{\boldsymbol{d}} \neq \emptyset}}  O\Big(3^{3K J} \, E_{\mathcal{S},\mathcal{L},\mathcal{U}}^{|\cdot|}(\boldsymbol{d}; R)\Big),
\end{equation} 
with $E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R)$ as defined in \cref{prop:cancellationAP} and 
\begin{equation*}
E_{\mathcal{S},\mathcal{L},\mathcal{U}}^{|\cdot|}(\boldsymbol{d}; R) := \mathbb{E} \bigg[\prod_{(i,j)\in \mathcal{S}} \abs{\ind{\pcomp{i}{j}\mid \mathbf{n} + b_i} - \frac{1}{\pcomp{i}{j}}} \ind{\substack{\mathbf{n}\in R\qquad \qquad\\\pcomp{i}{j}\mid \mathbf{n}+b_i \, \forall (i,j)\in \mathcal{L}}} \bigg] \leqslant \prod_{p\mid q_{R} \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}} \frac{1}{p}.
\end{equation*}

Inserting \cref{eq:usesieve} into \cref{eq:aftersbad} shows that $\mathrm{Tr} \big((\mathrm{Ad}_{G})^{K}\big)$ is bounded by the sum of a main term
\begin{equation}
\label{eq:maintermincomputation}
e^{O(K J)} N \sup_{\substack{\mathcal{S}\sqcup \mathcal{L}\sqcup \mathcal{U} = \sinterval{K}\times\sinterval{J}\\ |\mathcal{U}| <K^{2\varepsilon_1}}}\, \sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K} \\ |{\mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})}| \leqslant K^{1/2}}}\!\!\Bigg(\prod_{p\mid \fprod{\boldsymbol{d}; \mathcal{U}}} \frac{1}{p}\Bigg)\sum_{\substack{R\in X_{\boldsymbol{d}}}}\abs{E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R)}
\end{equation}
and a remainder term which is $\ll e^{O(K J)} N$ since, by part \cref{item:rank3} of \cref{lem:existencerank},
\begin{equation*}
\sum_{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}} \Bigg(\prod_{p\mid \fprod{\boldsymbol{d}; \mathcal{U}}} \frac{1}{p}\Bigg) \sum_{\substack{R\in \partial X_{\boldsymbol{d}} \\ R\cap A_{\boldsymbol{d}} \neq \emptyset}}  \prod_{p\mid q_{R} \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}} \frac{1}{p}
\leqslant\sum_{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}} \sum_{\substack{R\in \partial X_{\boldsymbol{d}} \\ R\cap A_{\boldsymbol{d}} \neq \emptyset}} \, \prod_{\substack{p\mid q_{R} \fprod{\boldsymbol{d}}}}\frac{1}{p}\, \ll\, 1.
\end{equation*}

We now use \cref{prop:cancellationAP} to bound the expression $E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R)$ in \cref{eq:maintermincomputation}. Note that the main condition on the modulus of $R$ in \cref{prop:cancellationAP} is satisfied. Indeed, by part \cref{item:rank2bis} of \cref{lem:existencerank}, we have, for $R\in X_{\boldsymbol{d}}$, 
\begin{equation*}
\abs{ \{p: p\mid q_{R},\, p\mid \fprod{\boldsymbol{d}; \mathcal{S}}\}}\leqslant L J K^{5\varepsilon_1} \leqslant K^{1-10\varepsilon_1} J K^{5\varepsilon_1} \leqslant K^{1-\varepsilon_1}.
\end{equation*}
We obtain
\begin{equation*}
\sum_{\substack{R\in X_{\boldsymbol{d}}}} \abs{E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R)}
\ll e^{O(K J)} V^{-|\mathcal{S}|/2}  \Bigg(\prod_{p\mid \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}}\, \frac{1}{p} \Bigg)  \sum_{\substack{R\in X_{\boldsymbol{d}}}}  \prod_{\substack{p\mid q_{R}\\ p\nmid \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}}}\frac{1}{p}.
\end{equation*}
The sum on the right-hand side is $\ll e^{O(K J)}$ by part \cref{item:rank4} of \cref{lem:existencerank}. Therefore, \cref{eq:maintermincomputation} is at most
\begin{equation*}
e^{O(K J)} N \sup_{\substack{\mathcal{S}\sqcup \mathcal{L}\sqcup \mathcal{U} = \sinterval{K}\times\sinterval{J}\\ |\mathcal{U}| <K^{2\varepsilon_1}}}\, \sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K} \\ |{\mathcal{S}_{\mathrm{bad}}(\boldsymbol{d})}| \leqslant K^{1/2}}}\!\! V^{-|\mathcal{S}|/2} \Bigg(\prod_{p\mid \fprod{\boldsymbol{d}; \mathcal{U}}} \frac{1}{p}\Bigg)  \Bigg(\prod_{p\mid \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}}\, \frac{1}{p} \Bigg).
\end{equation*}
We conclude that 
\begin{equation*}
\mathrm{Tr} \big((\mathrm{Ad}_{G})^{K}\big) \leqslant e^{O(K J)} N \bBigg@{3}(1 + \sup_{\substack{\mathcal{S}\sqcup \mathcal{L}\sqcup \mathcal{U} = \sinterval{K}\times\sinterval{J}\\ |\mathcal{U}| <K^{2\varepsilon_1}}}\,V^{-|\mathcal{S}|/2}  \sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}}}\,\prod_{p\mid \fprod{\boldsymbol{d}}} \frac{1}{p} \bBigg@{3}).
\end{equation*}
To finish the proof, note that the error term $e^{O(K J)} N$ can be absorbed into the term with the supremum. To see why this is true, note that, for $\mathcal{S} = \sinterval{K}\times\sinterval{J}$ and $\mathcal{L}=\mathcal{U}=\emptyset$, we have
\begin{equation*}
V^{-|\mathcal{S}|/2}  \sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}}}\,\prod_{p\mid \fprod{\boldsymbol{d}}} \frac{1}{p} = V^{-KJ/2} \prod_{j\in \sinterval{J}}\bBigg@{3}( \sum_{\substack{p_1, \ldots, p_{K}\in \mathcal{P}_j \\ \text{distinct}}} \prod_{i\in \sinterval{K}} \frac{1}{p_i} \bBigg@{3})  \gg V^{-KJ/2} V^{KJ} \gg 1.\qedhere
\end{equation*}

\begin{equation}
\label{eq:usesieve}
E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}) = \sum_{\substack{R\in X_{\boldsymbol{d}}}} c_{R,\boldsymbol{d}}\, E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R) + \sum_{\substack{R\in \partial X_{\boldsymbol{d}} \\ R\cap A_{\boldsymbol{d}} \neq \emptyset}}  O\Big(3^{3K J} \, E_{\mathcal{S},\mathcal{L},\mathcal{U}}^{|\cdot|}(\boldsymbol{d}; R)\Big),
\end{equation}

\begin{equation*}
\sum_{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}} \Bigg(\prod_{p\mid \fprod{\boldsymbol{d}; \mathcal{U}}} \frac{1}{p}\Bigg) \sum_{\substack{R\in \partial X_{\boldsymbol{d}} \\ R\cap A_{\boldsymbol{d}} \neq \emptyset}}  \prod_{p\mid q_{R} \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}} \frac{1}{p}
\leqslant\sum_{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}} \sum_{\substack{R\in \partial X_{\boldsymbol{d}} \\ R\cap A_{\boldsymbol{d}} \neq \emptyset}} \, \prod_{\substack{p\mid q_{R} \fprod{\boldsymbol{d}}}}\frac{1}{p}\, \ll\, 1.
\end{equation*}

\begin{equation*}
\abs{ \{p: p\mid q_{R},\, p\mid \fprod{\boldsymbol{d}; \mathcal{S}}\}}\leqslant L J K^{5\varepsilon_1} \leqslant K^{1-10\varepsilon_1} J K^{5\varepsilon_1} \leqslant K^{1-\varepsilon_1}.
\end{equation*}

\begin{equation*}
\sum_{\substack{R\in X_{\boldsymbol{d}}}} \abs{E_{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}; R)}
\ll e^{O(K J)} V^{-|\mathcal{S}|/2}  \Bigg(\prod_{p\mid \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}}\, \frac{1}{p} \Bigg)  \sum_{\substack{R\in X_{\boldsymbol{d}}}}  \prod_{\substack{p\mid q_{R}\\ p\nmid \fprod{\boldsymbol{d}; \mathcal{S} \sqcup \mathcal{L}}}}\frac{1}{p}.
\end{equation*}

\label{def:tpredictable}
A word $w\in \mathcal{W}$ is said to be \emph{$t$-predictable} if the following conditions both hold.
\begin{enumerate}
	\item Every letter appears $\leqslant t$ times in $w$.
	\item There are $\leqslant t$ letters with variable neighbours in $w$.
\end{enumerate} 
Otherwise $w$ is called \emph{$t$-unpredictable}.

\label{lem:uniquenesspredict}
Let $n\geqslant 2$ and let $w_1, w_2\in \mathcal{W}_n$. For $i\in \{1, 2\}$, let $L_i \subset \letters{w_i}$ be the set of letters 
\begin{align*}
L_i = &\{w_i[1], w_i[2]\} \cup \{\upletters{A}\in \letters{w_i} : \upletters{A}\text{ has variable neighbours in }w_i\} \\&\quad \cup \{\upletters{B}\in \letters{w_i} : \upletters{B}\text{ appears in $w_i$ next to a letter }\upletters{A}\text{ having variable neighbours in }w_i\}.
\end{align*}
Suppose that $\big\{ \pos{w_1}{\upletters{A}} : \upletters{A} \in L_1 \big\} = \big\{ \pos{w_2}{\upletters{A}} : \upletters{A} \in L_2 \big\}$. Then
\begin{equation*}
\big\{ \pos{w_1}{\upletters{A}} : \upletters{A} \in \letters{w_1} \big\} = \big\{ \pos{w_2}{\upletters{A}} : \upletters{A} \in \letters{w_2} \big\}.
\end{equation*}
In other words, the sets of positions of the letters in $L_1$ uniquely determine the sets of positions of all the letters of $w_1$.

\begin{align*}
L_i = &\{w_i[1], w_i[2]\} \cup \{\upletters{A}\in \letters{w_i} : \upletters{A}\text{ has variable neighbours in }w_i\} \\&\quad \cup \{\upletters{B}\in \letters{w_i} : \upletters{B}\text{ appears in $w_i$ next to a letter }\upletters{A}\text{ having variable neighbours in }w_i\}.
\end{align*}

Suppose that the conclusion does not hold, and let $k\geqslant 1$ be minimal with the property that $\posbis{w_1}{k}\neq \posbis{w_2}{k}$. Hence, $w_1[k] \not\in L_1$ and $w_2[k] \not\in L_2$ by the assumption in the statement. In particular, $k\geqslant 3$ since $w_i[1], w_i[2]\in L_i$. 

Note that $w_1[k]\neq w_1[k-2]$. Indeed, if $w_1[k] = w_1[k-2]$, we would have $k\in \posbis{w_1}{k-2}$, but ${\posbis{w_1}{k-2} = \posbis{w_2}{k-2}}$ by minimality of $k$, so $k\in \posbis{w_2}{k-2}$ and thus $\posbis{w_2}{k} = \posbis{w_1}{k}$ which is not the case, by assumption.

By definition of $L_1$, both $w_1[k]$ and $w_1[k-1]$ have constant neighbours in $w_1$. This means that every occurrence of the letter $w_1[k-1]$ in $w_1$ is surrounded by the letters $w_1[k-2]$ and $w_1[k]$ (in any order). In addition, every appearance of $w_1[k]$ is adjacent to an occurrence of $w_1[k-1]$. Thus, we may describe $\posbis{w_1}{k}$ exactly as
\begin{equation}
\label{eq:expressionPos}
\posbis{w_1}{k} = \big\{l\in \sinterval{n}\  :\  \{l-1, l+1\} \cap \posbis{w_1}{k-1} \neq \emptyset,\  l\not\in \posbis{w_1}{k-2}\big\}.
\end{equation}

The same reasoning with $w_2$ shows that 
\begin{equation}
\label{eq:expressionPos2}
\posbis{w_2}{k} = \big\{l\in \sinterval{n}\  :\  \{l-1, l+1\} \cap \posbis{w_2}{k-1} \neq \emptyset,\  l\not\in \posbis{w_2}{k-2}\big\}.
\end{equation}
However, $\posbis{w_1}{k-2} = \posbis{w_2}{k-2}$ and $\posbis{w_1}{k-1} = \posbis{w_2}{k-1}$ by minimality of $k$, so \cref{eq:expressionPos,eq:expressionPos2} imply that $\posbis{w_1}{k} = \posbis{w_2}{k}$, a contradiction.

\label{lem:countpredict}
Let $n, t\geqslant 1$. There are $\leqslant n^{O(t^3)}$ partitions of $\{1,\ldots, n\}$ of the form 
\begin{equation*}
\big\{ \pos{w}{\upletters{A}} : \upletters{A} \in \letters{w} \big\}
\end{equation*}
for some $t$-predictable word $w\in \mathcal{W}_n$.

By \cref{lem:uniquenesspredict}, it suffices to bound the number of possibilities for the set 
\begin{equation}
\label{eq:prepartition}
\big\{ \pos{w}{\upletters{A}} : \upletters{A} \in L_w \big\},
\end{equation}
where $L_w\subset \letters{w}$ is the set defined in \cref{lem:uniquenesspredict} (with $w$ in place of $w_i$), and $w$ ranges over the set of $t$-predictable words in $\mathcal{W}_n$. 

If $w$ is $t$-predictable, there are $\leqslant t$ letters with variable neighbours. Moreover, every letter appears $\leqslant t$ times, so for every letter \upletters{A} there are $\leqslant 2t$ letters adjacent to an occurrence of \upletters{A}. Thus, the set~$L_w$ has size $\leqslant 2+t+t\cdot 2t \leqslant 5t^2$. For every $\upletters{A}\in L_w$, the set $\pos{w}{\upletters{A}}$ of positions of $\upletters{A}$ in $w$ is a subset of $\sinterval{n}$ of size $\leqslant t$, and there are $\leqslant n^t$ such sets. 

Hence, there are $\leqslant (n^t)^{5t^2}$ possibilities for the set in \cref{eq:prepartition}, which concludes the proof.

\label{def:dnb}
Let $R\geqslant 1$. Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $\sinterval{R}\times \sinterval{J} = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$. 

We define $\widetilde{\mathbf{D}}^{\mathcal{S},\mathcal{L}}_{\!R}$ to be the the set of all $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!R}$ such that $d_{i+1}\neq -d_i$ for all $i\in \sinterval{R-1}$, i.e.~those which are non-backtracking. In particular, by \cref{def:Dss}, every $\boldsymbol{d}\in \widetilde{\mathbf{D}}^{\mathcal{S},\mathcal{L}}_{\!R}$ enjoys the following properties:
\begin{enumerate}
	\item \label{item:litcond1x} Whenever two indices $(i,j), (i',j)\in \mathcal{L}$ are such that $\pcomp{i}{j} = \pcomp{i'}{j}$, we have
	\begin{equation*}
		\pcomp{i}{j} \mid b_{i'} - b_{i}.
	\end{equation*}
	\item \label{item:litcond2x} For every $k\in \sinterval{R}$, there are at most $2JV$ distinct primes $p\mid \fprod{\boldsymbol{d}}$ for which there exists an index $(i,j)\in \mathcal{L}$ such that $p = \pcomp{i}{j}$ and $p\mid b_{i} - b_{k}$.
	\item \label{item:litcond3x} 
	For all $k_1 < k_2$ in $\sinterval{R}$ with $k_2-k_1 < L$ and $\interval{k_1}{k_2} \times \sinterval{J} \subset \mathcal{L}$, neither $(d_{k_1}, d_{k_1+1}, \ldots, d_{k_2})$ nor $(d_{k_2}, d_{k_2-1}, \ldots, d_{k_1})$ are prohibited sequences.
\end{enumerate}
Here we kept the usual notation: for ${(i,j)\in \sinterval{R}\times \sinterval{J}}$, $\pcomp{i}{j}$ is the unique prime in $\mathcal{P}_j$ dividing $d_i$, we write ${b_i := \sum_{k<i}d_{k}}$ and $\fprod{\boldsymbol{d}} := \prod_{i\in \sinterval{R}} d_{i}$.

\label{prop:predictablevector}
Let $1\leqslant R\leqslant K$. Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $\sinterval{R}\times \sinterval{J} = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$. We have
\begin{equation*}
	\sum_{\substack{\boldsymbol{d} \in \mathbf{P}_{\!R}}} \, \prod_{p\mid \fprod{\boldsymbol{d}}} \frac{1}{p} \ll e^{O(KJ)}V^{|\mathcal{S}|+(\abs{\mathcal{L}}+\abs{\mathcal{U}})/2}.
\end{equation*}

Any $\boldsymbol{d}\in \mathbf{P}_{\!R}$ induces a partition $\Pi_{\boldsymbol{d}}$ of $\sinterval{R}\times \sinterval{J}$, where $(i,j)$ and $(i',j')$ are in the same class if and only if $\pcomp{i}{j} = \pcomp{i'}{j'}$. Let us count the number of possible partitions.

Fix some $j\in \sinterval{J}$. Let $r\leqslant R$ be the length of $w_{j,\boldsymbol{d}}$. We know that $w_{j,\boldsymbol{d}}$ is $K^{1/4}$-predictable. By \cref{lem:countpredict}, there are $\leqslant R \cdot R^{O(K^{3/4})} \ll e^{K}$ possibilities for $r$ and for the partition of $\sinterval{r}$ given by
 \begin{equation}
 \label{eq:compressedpartition}
 \big\{\pos{w_{j,\boldsymbol{d}}}{\upletters{A}} : \upletters{A} \in \letters{w_{j,\boldsymbol{d}}} \big\}.
 \end{equation}
Let $\Pi_{j,\boldsymbol{d}}$ be the partition of $\sinterval{R}$ where $i$ and $i'$ are in the same class if and only if $v_{j,\boldsymbol{d}}[i] = v_{j,\boldsymbol{d}}[i']$, i.e.~$\pcomp{i}{j} = \pcomp{i'}{j}$. Since $w_{j,\boldsymbol{d}}$ is the compressed word of $v_{j,\boldsymbol{d}}$, the partition $\Pi_{j,\boldsymbol{d}}$ is uniquely determined by $r$, the partition \cref{eq:compressedpartition} of $\sinterval{r}$, and a sequence $(c_1, c_2, \ldots, c_{r})$ of positive integers summing to $R$ (these $c_i$ correspond to the number of consecutive occurrences of each letter in $v_{j,\boldsymbol{d}}$). There are $\leqslant e^{O(R)}$ vectors of positive integers summing to $R$. Therefore, there are ${\ll e^{K} e^{O(R)} \leqslant e^{O(K)}}$ possibilities for the partition $\Pi_{j,\boldsymbol{d}}$. Since the partitions $(\Pi_{j,\boldsymbol{d}})_{j\in \sinterval{J}}$ determine $\Pi_{\boldsymbol{d}}$, we conclude that there are $\leqslant e^{O(KJ)}$ possible partitions $\Pi_{\boldsymbol{d}}$ of $\sinterval{R}\times \sinterval{J}$. 

Observe that any $\boldsymbol{d} \in \mathbf{P}_{\!R}$ is fully determined by the signs of its coordinates $d_i$, the partition $\Pi_{\boldsymbol{d}}$ and the assignment of a prime $p$ to every class $\alpha$ of this partition, with $p\in \mathcal{P}_j$ when $\alpha\subset \sinterval{R}\times \{j\}$. 

Fix a partition $\Pi$ of $\sinterval{R}\times \sinterval{J}$ and a sequence of signs $\sigma\in \{\pm1\}^{R}$. For any $\boldsymbol{d} \in \mathbf{P}_{\!R}$ with $\Pi_{\boldsymbol{d}} = \Pi$, the number of distinct primes dividing $\fprod{\boldsymbol{d}}$ is $\leqslant |\mathcal{S}| + \tfrac{1}{2}(\abs{\mathcal{L}}+\abs{\mathcal{U}})$, as every $\pcomp{i}{j}$ with $(i,j)\not\in \mathcal{S}$ appears at least twice. Thus, the contribution of $\prod_{p\mid \fprod{\boldsymbol{d}}} \frac{1}{p}$ of all $\boldsymbol{d}$ with partition $\Pi_{\boldsymbol{d}} = \Pi$ and signs $(\mathrm{sign}(d_i))_{i\in \sinterval{R}} = \sigma$ is bounded by $V^{|\mathcal{S}|+(\abs{\mathcal{L}}+\abs{\mathcal{U}})/2}$ (since ${\sum_{p\in \mathcal{P}_j}1/p = V_j\leqslant V}$ for every $j$). 

Thus, we obtain
\begin{equation*}
	\sum_{\substack{\boldsymbol{d} \in \mathbf{P}_{\!R}}} \, \prod_{p\mid \fprod{\boldsymbol{d}}} \frac{1}{p} \leqslant 2^{K} e^{O(KJ)}V^{|\mathcal{S}|+(\abs{\mathcal{L}}+\abs{\mathcal{U}})/2}
\end{equation*}
as desired.

\label{lem:unpredictable}
Let $1\leqslant R\leqslant K$. Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $\sinterval{R}\times \sinterval{J} = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$ and $|\mathcal{U}| \leqslant K^{2\varepsilon_1}$. We have
\begin{equation*}
 \sum_{\substack{\boldsymbol{d}\in \mathbf{U}_{\!R}}}\,\prod_{p\mid \fprod{\boldsymbol{d}}}\, \frac{1}{p} \ll 1.
\end{equation*}

\label{def:constraints}
Let $R \geqslant 1$ and let $\boldsymbol{d} \in (\pm \mathcal{D})^{R}$. For $(i,j)\in \sinterval{R} \!\times\! \sinterval{J}$, write $\pcomp{i}{j}$ for the unique prime in $\mathcal{P}_j$ dividing $d_i$. Thus $\abs{d_i} = \prod_{j\in \sinterval{J}} \pcomp{i}{j}$. As before, we set $\fprod{\boldsymbol{d}} := \prod_{i\in \sinterval{R}}d_i$.

We define a \emph{constraint} on $\boldsymbol{d}$ to be any predicate of the form 
\begin{equation}
\label{eq:shapeofconstraint}
	\pcomp{i_0}{j_0} \ \Big\vert\  \sum_{i\in I} d_i + \kappa
\end{equation}
for some $I\subset \sinterval{R}$, $(i_0, j_0)\in \sinterval{R}\! \times\! \sinterval{J}$ and $\kappa\in \mathbb{Z}$. We denote this constraint by $C_{I, i_0,j_0,\kappa}(\boldsymbol{d})$.

\label{def:system}
A \emph{triangular system of $T$ constraints} on $\boldsymbol{d}$ is a sequence $C_1(\boldsymbol{d}), \ldots, C_{T}(\boldsymbol{d})$ of constraints on $\boldsymbol{d}$ such that, for each $t\in \sinterval{{T}}$, there is a prime $p_t$ involved in $C_t(\boldsymbol{d})$ and absent from $C_1(\boldsymbol{d}), C_2(\boldsymbol{d}), \ldots, C_{t-1}(\boldsymbol{d})$.

We will say that a triangular system of constraints on $\boldsymbol{d}$ has \emph{complexity $(T; c, B)$} if it is of the form $\big(C_{I_t, i_t, j_t, \kappa}(\boldsymbol{d})\big)_{t\in \sinterval{T}}$, where each $I_t$ is a union of at most $c$ discrete intervals, and $\abs{\kappa}\leqslant B$ (in particular, this integer $\kappa$ is the same for all constraints).

\label{lem:constraints}
Let $1\leqslant T \leqslant R\leqslant 2 K$. Let $B\geqslant 1$. Let $\mathbf{T}\subset (\pm \mathcal{D})^{R}$ be a set such that each $\boldsymbol{d} \in \mathbf{T}$ satisfies a triangular system of complexity $(T; 3, B)$ (thus, the system may depend on $\boldsymbol{d}$). Then 
\begin{equation*}
	\sum_{\boldsymbol{d}\in \mathbf{T}} \prod_{p\mid \fprod{\boldsymbol{d}}} \frac1p \ll B K^{11R J} H_0^{-T/2}.
\end{equation*}

\label{def:repetitions}
A word $w\in \mathcal{W}$ contains $n$ \emph{separated repetitions} if it has a substring of the form
\begin{equation*}
\upletters{A\makesubscript{1}\ldots A\makesubscript{1}\ldots A\makesubscript{2}\ldots A\makesubscript{2}\ldots$\cdots$\ldots A\makesubscript{n}\ldots A\makesubscript{n}},
\end{equation*}
for some non-necessarily distinct letters \upletters{A\makesubscript{1}$,\ldots,$A\makesubscript{n}}. The three dots \upletters{\ldots} represent a string of letters of arbitrary length (possibly empty). In other words, there are $k_1<l_1<k_2<...<k_n<l_n$ such that $w[k_i]=w[l_i]$ for all $i$.

\label{lem:unpredstep0}
Let $m \geqslant 10$. Let $k_1<k_2<\ldots<k_{m}$ be positive integers. Let $w\in \mathcal{W}$ be a word of length $\geqslant k_{m}$. Then, either $w$ contains $\gg m^{1/2}$ separated repetitions, or there are $i,j\in \sinterval{m}$ with $j-i \gg m^{1/2}$ such that the substring 
\begin{equation*}
	w[k_i]w[k_{i}+1] \cdots w[k_j]
\end{equation*}
of $w$ has distinct letters.

\label{lem:unpredstep1}
Let $\upletters{A}, \upletters{B}, \upletters{C}\in \mathcal{A}$. Let $w_1, w_2\in \mathcal{W}^{\neq}$ be two words of the form
\begin{equation*}
\upletters{A\ldots B\ldots C}.
\end{equation*}
Suppose that \upletters{B} has variable neighbours in the concatenation $w_1w_2$ (this just means that the two letters adjacent to \upletters{B} in $w_1$ are not the same as the two letters adjacent to \upletters{B} in $w_2$).

Then, there exist substrings $v_1 \sqsubset w_1$ and $v_2 \sqsubset w_2$, both of the form $\upletters{A\ldots Y}$ for some letter \upletters{Y} (possibly equal to \upletters{B} or \upletters{C}), with distinct sets of letters (i.e.~$\letters{v_1} \neq \letters{v_2}$).

If $\letters{w_1} 
eq \letters{w_2}$, we can just take $v_1 := w_1$, $v_2 := w_2$ and $\upletters{Y} := \upletters{C}$. 

Otherwise, $w_1$ and $w_2$ have the same sets of letters, and thus the same length as $w_1, w_2\in \mathcal{W}^{
eq}$. Let $k\geqslant 2$ be minimal such that $w_1[k] 
eq w_2[k]$. We know that $k$ exists, since $w_1
eq w_2$. We set $\upletters{X} := w_1[k]$ and $\upletters{Y} := w_2[k]$. The letter \upletters{Y} is present in $w_1$ as both words have the same letters. By minimality of $k$, we must have $\upletters{Y} = w_1[l]$ for some $l>k$. Set ${v_1 := w_1[1]w_1[2]\cdots w_1[l] = \upletters{A\ldots X\ldots Y}}$ and $v_2 := w_2[1]w_2[2]\cdots w_2[k] = \upletters{A\ldots Y}$. Then $\letters{v_1}
eq \letters{v_2}$ as $\upletters{X} \in \letters{v_1}\setminus \letters{v_2}$.

\label{lem:unpredstep2}
Let $m\geqslant 1$. Let $\upletters{A\makesubscript{0}}, \ldots, \upletters{A\makesubscript{2m}}\in \mathcal{A}$. Let $w_1,w_2\in \mathcal{W}^{\neq}$ be two words of the form
\begin{equation*}
\upletters{A\makesubscript{0}\ldots A\makesubscript{1}\ldots A\makesubscript{2}\ldots$\cdots$\ldots A\makesubscript{2m}}
\end{equation*}
such that, for all $1\leqslant i\leqslant 2m-1$, the letter \upletters{A\makesubscript{i}} has variable neighbours in the concatenation $w_1w_2$. 

Then, there are substrings $v_1 \sqsubset w_1$ and $v_2 \sqsubset w_2$, both of the form
\begin{equation*}
\upletters{Y\makesubscript{0}\ldots Y\makesubscript{1}\ldots Y\makesubscript{2}\ldots$\cdots$\ldots Y\makesubscript{m}},
\end{equation*}
for some letters $\upletters{Y\makesubscript{0}},\ldots,\upletters{Y\makesubscript{m}}$ (possibly equal to some of the $\upletters{A\makesubscript{i}}$) such that, for all $j\in \sinterval{m}$, the sets of letters of $v_1|_{\upletters{Y\makesubscript{j\!-\!1}\ldots Y\makesubscript{j}}}$ and $v_2|_{\upletters{Y\makesubscript{j\!-\!1}\ldots Y\makesubscript{j}}}$ are distinct.

Set $\upletters{Y\makesubscript{0}} := \upletters{A\makesubscript{0}}$. Let $w_1^{1} := w_1|_{\upletters{Y\makesubscript{0}\ldots A\makesubscript{1}\ldots A\makesubscript{2}}}$  and $w_2^1 := w_2|_{\upletters{Y\makesubscript{0}\ldots A\makesubscript{1}\ldots A\makesubscript{2}}}$. Applying \cref{lem:unpredstep1} to these words $w_1^{1}$ and $w_2^{1}$, we find two further substrings $v_1^1 \sqsubset w_1^1$ and $v_2^1 \sqsubset w_2^1$ of the form $\upletters{Y\makesubscript{0}\ldots Y\makesubscript{1}}$ for some common ending letter $\upletters{Y\makesubscript{1}}$, such that $\letters{v_1^1} \neq \letters{v_2^1}$. Notice that $w_1$ and $w_2$ are of the form 
\begin{equation*}
\upletters{Y\makesubscript{0}\ldots Y\makesubscript{1}\ldots A\makesubscript{3}\ldots A\makesubscript{4}\ldots$\cdots$\ldots A\makesubscript{2m}}.
\end{equation*}
We may thus define the substrings $w_1^2 := w_1|_{\upletters{Y\makesubscript{1}\ldots A\makesubscript{3}\ldots A\makesubscript{4}}}$ and $w_2^2 := w_2|_{\upletters{Y\makesubscript{1}\ldots A\makesubscript{3}\ldots A\makesubscript{4}}}$. Applying \cref{lem:unpredstep1} again with $w_1^2$ and $w_2^2$, we obtain two substrings $v_1^2 \sqsubset w_1^2$ and $v_2^2 \sqsubset w_2^2$ of the form $\upletters{Y\makesubscript{1}\ldots Y\makesubscript{2}}$, with $\letters{v_1^2} \neq \letters{v_2^2}$. In particular, $w_1$ and $w_2$ can now be written as
\begin{equation*}
\upletters{Y\makesubscript{0}\ldots Y\makesubscript{1}\ldots Y\makesubscript{2}\ldots A\makesubscript{5}\ldots A\makesubscript{6}\ldots$\cdots$\ldots A\makesubscript{2m}}.
\end{equation*}
We can repeat this process; after $m$ applications of \cref{lem:unpredstep1}, we obtain substrings of $w_1$ and $w_2$ of the form $\upletters{Y\makesubscript{0}\ldots Y\makesubscript{1}\ldots Y\makesubscript{2}\ldots$\cdots$\ldots Y\makesubscript{m}}$ with the required properties.

\label{lem:unpredstep3}
Let $m\geqslant 1$. Let $\upletters{Y\makesubscript{0}}, \ldots, \upletters{Y\makesubscript{4m}}\in \mathcal{A}$. Let $w_1, w_2\in \mathcal{W}^{\neq}$ be two words of the form
\begin{equation*}
\upletters{Y\makesubscript{0}\ldots Y\makesubscript{1}\ldots Y\makesubscript{2}\ldots$\cdots$\ldots Y\makesubscript{4m}}.
\end{equation*}
Suppose that, for all $j\in \sinterval{4m}$, the words $w_1|_{\upletters{Y\makesubscript{j\!-\!1}\ldots Y\makesubscript{j}}}$ and $w_2|_{\upletters{Y\makesubscript{j\!-\!1}\ldots Y\makesubscript{j}}}$ have distinct sets of letters.

Then, there is a pair of words $(w_1', w_2') \in \{(w_1, w_2), (w_2, w_1), (\overline{w_1}, \overline{w_2}), (\overline{w_2}, \overline{w_1})\}$ with the following properties.

There are letters $\upletters{X\makesubscript{1}},\ldots,\upletters{X\makesubscript{m}},\upletters{Z\makesubscript{0}},\upletters{Z\makesubscript{1}},\ldots,\upletters{Z\makesubscript{m}},\upletters{Z\makesubscript{m\!+\!1}}$ (possibly equal to some of the $\upletters{Y\makesubscript{j}}$) such that $w_1'$ is of the form 
\begin{equation*}
\upletters{Z\makesubscript{0}\ldots X\makesubscript{1}\ldots Z\makesubscript{1}\ldots X\makesubscript{2}\ldots Z\makesubscript{2}\ldots$\cdots$\ldots Z\makesubscript{m\!-\!1}\ldots X\makesubscript{m}\ldots Z\makesubscript{m}\ldots Z\makesubscript{m\!+\!1}},
\end{equation*}
$w_2'$ is of the form 
\begin{equation*}
\upletters{Z\makesubscript{0}\ldots Z\makesubscript{1}\ldots Z\makesubscript{2}\ldots$\cdots$\ldots Z\makesubscript{m}\ldots Z\makesubscript{m\!+\!1}},
\end{equation*}
and, for all $j\in \sinterval{m}$, the letter \upletters{X\makesubscript{j}} does not appear in $w_2'|_{\upletters{Z\makesubscript{0}\ldots Z\makesubscript{j}}}$.

\begin{equation*}
\upletters{Z\makesubscript{0}\ldots X\makesubscript{1}\ldots Z\makesubscript{1}\ldots X\makesubscript{2}\ldots Z\makesubscript{2}\ldots$\cdots$\ldots Z\makesubscript{m\!-\!1}\ldots X\makesubscript{m}\ldots Z\makesubscript{m}\ldots Z\makesubscript{m\!+\!1}},
\end{equation*}

\begin{equation*}
\upletters{Y\makesubscript{0}\ldots X\makesubscript{1}\ldots Y\makesubscript{j\makesubscript{1}}\ldots X\makesubscript{2}\ldots Y\makesubscript{j\makesubscript{2}}\ldots$\cdots$\ldots Y\makesubscript{j\makesubscript{m\!-\!1}}\ldots X\makesubscript{m}\ldots Y\makesubscript{j\makesubscript{m}}\ldots Y\makesubscript{4m}}.
\end{equation*}

\label{lem:unpredstep4}
Let $m\geqslant 1$. Let $\upletters{A\makesubscript{0}}, \ldots, \upletters{A\makesubscript{8m}}\in \mathcal{A}$. Let $w_1,w_2\in \mathcal{W}^{\neq}$ be two words of the form
\begin{equation*}
\upletters{A\makesubscript{0}\ldots A\makesubscript{1}\ldots A\makesubscript{2}\ldots$\cdots$\ldots A\makesubscript{8m}}.
\end{equation*}
Suppose that, for $1\leqslant i\leqslant 8m-1$, the letter \upletters{A\makesubscript{i}} has variable neighbours in the concatenation $w_1w_2$. 

Then, after possibly replacing $(w_1, w_2)$ with an element of $\{(w_1, w_2), (w_2, w_1), (\overline{w_1}, \overline{w_2}), (\overline{w_2}, \overline{w_1})\}$, the following applies.

For some letters $\upletters{X\makesubscript{1}},\ldots,\upletters{X\makesubscript{m}},\upletters{Z\makesubscript{0}},\upletters{Z\makesubscript{1}},\ldots,\upletters{Z\makesubscript{m}}$ (possibly equal to some of the $\upletters{A\makesubscript{j}}$), there are words $v_1\sqsubset w_1$ and $v_2 \sqsubset w_2$, with $v_1$ of the form
\begin{equation*}
\upletters{Z\makesubscript{0}\ldots X\makesubscript{1}\ldots Z\makesubscript{1}\ldots X\makesubscript{2}\ldots Z\makesubscript{2}\ldots$\cdots$\ldots Z\makesubscript{m\!-\!1}\ldots X\makesubscript{m}\ldots Z\makesubscript{m}}
\end{equation*}
and $v_2$ of the form 
\begin{equation*}
\upletters{Z\makesubscript{0}\ldots Z\makesubscript{1}\ldots Z\makesubscript{2}\ldots$\cdots$\ldots Z\makesubscript{m}},
\end{equation*}
such that, for all $j\in \sinterval{m}$, the letter \upletters{X\makesubscript{j}} does not appear in the substring $v_2|_{\upletters{Z\makesubscript{0}\ldots Z\makesubscript{j}}}$.

\begin{equation*}
\upletters{Z\makesubscript{0}\ldots X\makesubscript{1}\ldots Z\makesubscript{1}\ldots X\makesubscript{2}\ldots Z\makesubscript{2}\ldots$\cdots$\ldots Z\makesubscript{m\!-\!1}\ldots X\makesubscript{m}\ldots Z\makesubscript{m}}
\end{equation*}

\label{lem:combipairs}
Let $S$ be a set of $n$ pairs of real numbers, such that
\begin{itemize}
	\item if $(a,b)\in S$ then $a<b$, and
	\item if  $(a,b), (c,d)\in S$ are two distinct pairs, then $\{a, b\}\cap \{c,d\} = \emptyset$.
\end{itemize}

There exists $S' \subset S$ of size $n' \geqslant n^{1/4}$ such that one of the following holds.\footnote{The bound $n' \geqslant n^{1/4}$ can be improved, but that is not relevant for us.}
\begin{enumerate}[label=(\roman*), ref=\roman*]
	\item \label{item:pairs1} $S' = \{(a_1, b_1), (a_2, b_2),\ldots, (a_{n'}, b_{n'})\}$ for some $a_1<b_1<a_2<b_2<\cdots <b_{n'}$.
	\item \label{item:pairs2} $S' = \{(a_1, b_1), (a_2, b_2),\ldots, (a_{n'}, b_{n'})\}$ for some $a_1<a_2<\cdots <a_{n'}<b_1<b_2<\cdots <b_{n'}$.
	\item \label{item:pairs3} $S' = \{(a_1, b_1), (a_2, b_2),\ldots, (a_{n'}, b_{n'})\}$ for some $a_1<a_2<\cdots <a_{n'}<b_{n'}<b_{n'-1}<\cdots <b_1$.
\end{enumerate}

\label{prop:structureunpred}
There is an absolute constant $c_1> 0$ such that the following holds.

Let $n,t\geqslant 10$. Let $w\in \mathcal{W}_n$ be a $t$-unpredictable word. Then, for some $m \geqslant t^{c_1}$, at least one of the properties below is satisfied.
\begin{enumerate}
	\item $w$ has $m$ separated repetitions.
	\item There are words $v_1, v_2$ with all of the following properties:
            \begin{enumerate}[label=(\roman*), ref=\roman*]
            	\item $v_1\in \mathcal{W}^{\neq}$ and $v_2\in \mathcal{W}^{\neq}$;
            	\item $v_1 \sqsubset w$ or $\overline{v_1} \sqsubset w$;
            	\item $v_2 \sqsubset w$ or $\overline{v_2} \sqsubset w$;
            	\item there are letters $\upletters{X\makesubscript{1}},\ldots,\upletters{X\makesubscript{m}},\upletters{Z\makesubscript{0}},\ldots,\upletters{Z\makesubscript{m}}$ such that $v_1$ is of the form
                            \begin{equation*}
                            \upletters{Z\makesubscript{0}\ldots X\makesubscript{1}\ldots Z\makesubscript{1}\ldots X\makesubscript{2}\ldots Z\makesubscript{2}\ldots$\cdots$\ldots Z\makesubscript{m-1}\ldots X\makesubscript{m}\ldots Z\makesubscript{m}}
                            \end{equation*}
                            and $v_2$ is of the form 
                            \begin{equation*}
                            \upletters{Z\makesubscript{0}\ldots Z\makesubscript{1}\ldots Z\makesubscript{2}\ldots$\cdots$\ldots Z\makesubscript{m}}.
                            \end{equation*}
                            Moreover, for all $j\in \sinterval{m}$, the letter \upletters{X\makesubscript{j}} does not appear in $v_2|_{\upletters{Z\makesubscript{0}\ldots Z\makesubscript{j}}}$.
            \end{enumerate}
\end{enumerate}

\begin{equation*}
                            \upletters{Z\makesubscript{0}\ldots X\makesubscript{1}\ldots Z\makesubscript{1}\ldots X\makesubscript{2}\ldots Z\makesubscript{2}\ldots$\cdots$\ldots Z\makesubscript{m-1}\ldots X\makesubscript{m}\ldots Z\makesubscript{m}}
                            \end{equation*}

By definition of unpredictability, either $w$ contains a letter repeated $>t$ times, or it has $>t$ letters with variable neighbours. In the first case, we immediately see that $w$ has $\lfloor t/2 \rfloor$ repetitions. This is $\geqslant t^{c_1}$ if $c_1$ is sufficiently small.

Suppose now that there are $>t$ letters with variable neighbours in $w$. Let $E$ be the set of all these letters, with the possible exception of the first and last letters of $w$ which are discarded (to simplify the notation below). Thus, $\abs{E} \geqslant t-2$. For every letter $\upletters{A} \in E$, there are two positions $1<k_{\upletters{A}}<l_{\upletters{A}}<n$ such that $w[k_{\upletters{A}}] = w[l_{\upletters{A}}] = \upletters{A}$, and the sets of letters adjacent to these two occurrences of \upletters{A} are different, i.e.~$\{w[k_{\upletters{A}}-1], w[k_{\upletters{A}}+1]\} \neq \{w[l_{\upletters{A}}-1], w[l_{\upletters{A}}+1]\}$.

We apply \cref{lem:combipairs} to the set $S = \{(k_{\upletters{A}}, l_{\upletters{A}}) : \upletters{A}\in E\}$. If case \cref{item:pairs1} occurs, we can immediately conclude that $w$ has $\gg t^{1/4}$ separated repetitions and we are done.

Suppose that case \cref{item:pairs2} of \cref{lem:combipairs} applies. This implies that, for some $c\gg1$, there exists a subset 
\begin{equation*}
	F = \{\upletters{A\makesubscript{1}},\ldots,\upletters{A\makesubscript{\abs{F}}}\}\subset E
\end{equation*}
of size $\abs{F} \geqslant t^{c}$ such that 
\begin{equation*}
	1<k_{\upletters{A\makesubscript{1}}}<k_{\upletters{A\makesubscript{2}}}<\cdots <k_{\upletters{A\makesubscript{\abs{F}}}}<l_\upletters{A\makesubscript{1}}<l_\upletters{A\makesubscript{2}}<\cdots <l_{\upletters{A\makesubscript{\abs{F}}}}<n.
\end{equation*}
By \cref{lem:unpredstep0}, either $w$ has $\gg t^{c/2}$ separated repetitions, and the first conclusion holds, or we can find a `large' substring of $w[k_{\upletters{A\makesubscript{1}}}]w[k_{\upletters{A\makesubscript{1}}}+1]\cdots w[k_{\upletters{A\makesubscript{\abs{F}}}}]$ with distinct letters. Without loss of generality (by replacing $F$ with a smaller subset, $c$ with a smaller absolute constant and relabelling the letters), we may thus assume that the word $w[k_{\upletters{A\makesubscript{1}}}]w[k_{\upletters{A\makesubscript{1}}}+1]\cdots w[k_{\upletters{A\makesubscript{\abs{F}}}}]$ itself has distinct letters. By a further application of \cref{lem:unpredstep0}, we may also assume that the word $w[l_{\upletters{A\makesubscript{1}}}]w[l_{\upletters{A\makesubscript{1}}}+1]\cdots w[l_{\upletters{A\makesubscript{\abs{F}}}}]$ has distinct letters. 

We apply \cref{lem:unpredstep4} with $w_1 := w[k_{\upletters{A\makesubscript{1}}}]w[k_{\upletters{A\makesubscript{1}}}+1]\cdots w[k_{\upletters{A\makesubscript{\abs{F}}}}]$ and $w_2 := w[l_{\upletters{A\makesubscript{1}}}]w[l_{\upletters{A\makesubscript{1}}}+1]\cdots w[l_{\upletters{A\makesubscript{\abs{F}}}}]$. These are two words in $\mathcal{W}^{\neq}$ of the form 
\begin{equation*}
	\upletters{A\makesubscript{1}\ldots A\makesubscript{2}\ldots A\makesubscript{3}\ldots} \cdots \upletters{\ldots A\makesubscript{\abs{F}}},
\end{equation*}
so the assumptions of \cref{lem:unpredstep4} are satisfied (of course, we may assume that $\abs{F} \equiv 1 \pmod{8}$ without loss of generality). The conclusion of \cref{lem:unpredstep4} provides us with two words $v_1$ and $v_2$ precisely satisfying the second conclusion of \cref{prop:structureunpred}.

The treatment of case \cref{item:pairs3} of \cref{lem:combipairs} is similar. For some $c\gg1$, there exists a subset 
\begin{equation*}
	F = \{\upletters{A\makesubscript{1}},\ldots,\upletters{A\makesubscript{\abs{F}}}\}\subset E
\end{equation*}
of size $\abs{F} \geqslant t^{c}$ such that 
\begin{equation*}
	1<k_{\upletters{A\makesubscript{1}}}<k_{\upletters{A\makesubscript{2}}}<\cdots <k_{\upletters{A\makesubscript{\abs{F}}}}<l_\upletters{A\makesubscript{\abs{F}}}<l_\upletters{A\makesubscript{\abs{F}\!-\!1}}<\cdots <l_{\upletters{A\makesubscript{1}}}<n.
\end{equation*}
By two successive applications \cref{lem:unpredstep0}, we may assume, without loss of generality, that the substrings $w_1 := w[k_{\upletters{A\makesubscript{1}}}]w[k_{\upletters{A\makesubscript{1}}}+1]\cdots w[k_{\upletters{A\makesubscript{\abs{F}}}}]$ and $w_2 := w[l_{\upletters{A\makesubscript{\abs{F}}}}]w[l_{\upletters{A\makesubscript{\abs{F}}}}-1]\cdots w[l_{\upletters{A\makesubscript{1}}}]$ each have distinct letters. Then, applying \cref{lem:unpredstep4} with these two substrings $w_1$ and $w_2$ produces two words $v_1$ and $v_2$ with the required properties.

\label{def:minimalrep}
Let $\boldsymbol{d}\in \widetilde{\mathbf{D}}^{\mathcal{S},\mathcal{L}}_{\!R}$. Let $1\leqslant x<y \leqslant R$ and $p\in \mathcal{P}$. We will say that $(x,y,p)$ is a \emph{divisibility triple} if $p\mid d_x$, $p\mid d_y$ and there is at least one $x<i<y$ such that $p\nmid d_i$. In particular, $y\geqslant x+2$. 

We shall say that the triple $(x,y,p)$ is \emph{minimal} if there is no divisibility triple $(x',y',p')$ with ${x\leqslant x'<y'\leqslant y}$ and $\abs{y'-x'}<\abs{y-x}$.

\label{lem:seprepstep0}
Let $\boldsymbol{d}\in \widetilde{\mathbf{D}}^{\mathcal{S},\mathcal{L}}_{\!R}$ and let $(x,y,p)$ be a minimal divisibility triple. There is some $q\in \mathcal{P}$ such that 
\begin{equation*}
	\sum_{\substack{x<i<y\\ q\mid d_{i}}} d_{i} \not\equiv 0 \pmod p.
\end{equation*}

First, note that $p\nmid d_{i}$ for all $x<i<y$ by minimality of $(x,y,p)$. For $q\in \mathcal{P}$, define 
\begin{equation*}
	I(q) = \{x<i<y : q\mid d_i\}.
\end{equation*}
Observe that $I(q)$ is a discrete interval by \cref{lem:triplediscreteintervals} and minimality of $(x,y,p)$. 

Consider the collection $\mathcal{I}$ of all sets $I(q)$, where $q$ ranges over the prime divisors of $d_{y-1}$. This is a partially ordered set (where the partial order is set inclusion). Choose a prime $q_0\mid d_{y-1}$ such that $I(q_0)$ is minimal in $\mathcal{I}$ for inclusion. This implies that $\pcomp{i}{j} = \pcomp{(y-1)}{j}$ for all $i\in I(q_0)$ and all $j\in \sinterval{J}$, and thus $|{d_i}| = |{d_{y-1}}|$ for all $i\in I(q_0)$. Since $\boldsymbol{d}$ is non-backtracking, we actually have ${d_i} = {d_{y-1}}$ for all $i\in I(q_0)$. Therefore,
\begin{equation*}
	\sum_{\substack{x<i<y\\ q_0\mid d_i}} d_{i} = \sum_{i\in I(q_0)} d_{i} = \abs{I(q_0)} d_{y-1}.
\end{equation*}
This is not divisible by $p$ since $p\nmid d_{y-1}$ and $0<\abs{I(q_0)} \leqslant R \leqslant K < H_0 \leqslant p$.

\begin{equation*}
	\sum_{\substack{x<i<y\\ q_0\mid d_i}} d_{i} = \sum_{i\in I(q_0)} d_{i} = \abs{I(q_0)} d_{y-1}.
\end{equation*}

\label{lem:seprepstep1}
Let $\boldsymbol{d} \in \widetilde{\mathbf{D}}^{\mathcal{S},\mathcal{L}}_{\!R}$, let $j\in \sinterval{J}$, and suppose that the word $w_{j,\boldsymbol{d}}$ (see \cref{def:predunpred}) has $\geqslant 2m$ separated repetitions, for some $m \geqslant K^{2\varepsilon_1}$.

Then there are $1\leqslant x_1<y_1<x_2<y_2<\ldots <x_m<y_m \leqslant R$ and primes $p_1, \ldots, p_m\in \mathcal{P}$ such that, for all $i\in \sinterval{m}$, $(x_i,y_i,p_i)$ is a minimal divisibility triple, and moreover
\begin{equation*}
	\big(\interval{x_i}{y_i} \times \sinterval{J}\big) \cap \mathcal{U} = \emptyset.
\end{equation*}

By \cref{lem:seprepstep1}, there are $1\leqslant x_1<y_1<x_2<y_2<\ldots <x_m<y_m \leqslant R$ and $p_1, \ldots, p_m\in \mathcal{P}$ such that, for all $i \in \sinterval{m}$, $(x_i,y_i,p_i)$ is a minimal divisibility triple, and
\begin{equation}
\label{eq:assumptionnounlit}
	\big(\interval{x_i}{y_i} \times \sinterval{J}\big) \cap \mathcal{U} = \emptyset.
\end{equation}
By definition of divisibility triple, and by part \cref{item:litcond1x} of \cref{def:dnb}, for every $i \in \sinterval{m}$, we have
\begin{equation}
\label{eq:theconstraintinrep}
	p_i \ \Big\vert\, \sum_{x_i<z<y_i} d_z.
\end{equation}
By \cref{lem:seprepstep0}, there is, for each $n$, a prime $q_i \in \mathcal{P}$ such that 
\begin{equation}
\label{eq:condnonzero2}
	\sum_{\substack{x_i<z<y_i\\ q_i\mid d_{z}}} d_{z} \not\equiv 0 \pmod {p_i}.
\end{equation}

Let $I^<$ be the set of all $i \in \sinterval{m}$ such that $q_i$ does not divide $\prod_{k<i}\prod_{z\in \interval{x_{k}}{y_{k}}}d_z$. 

Suppose that $\abs{I^<}\geqslant m/4$. Observe that \cref{eq:theconstraintinrep} is a constraint $C_i$ on $\boldsymbol{d}$ in which $q_i$ is \cref{item:const3}-involved by \cref{eq:condnonzero2}. If $i \in I^<$, we know that $q_i$ is absent from the constraints $C_{k}$ with $k<i$. Therefore, the constraints $(C_i)_{i \in I^<}$ form a triangular system of complexity $(\lceil m/4 \rceil; 1, 0)$ and we are done. Henceforth, we assume that $\abs{I^<}< m/4$.

Now, let $I_1$ be the set of all $i \in \sinterval{m}$ such that $\interval{x_i+1}{y_i-1}\times \sinterval{J}$ contains an index $(s_i, t_i)\in \mathcal{S}$. Suppose that $\abs{I_1}\geqslant m/4$. We will use the previous constraints $C_i$, but with the $\pcomp{s_i}{t_i}$ as the involved primes, in place of $q_i$. For $i \in I_1$, notice that $\pcomp{s_i}{t_i}$ is \cref{item:const3}-involved in the constraint \cref{eq:theconstraintinrep}, because 
\begin{equation}
\label{eq:condnonzero3}
	\sum_{\substack{x_i<z<y_i\\ \pcomp{s_i}{t_i}\mid d_{z}}} d_{z} = d_{s_i} \not\equiv 0 \pmod {p_i}.
\end{equation}
Here we used that $(s_i, t_i)\in \mathcal{S}$ for the first equality and the minimality of $(x_i,y_i,p_i)$ to say that $p_i \nmid d_{s_i}$. In addition, $\pcomp{s_i}{t_i}$ is absent from the other constraints $C_{k}$, $k\neq i$, as $(s_i, t_i)\in \mathcal{S}$. Thus, $(C_i)_{i \in I_1}$ is a triangular system of complexity $(\lceil m/4 \rceil; 1, 0)$ satisfied by $\boldsymbol{d}$, as desired. We now assume that $\abs{I_1} < m/4$.

Let $I_2$ be the set of all $i \in \sinterval{m}$ such that $\{x_i\}\times \sinterval{J}$ contains an index $(s_i, t_i)\in \mathcal{S}$ (thus $s_i = x_i$). Suppose that $\abs{I_2} \geqslant m/2$. Then $\abs{I_2\setminus I^<} \geqslant m/4$. This time, we will use a different sequence of constraints.  Let $i \in I_2\setminus I^<$. By definition of $I^<$, we know that there exists
\begin{equation*}
	z_i \in \bigcup_{k<i} \interval{x_{k}}{y_{k}}
\end{equation*}
such that $q_i \mid d_{z_i}$. By \cref{eq:assumptionnounlit}, we have $(\{z_i\}\times \sinterval{J})\cap \mathcal{U} = \emptyset$. We also know that $q_i\mid d_{u_i}$ for some $x_i<u_i<y_i$ by \cref{eq:condnonzero2}. By \cref{eq:assumptionnounlit} again, we have $(\{u_i\}\times \sinterval{J})\cap \mathcal{U} = \emptyset$. Hence, by part \cref{item:litcond1x} of \cref{def:dnb}, we obtain the constraint
\begin{equation*}
	q_i \ \Big\vert\,  \sum_{z_i<l<u_i} d_l,
\end{equation*}
that we call $C_i'$. Since 
\begin{equation}
\label{eq:orderinginequ}
	z_i<x_i=s_i<u_i<y_i
\end{equation}
and $(s_i, t_i)\in \mathcal{S}$, we have $\pcomp{s_i}{t_i} \neq q_i$ and
\begin{equation*}
	\sum_{\substack{z_i < l < u_i \\ \pcomp{s_i}{t_i} \mid d_l}} d_l = d_{s_i} \not\equiv 0 \pmod{q_i};
\end{equation*}
therefore $\pcomp{s_i}{t_i}$ is \cref{item:const3}-involved in $C_i'$. Moreover, for $k,i\in I_2\setminus I^<$ with $k<i$, the same inequalities~\cref{eq:orderinginequ} and the fact that $(s_{i}, t_{i})\in \mathcal{S}$ show that $\pcomp{s_{i}}{t_{i}}$ is absent from $C_{k}'$. Thus, $\boldsymbol{d}$ satisfies a triangular system of complexity $(\lceil m/4 \rceil; 1, 0)$. We may assume henceforth that $\abs{I_2} < m/2$.

We have reached the final case of the proof. We will show that this case is impossible using the prohibited sequences condition. Let $I_3 = \sinterval{m} \setminus (I_1\cup I_2)$, so that $\abs{I_3} \geqslant m/4$. For $i \in I_3$, by definition of $I_1$ and $I_2$, the set $\interval{x_i}{y_i-1}\times \sinterval{J}$ has empty intersection with $\mathcal{S}$. By \cref{eq:assumptionnounlit}, this implies that $\interval{x_i}{y_i-1}\times \sinterval{J}\subset \mathcal{L}$. 

Let $i \in I_3$ and suppose for a moment that $\abs{y_i-x_i} \leqslant L$. We claim that $(d_{x_i}, d_{x_i+1}, \ldots, d_{y_i-1})$ is a prohibited sequence (see \cref{def:prohibitedsequence}). This vector is non-backtracking as $\boldsymbol{d}\in \widetilde{\mathbf{D}}^{\mathcal{S},\mathcal{L}}_{\!R}$; it satisfies the consecutiveness assumption by \cref{lem:triplediscreteintervals} and minimality of $(x_i, y_i, p_i)$; and it satisfies the prohibited pattern \cref{eq:theconstraintinrep}. Therefore, $(d_{x_i}, d_{x_i+1}, \ldots, d_{y_i-1})$ is indeed a prohibited sequence, but this cannot happen by part \cref{item:litcond3x} of \cref{def:dnb}. 

We deduce that $y_i - x_i>L$ for all $i \in I_3$. This implies
\begin{equation*}
	|I_3| L \leqslant \sum_{i \in I_3} (y_i-x_i) \leqslant R \leqslant K,
\end{equation*}
but that is impossible as $\abs{I_3} \geqslant m/4 \geqslant 2K^{10\varepsilon_1}$ and $L = K^{1-10\varepsilon_1}$. This concludes the proof.

Let $w := w_{j,\boldsymbol{d}}$. Consider the second conclusion of \cref{prop:structureunpred}. There are eight possibilities:
\begin{itemize}
	\item $v_1 \sqsubset w$, $v_2 \sqsubset w$ and $v_1$ appears before $v_2$ in $w$;\footnote{Technically speaking, we should say that there is \emph{an occurrence of} $v_1$ before/after \emph{an occurrence of} $v_2$ in $w$, as $v_1$ and $v_2$ could appear several times in $w$.}
	\item $v_1 \sqsubset w$, $v_2 \sqsubset w$ and $v_1$ appears after $v_2$ in $w$;
	\item $v_1 \sqsubset w$, $\overline{v_2} \sqsubset w$ and $v_1$ appears before $\overline{v_2}$ in $w$;\\
	 $\vdots$
	 \item $\overline{v_1} \sqsubset w$, $\overline{v_2} \sqsubset w$ and $\overline{v_1}$ appears after $\overline{v_2}$ in $w$.
\end{itemize}
We will only consider the case where $v_1 \sqsubset w$, $v_2 \sqsubset w$ and $v_1$ appears before $v_2$ in $w$. The proofs of the seven other cases are completely analogous and left to the reader. 

In this case, the second conclusion of \cref{prop:structureunpred} tells us that there are integers
\begin{equation}
\label{eq:ikxinequalities}
k_0<x_1<k_1<x_2<k_2<\cdots<x_m<k_m\leqslant l_0<l_1<l_2<\cdots <l_m
\end{equation}
in $\sinterval{R}$ such that $\pcomp{k_i}{j} = \pcomp{l_i}{j}$ for all $i\in \interval{0}{m}$. Moreover, for all $i\in \sinterval{m}$, the prime $\pcomp{x_i}{j}$ does not divide $\prod_{l_0\leqslant z\leqslant l_i} d_{z}$. Furthermore, the fact that $v_1$ has distinct letters implies in particular that, for all $i\in \sinterval{m-1}$, $\pcomp{k_{i+1}}{j} \nmid \prod_{z\in \interval{k_{i-1}}{k_i}} d_z$, and for all $i\in \sinterval{m}$, $\pcomp{x_i}{j} \nmid \prod_{k_0\leqslant z \leqslant k_{i-1}} d_z$. These observations will be useful later.

Call an integer $i\in \sinterval{m}$ \emph{unsuitable} if one of the following holds:
\begin{itemize}
	\item there exists an unlit index in $\interval{k_{i-1}}{k_i}\times \sinterval{J}$ or in $\interval{l_{i-1}}{l_i}\times \sinterval{J}$;
	\item $\abs{k_i-k_{i-1}}\geqslant L$ or $\abs{l_i-l_{i-1}}\geqslant L$;
	\item there exists a divisibility triple $(x,y,p)$ with $k_{i-1}<x<y\leqslant k_i$.
\end{itemize}
Otherwise, we shall say that $i$ is \emph{suitable}.

Since $\abs{\mathcal{U}} \leqslant K^{2\varepsilon_1}$ and $L = K^{1-10\varepsilon_1}$, the first two scenarios can only happen for $\leqslant 3K^{10\varepsilon_1}$ values of~$i\in \sinterval{m}$. Moreover, if there are $\geqslant 8 K^{10\varepsilon_1}$ values of $i$ for which the third scenario occurs, then $w$ has $\geqslant 8 K^{10\varepsilon_1}$ repetitions, and we are done by \cref{lem:seprepstep2}. Therefore, there are at most $11K^{10\varepsilon_1}$ unsuitable integers $i\in \sinterval{m}$.

Let $\interval{m_1}{m_2}$ be a subinterval of $\sinterval{m}$ of maximal length that does not contain any unsuitable integer. Then $m_2-m_1 \geqslant m/(33K^{10\varepsilon_1})$.

Let $i\in \interval{m_1}{m_2}$. Note that $(k_i,j),(l_i,j)\not\in \mathcal{U}$ since $i$ is suitable, and $(k_i,j),(l_i,j)\not\in \mathcal{S}$ as $\pcomp{k_i}{j} = \pcomp{l_i}{j}$. This means that $(k_i,j),(l_i,j)\in \mathcal{L}$. Hence, by part \cref{item:litcond1x} of \cref{def:dnb}, we have the following constraint on $\boldsymbol{d}$:
\begin{equation*}
	\pcomp{k_i}{j} \ \Big\vert \, \sum_{k_i< z <l_i} d_z.
\end{equation*}
We rewrite this as 
\begin{equation}
\label{eq:lastconstraint}
	\pcomp{k_i}{j}  \ \Big\vert \, \kappa +\sum_{k_0\leqslant z <k_i}-d_z + \sum_{l_0< z <l_i}d_z,
\end{equation}
with $\kappa := \sum_{k_0\leqslant z\leqslant l_0} d_z$. We call this constraint $C_i$; it is a constraint on the concatenation of $\boldsymbol{d}$ and $-\boldsymbol{d}$. We will show that an appropriate subset of these constraints forms a triangular system. 

Note that $\abs{\kappa}\leqslant K H$, and $\kappa$ is the same for all $C_i$.

We define $I$ to be the set of all $i\in \interval{m_1}{m_2}$ such that $\big(\interval{k_{i-1}}{k_i}\times \sinterval{J}\big)\cap \mathcal{S} \neq \emptyset$.

Suppose first that $\abs{I}\geqslant (m_2-m_1)/2$. Then one of the sets $I_0 := \{i\in I : i\equiv 0\pmod 2\}$ and $I_1 := \{i\in I : i\equiv 1\pmod 2\}$ has size $\geqslant (m_2-m_1)/4$. Without loss of generality, suppose that we are in the case $\abs{I_0}\geqslant (m_2-m_1)/4$. For each element $i\in I_0$, there is some $(s_i, t_i)\in \mathcal{S}$ such that $\{s_i\} \in \interval{k_{i-1}}{k_i}$. We claim that the constraints $(C_{i+1})_{i\in I_0}$ form a triangular system. Indeed, the prime $\pcomp{s_i}{t_i}$ is \cref{item:const3}-involved in $C_{i+1}$ as
\begin{equation*}
	\sum_{\substack{k_0\leqslant z<k_{i+1}\\ \pcomp{s_i}{t_i} \mid d_z}}-d_z + \sum_{\substack{l_0< z<l_{i+1}\\ \pcomp{s_i}{t_i} \mid d_z}}d_z= -d_{s_i} \not\equiv 0 \pmod{\pcomp{k_{i+1}}{j}},
\end{equation*}
using that $(s_i, t_i)$ is a single index. The last step $d_{s_i}\not\equiv 0 \pmod{\pcomp{k_{i+1}}{j}}$ follows from the above-mentioned fact that $\pcomp{k_{i+1}}{j}$ does not divide $\prod_{z\in \interval{k_{i-1}}{k_i}} d_z$. Furthermore, $\pcomp{s_i}{t_i}$ is absent from $C_{r+1}$ for all $r\in I_0$ with $r<i$, as for such $r$ we have $s_i \not\in \interval{k_0}{k_{r+1}-1} \cup \interval{l_0+1}{l_{r+1}-1}$. Thus, the concatenation of $\boldsymbol{d}$ and $-\boldsymbol{d}$ satisfies a triangular system of constraints of complexity ${(\lceil (m_2-m_1)/4 \rceil ;2,K H)}$, as required.

Thus, we may assume that $\abs{I} < (m_2-m_1)/2$. Let $i\in \interval{a}{b}\setminus I$. We will finally make use of the integers $x_i$ introduced in \cref{eq:ikxinequalities}. We claim that the prime $\pcomp{x_i}{j}$ is \cref{item:const3}-involved in the constraint $C_i$ defined by~\cref{eq:lastconstraint}. 

Suppose for contradiction that $\pcomp{x_i}{j}$ is not \cref{item:const3}-involved in $C_i$. Recalling that $\pcomp{x_i}{j}$ does not divide $\prod_{l_0\leqslant z\leqslant l_i} d_{z}$, this means that 
\begin{equation}
\label{eq:finalprohibitedpattern}
	\sum_{\substack{k_{i-1}<z<k_i\\ \pcomp{x_i}{j}\mid d_z}}d_z \equiv 0 \pmod{\pcomp{k_i}{j}}.
\end{equation}
Since $i$ is suitable, the set $\{k_{i-1}<z< k_i: \pcomp{x_i}{j}\mid d_z\}$ is a discrete interval, by \cref{lem:triplediscreteintervals}, say $\{k_{i-1}<z< k_i: \pcomp{x_i}{j}\mid d_z\} = \interval{r}{t}$. Observe that the vector $(d_{k_i}, d_{k_i-1}, \ldots, d_{r})$ is a prohibited sequence. Indeed, it satisfies all the assumptions of \cref{def:prohibitedsequence}: it has length $\leqslant \abs{k_i-k_{i-1}}< L$ as $i$ is suitable; it is non-backtracking as $\boldsymbol{d}\in \widetilde{\mathbf{D}}^{\mathcal{S},\mathcal{L}}_{\!R}$; it meets the consecutiveness assumption by \cref{lem:triplediscreteintervals} (using that $i$ is suitable); and finally, by \cref{eq:finalprohibitedpattern}, it satisfies the prohibited pattern 
\begin{equation*}
	\pcomp{k_i}{j} \ \Big\vert\,\sum_{\substack{k_{i-1}<z<k_i\\ \pcomp{x_i}{j}\mid d_z}}d_z  = \sum_{r\leqslant z\leqslant t} d_z.
\end{equation*}
However, using that $i\not\in I$ and that $i$ is suitable, we see that $\interval{k_{i-1}}{k_i}\times \sinterval{J}\subset \mathcal{L}$. This contradicts  part \cref{item:litcond3x} of \cref{def:dnb}. We deduce that $\pcomp{x_i}{j}$ is \cref{item:const3}-involved in the constraint $C_i$.

We know, by definition of $x_i$, that $\pcomp{x_i}{j}$ does not divide $\prod_{l_0\leqslant z\leqslant l_i} d_{z}$ or $\prod_{k_0\leqslant z \leqslant k_{i-1}} d_z$. This implies that $\pcomp{x_i}{j}$ is absent from $C_{k}$ for all $k<i$. Therefore, the concatenation of $\boldsymbol{d}$ and $-\boldsymbol{d}$ satisfies the triangular system of constraints $(C_i)_{i\in \interval{a}{b}\setminus I}$, which has complexity $(\lceil(m_2-m_1)/2 \rceil ;2,K H)$. This concludes the proof.

Let $\boldsymbol{d}\in \mathbf{U}_{\!R}$. By \cref{def:predunpred}, there is some ${j\in \sinterval{J}}$ such that $w_{j,\boldsymbol{d}}$ is $K^{1/4}$-unpredictable. 

Let $c_1>0$ be the constant in the statement of \cref{prop:structureunpred}. We can safely assume that ${K^{c_1/8} \geqslant 400K^{10\varepsilon_1}}$ since $c_1$ is a fixed absolute constant (that could in principle be computed) and $\varepsilon_1$ is assumed to be sufficiently small.

By \cref{prop:structureunpred}, one the following holds.
\begin{itemize}
	\item The first possibility is that $w_{j,\boldsymbol{d}}$ has $\geqslant K^{c_1/4}$ separated repetitions. By \cref{lem:seprepstep2}, $\boldsymbol{d}$ satisfies a triangular system of complexity $(\lceil K^{c_1/4}/100 \rceil ;1,0)$.
	\item Otherwise, the second conclusion of \cref{prop:structureunpred} holds with $m\geqslant K^{c_1/4}$, which means that the hypotheses of \cref{lem:seprepstep3} are satisfied, and hence the concatenation of $\boldsymbol{d}$ and $-\boldsymbol{d}$ satisfies a triangular system of constraints of complexity $(\lceil K^{c_1/4}/(200K^{10\varepsilon_1})\rceil ;2,K H)$.
\end{itemize}
In either case, the concatenation of $\boldsymbol{d}$ and $-\boldsymbol{d}$ satisfies a triangular system of constraints of complexity $(\lceil 2K^{c_1/8} \rceil ;2,K H)$.

By \cref{lem:constraints}, we obtain the bound
\begin{equation*}
	\sum_{\substack{\boldsymbol{d}\in \mathbf{U}_{\!R}}}\,\prod_{p\mid \fprod{\boldsymbol{d}}}\, \frac{1}{p} \ll K H K^{22R J} H_0^{-K^{c_1/8}}.
\end{equation*}
Note that $K H K^{22R J} \ll K^{O(K J)}$ as $H\leqslant e^{K}$ and $R\leqslant K$. Moreover, since ${\log H_0 \gg K^{1-\varepsilon_1}}$ and $c_1\geqslant 80\varepsilon_1$ we have $H_0^{-K^{c_1/8}} \ll \exp\big(-K^{1+c_1/16}\big)$. Recalling that $J \leqslant \log K$, we get
\begin{equation*}
	\sum_{\substack{\boldsymbol{d}\in \mathbf{U}_{\!R}}}\,\prod_{p\mid \fprod{\boldsymbol{d}}}\, \frac{1}{p} \ll K^{O(K J)} e^{-K^{1+c_1/16}} \ll 1
\end{equation*}
as desired.

\label{def:extension}
Let $R \geqslant 2$. Let $\mathcal{S},\mathcal{L},\mathcal{U}$ be sets such that $\sinterval{R}\times \sinterval{J} = \mathcal{S}\sqcup \mathcal{L}\sqcup \mathcal{U}$. Let $\boldsymbol{d}'\in \Dsfmix{R-2}$ and $\boldsymbol{d}\in \Dsfmix{R}$.
We say that $\boldsymbol{d}$ is an \emph{extension of $\boldsymbol{d}'$} if 
\begin{equation*}
	\boldsymbol{d} = (d'_1, d'_2, \ldots, d'_{R-2}, x, -x)
\end{equation*}
for some $x\in \pm \mathcal{D}$. The \emph{type} of this extension is defined to be the triple $(J_{\mathcal{N}}, J_{\mathcal{L}}, J_{\mathcal{U}})$, where 
\begin{enumerate}
	\item $J_{\mathcal{N}}$ is the set of all $j\in \sinterval{J}$ such that $\pcomp{R}{j} \nmid \fprod{\boldsymbol{d}'}$;
	\item $J_{\mathcal{L}}$ is the set of all $j\in \sinterval{J}$ such that $(R, j)\in \mathcal{L}$ and there exists $i\in \sinterval{R-2}$ with $\pcomp{R}{j} = \pcomp{i}{j}$ and $(i,j)\in \mathcal{L}$;
	\item $J_{\mathcal{U}}$ is the set of all remaining $j\in \sinterval{J}$, i.e.~$J_{\mathcal{U}}$ is defined by $\sinterval{J} = J_{\mathcal{N}} \sqcup J_{\mathcal{L}}\sqcup J_{\mathcal{U}}$.
\end{enumerate}

\label{lem:Junlitanalysis}
Keeping the notations of \cref{def:extension}, $J_{\mathcal{U}}$ is exactly the set of $j\in \sinterval{J}$ such that
\begin{itemize}
	\item either $(R,j)\in \mathcal{U}$,
	\item or $(R,j)\not\in \mathcal{U}$, and the set $\{i\in \sinterval{R-2}: \pcomp{R}{j} = \pcomp{i}{j}\}$ is non-empty and contained in $\mathcal{U}$.
\end{itemize}

\label{lem:onepairbacktracking}
Let $R \geqslant 2$. Let $\mathcal{S},\mathcal{L},\mathcal{U}$ be sets such that $\sinterval{R}\times \sinterval{J} = \mathcal{S}\sqcup \mathcal{L}\sqcup \mathcal{U}$. Let $J_{\mathcal{N}}, J_{\mathcal{L}}, J_{\mathcal{U}}$ be any sets such that $\sinterval{J} = J_{\mathcal{N}} \sqcup J_{\mathcal{L}}\sqcup J_{\mathcal{U}}$. Let $\boldsymbol{d}'\in \Dsfmix{R-2}$. 

Write $\mathrm{Ext}_{J_{\mathcal{N}}, J_{\mathcal{L}}, J_{\mathcal{U}}}^{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}')$ for the set of all extensions $\boldsymbol{d}$ of $\boldsymbol{d}'$ of type $(J_{\mathcal{N}}, J_{\mathcal{L}}, J_{\mathcal{U}})$ satisfying properties \cref{item:litcond1} and \cref{item:litcond2} of \cref{lem:litcond}. Then
\begin{equation*}
	\sum_{\boldsymbol{d} \in \mathrm{Ext}_{J_{\mathcal{N}}, J_{\mathcal{L}}, J_{\mathcal{U}}}^{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}')}  \, \prod_{\substack{p\mid \fprod{\boldsymbol{d}}\\ p\nmid \fprod{\boldsymbol{d}'}}} \frac{1}{p} \leqslant e^{O(J)} V^{J} R^{\abs{J_{\mathcal{U}}}}.
\end{equation*}

Let us write $\mathrm{Ext}(\boldsymbol{d}')$ instead of $\mathrm{Ext}_{J_{\mathcal{N}}, J_{\mathcal{L}}, J_{\mathcal{U}}}^{\mathcal{S},\mathcal{L},\mathcal{U}}(\boldsymbol{d}')$ to shorten notation. By definition, the elements $\boldsymbol{d} \in \mathrm{Ext}(\boldsymbol{d}')$ are uniquely determined by the $R$-th coordinate $d_{R}\in \pm\mathcal{D}$. Just as any element of $\pm \mathcal{D}$, $d_{R}$ is of the form 
\begin{equation}
\label{eq:lastinsert}
	d_{R} = \sigma \prod_{j\in \sinterval{J}} \pcomp{R}{j}
\end{equation}
for some $\sigma\in \{\pm1\}$ and $\pcomp{R}{j}\in \mathcal{P}_j$. Thus,
\begin{equation}
\label{eq:insertsplit}
	\sum_{\boldsymbol{d} \in \mathrm{Ext}(\boldsymbol{d}')}   \prod_{\substack{p\mid \fprod{\boldsymbol{d}}\\ p\nmid \fprod{\boldsymbol{d}'}}} \frac{1}{p}
	= \sum_{\sigma}  \sum_{(\pcomp{R}{j})_{j\in J_{\mathcal{N}}}}  \sum_{(\pcomp{R}{j})_{j\in J_{\mathcal{L}}}}  \sum_{(\pcomp{R}{j})_{j\in J_{\mathcal{U}}}} \prod_{j\in J_{\mathcal{N}}} \frac{1}{\pcomp{R}{j}},
\end{equation}
where the quadruple sum is over all choices of $\sigma$ and $(\pcomp{R}{j})_{j\in \sinterval{J}}$ such that, defining $d_{R}$ by \cref{eq:lastinsert} and letting $\boldsymbol{d} := (d'_1, d'_2, \ldots, d'_{R-2}, -d_{R}, d_{R})$, we have $\boldsymbol{d} \in \mathrm{Ext}(\boldsymbol{d}')$.

We treat the elements of $J_{\mathcal{N}}$, $J_{\mathcal{L}}$ and $J_{\mathcal{U}}$ separately.

For every $j\in J_{\mathcal{N}}$, we have
\begin{equation}
\label{eq:Jnew}
	\sum_{\pcomp{R}{j}\in \mathcal{P}_j} \frac{1}{\pcomp{R}{j}} = V_j \leqslant V.
\end{equation}

Let $j\in J_{\mathcal{L}}$. By definition of $J_{\mathcal{L}}$, we know that $(R, j)\in \mathcal{L}$. We need to count the number of possibilities for $\pcomp{R}{j}$, given that it should be of the form $\pcomp{R}{j} = \pcomp{i}{j}$ for some $i\in \sinterval{R-2}$ with $(i,j)\in \mathcal{L}$. Since $\boldsymbol{d}$ has to satisfy property \cref{item:litcond1} of \cref{lem:litcond}, we know that $\pcomp{R}{j}$ must be an element of the set
\begin{equation*}
	A_j := \{\pcomp{i}{j} \, :\,  i\in \sinterval{R-2}, \, (i,j)\in \mathcal{L}, \, \pcomp{i}{j} \mid b_{R-1} - b_{i}\}
\end{equation*}
(recalling that $\pcomp{R}{j} = \pcomp{(R-1)}{j}$, and thus $b_{R-1} = \sum_{k<R-1} d_k \equiv b_{R}\pmod {\pcomp{R}{j}}$). Note that this set $A_j$ depends only on $\boldsymbol{d}'$ and $\mathcal{L}$, which are fixed.

For $j\in J_{\mathcal{U}}$, we know that $\pcomp{R}{j} \mid \fprod{\boldsymbol{d}'}$, so $\pcomp{R}{j}$ must be chosen in the set $\{\pcomp{1}{j}, \pcomp{2}{j}, \ldots, \pcomp{(R-2)}{j}\}$. Thus, there are $\leqslant R$ possibilities for $\pcomp{R}{j}$ when $j\in J_{\mathcal{U}}$.

Putting everything together, we obtain that 
\begin{equation}
\label{eq:intermediateinsert}
	\sum_{\boldsymbol{d} \in \mathrm{Ext}(\boldsymbol{d}')}  \prod_{\substack{p\mid \fprod{\boldsymbol{d}}\\ p\nmid \fprod{\boldsymbol{d}'}}} \frac{1}{p} \leqslant 2 V^{\abs{J_{\mathcal{N}}}}R^{\abs{J_{\mathcal{U}}}} \prod_{j\in J_{\mathcal{L}}} \abs{A_j}.
\end{equation}
By the AM-GM inequality, we have
\begin{equation*}
	\bigg(\prod_{j\in J_{\mathcal{L}}} \abs{A_j}\bigg)^{1/\abs{J_{\mathcal{L}}}} \leqslant \frac{1}{\abs{J_{\mathcal{L}}}} \sum_{j\in J_{\mathcal{L}}} \abs{A_j} = \frac{1}{\abs{J_{\mathcal{L}}}} \bigg\lvert\bigsqcup_{j\in J_{\mathcal{L}}} A_j\bigg\rvert.
\end{equation*}
This is a disjoint union as $A_j \subset \mathcal{P}_j$ for all $j\in J_{\mathcal{L}}$, and the sets $\mathcal{P}_j$ are disjoint. Clearly, $\bigsqcup_{j\in J_{\mathcal{L}}} A_j$ is contained in the set of all $p\mid \fprod{\boldsymbol{d}'}$ for which there is an index $(i,j)\in \mathcal{L}$, with $i\leqslant R-2$, such that $p = \pcomp{i}{j}$ and $p\mid b_i - b_{R-1}$. If~$\big\lvert{\bigsqcup_{j\in J_{\mathcal{L}}} A_j} \big\rvert> 2J V$, no extension $\boldsymbol{d}$ of $\boldsymbol{d}'$ can be in $\mathrm{Ext}(\boldsymbol{d}')$ as such a $\boldsymbol{d}$ will not satisfy property~\cref{item:litcond2} of \cref{lem:litcond}. Thus, in this case, $\mathrm{Ext}(\boldsymbol{d}')$ is empty and there is nothing to prove. Otherwise, we have 
\begin{equation*}
	\bigg\lvert\bigsqcup_{j\in J_{\mathcal{L}}} A_j\bigg\rvert \leqslant 2JV.
\end{equation*}
Hence, \cref{eq:intermediateinsert} becomes
\begin{equation*}
	\sum_{\boldsymbol{d} \in \mathrm{Ext}(\boldsymbol{d}')}  \prod_{\substack{p\mid \fprod{\boldsymbol{d}}\\ p\nmid \fprod{\boldsymbol{d}'}}} \frac{1}{p} \leqslant 2V^{\abs{J_{\mathcal{N}}}}R^{\abs{J_{\mathcal{U}}}} \left( \frac{2J V}{\abs{J_{\mathcal{L}}}}\right)^{\abs{J_{\mathcal{L}}}} \leqslant e^{O(J)} V^{\abs{J_{\mathcal{N}}} + \abs{J_{\mathcal{L}}}} R^{\abs{J_{\mathcal{U}}}}.
\end{equation*}
This concludes the proof as $\abs{J_{\mathcal{N}}} + \abs{J_{\mathcal{L}}} \leqslant J$.

\label{def:cyclicperm}
Let $0\leqslant h\leqslant R$ and let $\boldsymbol{d}\in \Dsfmix{R}$. We denote by $\tau_h\boldsymbol{d}$ the vector obtained by cyclically permuting the entries of $\boldsymbol{d}$:
\begin{equation*}
	\tau_h\boldsymbol{d}  := (d_{R-h+1}, d_{R-h+2}, \ldots, d_{R}, d_1, d_2, \ldots, d_{R-h}).
\end{equation*}

\label{lem:generation}
Let $\boldsymbol{d}\in \mathbf{D}_{\!K}$ and let $\widetilde{\boldsymbol{d}} \in \Dsfmix{\widetilde{{K}}}$ be the reduced vector. Let $M = (K - \widetilde{{K}})/2$. There is a canonical choice of non-negative integers $h_0,\ldots, h_M$ with $\sum_i h_i = K$ and vectors $\boldsymbol{d}^{(0)}, \ldots, \boldsymbol{d}^{(M)}$ such that
\begin{itemize}
	\item $\boldsymbol{d}^{(0)} = \widetilde{\boldsymbol{d}}$,
	\item $\boldsymbol{d}^{(i+1)}$ is an extension of $\tau_{h_i}\boldsymbol{d}^{(i)}$ for all $i\in \interval{0}{M-1}$,
	\item $\tau_{h_M} \boldsymbol{d}^{(M)} = \boldsymbol{d}$.
\end{itemize}

\label{lem:slugeneration}
Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $\sinterval{K}\times\sinterval{J} = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$. Let $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}$ with reduced vector $\widetilde{\boldsymbol{d}} \in \Dsfmix{\widetilde{{K}}}$. Let $M = (K - \widetilde{{K}})/2$. 

Let $h_0,\ldots, h_M$ and $\boldsymbol{d}^{(0)}, \ldots, \boldsymbol{d}^{(M)}$ be as in \cref{lem:generation}. 

For $m\in \interval{0}{M}$, let $K_m$ be the length of $\boldsymbol{d}^{(m)}$. There is a canonical injection $\iota_m : \sinterval{K_m} \to \sinterval{K}$ such that $d^{(m)}_k = d_{\iota_m(k)}$ for all $k\in \sinterval{K_m}$.\footnote{Note that this map $\iota_m$ may not be increasing, due to the cyclic permutations.} Let $\mathcal{S}_m$, $\mathcal{L}_m$ and $\mathcal{U}_m$ be the sets associated to $\boldsymbol{d}^{(m)}$ as in \cref{lem:reducedlit}.

The following holds.
\begin{enumerate}[label=(\roman*), ref=\roman*]
	\item \label{item:generation1} For all $m\in \interval{0}{M}$, the vector $\boldsymbol{d}^{(m)}$ satisfies properties \cref{item:litcond1} and \cref{item:litcond2} of \cref{lem:litcond}.\footnote{Of course, with $K_m,\mathcal{S}_m,\mathcal{L}_m,\mathcal{U}_m$ in place of $K,\mathcal{S},\mathcal{L},\mathcal{U}$, respectively.} 
	\item \label{item:generation2} For $m\in \interval{0}{M-1}$, let $(J_{\mathcal{N},m}, J_{\mathcal{L},m}, J_{\mathcal{U},m})$ be the type of the extension $\boldsymbol{d}^{(m+1)}$ of $\tau_{h_m}\boldsymbol{d}^{(m)}$. Then 
\begin{equation*}
	\sum_{m\in \interval{0}{M-1}} \abs{J_{\mathcal{U},m}} \leqslant 2\abs{\mathcal{U}}.
\end{equation*}
\end{enumerate}

Property \cref{item:generation1}. Suppose that there are indices $(k,j), (k',j)\in \mathcal{L}_m$ such that $d^{(m)}_{kj} = d^{(m)}_{k'j}$, where $d^{(m)}_{kj}$ is the unique prime in $\mathcal{P}_j$ dividing $d^{(m)}_k$. Then $(\iota(k),j),(\iota(k'),j)\in \mathcal{L}$ and 
\begin{equation*}
	\pcomp{\iota(k)}{j} = d^{(m)}_{kj} = d^{(m)}_{k'j} = \pcomp{\iota(k')}{j}.
\end{equation*}
By property \cref{item:litcond1} of \cref{lem:litcond} applied to $\boldsymbol{d}$, we have $\pcomp{\iota(k)}{j} \mid b_{\iota(k')} - b_{\iota(k)}$, and thus
\begin{equation*}
	d^{(m)}_{kj}\ \Big\vert\, \sum_{l<k'} d^{(m)}_l-\sum_{l<k} d^{(m)}_l,
\end{equation*}
since the expression on the right only differs from $b_{\iota(k')} - b_{\iota(k)}$ by pairs of backtracking steps, which cancel each other out. This proves that $\boldsymbol{d}^{(m)}$ satisfies property \cref{item:litcond1} of \cref{lem:litcond}. The proof that property \cref{item:litcond2} of \cref{lem:litcond} passes down from $\boldsymbol{d}$ to $\boldsymbol{d}^{(m)}$ is analogous and shall be omitted.
\medbreak

Property \cref{item:generation2}. Let us make a preliminary observation. For $0\leqslant m_1 < m_2\leqslant M$, the composition
\begin{equation*}
	\iota_{m_2}^{-1} \circ \iota_{m_1} : \sinterval{K_{m_1}} \to \sinterval{K_{m_2}}
\end{equation*}
is well-defined, injective, and its image is contained in $\sinterval{K_{m_2}-2}$ since the last two entries of $\boldsymbol{d}^{(m_2)}$ correspond to a new backtracking pair. 

For $m\in \interval{0}{M-1}$, by \cref{lem:Junlitanalysis}, we can write $J_{\mathcal{U},m} = J_{\mathcal{U},m}^- \sqcup J_{\mathcal{U},m}^+$, where 
\begin{itemize}
	\item ${J_{\mathcal{U},m}^- = \{j\in \sinterval{J} : (K_{m+1},j)\in \mathcal{U}_{m+1}\}}$, and
	\item $J_{\mathcal{U},m}^+$ is the set of all $j\in \sinterval{J}$ such that $(K_{m+1},j) \not\in\mathcal{U}_{m+1}$ and
	\begin{equation}
	\label{eq:setcontainedinu}
		{\big\{k\in \sinterval{K_{m+1}-2}: \pcomp{K_{m+1}}{j}^{(m+1)} = \pcomp{k}{j}^{(m+1)}\big\}} \times \{j\}
	\end{equation}
	is a non-empty set contained in $\mathcal{U}_{m+1}$.
\end{itemize}

Define a map $F^- : \bigsqcup_{m\in \interval{0}{M-1}} \big(\{m\} \times J_{\mathcal{U},m}^- \big) \to \mathcal{U}$ as follows. For $m\in \interval{0}{M-1}$ and $j\in J_{\mathcal{U},m}$, let $F^-(m,j) := (\iota_{m+1}(K_{m+1}),j)$. We know that $(K_{m+1},j)\in \mathcal{U}_{m+1}$, so $(\iota_{m+1}(K_{m+1}),j)$ is indeed in $\mathcal{U}$. Note that $\iota_{m+1}(K_{m+1})$ uniquely determines $m$. To check this, note that there cannot exist $1\leqslant m_1 < m_2\leqslant M$ such that $\iota_{m_1}(K_{m_1}) = \iota_{m_2}(K_{m_2})$ by our preliminary observation. Hence, $F^-$ is injective, and thus 
\begin{equation*}
	\sum_{m\in \interval{0}{M-1}} \lvert{J_{\mathcal{U},m}^-}\rvert \leqslant \abs{\mathcal{U}}.
\end{equation*}

Define a map $F^+ : \bigsqcup_{m\in \interval{0}{M-1}} \big(\{m\} \times J_{\mathcal{U},m}^+\big) \to \mathcal{U}$ as follows. For $m\in \interval{0}{M-1}$ and ${j\in J_{\mathcal{U},m}}$, let $(k_{m+1},j)$ be any element in the (non-empty) set \cref{eq:setcontainedinu}, and define $F^+(m,j) := (\iota_{{m+1}}(k_{m+1}),j)$. Since $(k_{m+1},j)\in \mathcal{U}_{m+1}$, we know that $(\iota_{{m+1}}(k_{m+1}),j)\in \mathcal{U}$, so $F^+$ is well-defined. 

We shall prove that $F^+$ is an injective map. Suppose that ${(\iota_{m_1}(k_{m_1}),j) = (\iota_{m_2}(k_{m_2}),j)}$ for some ${1\leqslant m_1<m_2\leqslant M}$ and $j\in J_{\mathcal{U},m_1-1}^+\cap J_{\mathcal{U},m_2-1}^+$. Let $\iota := \iota_{m_2}^{-1} \circ \iota_{m_1} : \sinterval{K_{m_1}} \to \sinterval{K_{m_2}}$.	 
By definition of $\iota$, $\iota_{m_1}$, $\iota_{m_2}$, $k_{m_1}$ and $k_{m_2}$, and using the equality $\iota_{m_1}(k_{m_1}) = \iota_{m_2}(k_{m_2})$, we have
\begin{equation*}
 	\pcomp{\iota(K_{m_1})}{j}^{(m_2)} = \pcomp{K_{m_1}}{j}^{(m_1)} = \pcomp{k_{m_1}}{j}^{(m_1)} = \pcomp{\iota_{m_1}(k_{m_1})}{j} = \pcomp{\iota_{m_2}(k_{m_2})}{j} = \pcomp{k_{m_2}}{j}^{(m_2)} = \pcomp{K_{m_2}}{j}^{(m_2)}.
\end{equation*}
Recall, moreover, that $\iota(K_{m_1}) \in \sinterval{K_{m_2}-2}$ by our preliminary observation. Therefore, the pair $(\iota(K_{m_1}),j)$ in the set \cref{eq:setcontainedinu}, with $m_2$ in place of $m+1$. Since $j\in  J_{\mathcal{U},m_2-1}^+$, that set is contained in $\mathcal{U}_{m_2}$, so $(\iota(K_{m_1}),j)\in \mathcal{U}_{m_2}$. 

On the other hand, since $j\in J_{\mathcal{U},m_1-1}^+$, we have $(K_{m_1},j) \not\in \mathcal{U}_{m_1}$, by definition of $J_{\mathcal{U},m_1-1}^+$. In addition, $(K_{m_1},j) \not\in \mathcal{S}_{m_1}$ as $\pcomp{(K_{m_1}-1)}{j} = \pcomp{K_{m_1}}{j}$. Thus, $(K_{m_1},j)$ has to be $\mathcal{L}_{m_1}$. Hence, $(\iota(K_{m_1}),j)\in \mathcal{L}_{m_2}$, which contradicts the fact that $(\iota(K_{m_1}),j)\in \mathcal{U}_{m_2}$. 

Therefore, $F^+$ is injective, so 	
\begin{equation*}
	\sum_{m\in \interval{0}{M-1}} \lvert{J_{\mathcal{U},m}^+}\rvert \leqslant \abs{\mathcal{U}}
\end{equation*}
which is what we had to show.

\label{lem:backtrackingreconstruction}
Let $\mathcal{S}$, $\mathcal{L}$, $\mathcal{U}$ be sets such that $\sinterval{K}\times\sinterval{J} = \mathcal{S}\sqcup\mathcal{L}\sqcup\mathcal{U}$ and $|\mathcal{U}| \leqslant K^{2\varepsilon_1}$. Let $0\leqslant R \leqslant K$ and let $\boldsymbol{d}'\in (\pm \mathcal{D})^{R}$.

Then
\begin{equation*}
	\sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}\\ \widetilde{\boldsymbol{d}} = \boldsymbol{d}'}}\, \prod_{\substack{p\mid \fprod{\boldsymbol{d}} \\ p\nmid \fprod{\boldsymbol{d}'}}} \frac{1}{p} \ll e^{O(KJ)} V^{(K-R)J/2},
\end{equation*}
where $\widetilde{\boldsymbol{d}}$ is the reduced vector associated to $\boldsymbol{d}$ (see \cref{def:backtracking}).

Let $M := (K - R)/2$. By \cref{lem:generation}, any $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}$ with $\widetilde{\boldsymbol{d}} = \boldsymbol{d}'$ is obtained from $\boldsymbol{d}'$ by a succession of cyclic permutations and extensions. We sum over all possibilities for the integers $h_0, \ldots, h_M$ characterising the cyclic permutations, and for the types $(J_{\mathcal{N},m}, J_{\mathcal{L},m}, J_{\mathcal{U},m})$ of these extensions. There are $e^{O(K)}$ tuples of non-negative integers $(h_0, \ldots, h_M)$ with sum $\leqslant K$. For every $m\in \interval{0}{M-1}$, there are $e^{O(J)}$ decompositions of $\sinterval{J}$ into three sets $\sinterval{J} = J_{\mathcal{N},m} \sqcup J_{\mathcal{L},m} \sqcup J_{\mathcal{U},m}$. Thus, there are $e^{O(KJ)}$ possibilities for $h_0, \ldots, h_M$ and $(J_{\mathcal{N},m}, J_{\mathcal{L},m}, J_{\mathcal{U},m})_{m\in \interval{0}{M-1}}$.

Fix some $h_0, \ldots, h_M$ and $(J_{\mathcal{N},m}, J_{\mathcal{L},m}, J_{\mathcal{U},m})_{m\in \interval{0}{M-1}}$. By part \cref{item:generation2} of \cref{lem:slugeneration}, we may assume that 
\begin{equation}
\label{eq:boundsumJunlit}
	\sum_{m\in \interval{0}{M-1}} \abs{J_{\mathcal{U},m}} \leqslant 2\abs{\mathcal{U}}.
\end{equation}
The remaining task is to show that the sum in the statement, restricted to those $\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}$ generated from $\boldsymbol{d}'$ via the cyclic permutations $\tau_{h_0}, \ldots, \tau_{h_M}$ and extensions of types $(J_{\mathcal{N},m}, J_{\mathcal{L},m}, J_{\mathcal{U},m})$, is at most $e^{O(KJ)} V^{MJ}$. 
We do so by repeatedly applying \cref{lem:onepairbacktracking} to obtain the bound
\begin{equation*}
	\prod_{m\in \interval{0}{M-1}} e^{O(J)} V^{J} K^{\abs{J_{\mathcal{U},m}}} \leqslant e^{O(KJ)} V^{MJ} K^{\sum_{m\in \interval{0}{M-1}} \abs{J_{\mathcal{U},m}}}.
\end{equation*}
Note that we have used part \cref{item:generation1} of \cref{lem:slugeneration} to be able to apply \cref{lem:onepairbacktracking}. By \cref{eq:boundsumJunlit}, and since $|\mathcal{U}| \leqslant K^{2\varepsilon_1}$, the term $K^{\sum_{m\in \interval{0}{M-1}} \abs{J_{\mathcal{U},m}}}$ is $e^{O(K)}$. This concludes the proof.

\begin{equation*}
	\prod_{m\in \interval{0}{M-1}} e^{O(J)} V^{J} K^{\abs{J_{\mathcal{U},m}}} \leqslant e^{O(KJ)} V^{MJ} K^{\sum_{m\in \interval{0}{M-1}} \abs{J_{\mathcal{U},m}}}.
\end{equation*}

The weighted graph $G$ introduced in \cref{def:Gamma} satisfies the first two properties of \cref{prop:smalltrace}: the first one by \cref{lem:introducingcutoff}, and the second by construction.

For the trace bound, we have, by \cref{lem:reductiontocountingpb}, that
\begin{equation*}
	\mathrm{Tr} \big((\mathrm{Ad}_{G})^{K}\big) \leqslant  \sup_{\substack{\mathcal{S}\sqcup \mathcal{L}\sqcup \mathcal{U} = \sinterval{K}\times\sinterval{J}\\ |\mathcal{U}| <K^{2\varepsilon_1}}}\,e^{O(K J)} N V^{-|\mathcal{S}|/2}  \sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}}}\,\prod_{p\mid \fprod{\boldsymbol{d}}} \frac{1}{p}.
\end{equation*}
Fix some sets $\mathcal{S}$, $\mathcal{L}$ and $\mathcal{U}$ with $\mathcal{S}\sqcup \mathcal{L}\sqcup \mathcal{U} = \sinterval{K}\times\sinterval{J}$ and $|\mathcal{U}| <K^{2\varepsilon_1}$. It remains to show that
\begin{equation}
\label{eq:tracesectionten}
	  \sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}}}\,\prod_{p\mid \fprod{\boldsymbol{d}}} \frac{1}{p} \leqslant e^{O(K J)} V^{|\mathcal{S}|/2} V^{2KJ/3}.
\end{equation}
To do this, we sum over the backtracking and non-backtracking parts separately. We first sum over all possibilities for the length $R$ of the reduced walk, and the sets $\mathcal{S}'$, $\mathcal{L}'$ and $\mathcal{U}'$ associated to the reduced walk (see \cref{lem:reducedlit}). We then sum over all possibilities $\boldsymbol{d}'$ for the reduced walk given this data, and finally over all $\boldsymbol{d}$ with reduced walk $\widetilde{\boldsymbol{d}} = \boldsymbol{d}'$. This gives
\begin{equation}
\label{eq:afterdividebnb}
 	\sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}}}\,\prod_{p\mid \fprod{\boldsymbol{d}}} \frac{1}{p} = \sum_{0\leqslant R\leqslant K}\, \sum_{\substack{\sinterval{R}\times \sinterval{J} = \mathcal{S}'\sqcup \mathcal{L}'\sqcup \mathcal{U}'}} \, \sum_{\boldsymbol{d}' \in \widetilde{\mathbf{D}}^{\mathcal{S}',\mathcal{L}'}_{\!R}} \, \prod_{p\mid \fprod{\boldsymbol{d}'}} \frac{1}{p}\, \sum_{\substack{\boldsymbol{d} \in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}\\ \widetilde{\boldsymbol{d}} = \boldsymbol{d}'}}\, \prod_{\substack{p\mid \fprod{\boldsymbol{d}} \\ p\nmid \fprod{\boldsymbol{d}'}}} \frac{1}{p}.
\end{equation}
By \cref{lem:reducedlit}, we may add the constraints $\abs{\mathcal{U}'}\leqslant K^{2\varepsilon_1}$ and $|\mathcal{S}| \leqslant |\mathcal{S}'| \leqslant |\mathcal{S}| + \tfrac13 K J$ to the second sum. 

By \cref{lem:backtrackingreconstruction}, the innermost sum in \cref{eq:afterdividebnb} satisfies
\begin{equation*}
	\sum_{\substack{\boldsymbol{d}\in \mathbf{D}^{\mathcal{S},\mathcal{L}}_{\!K}\\ \widetilde{\boldsymbol{d}} = \boldsymbol{d}'}}\, \prod_{\substack{p\mid \fprod{\boldsymbol{d}} \\ p\nmid \fprod{\boldsymbol{d}'}}} \frac{1}{p} \ll e^{O(KJ)} V^{(K-R)J/2}.
\end{equation*}
We can split the sum over non-backtracking walks $\boldsymbol{d}'$ as a sum over predictable walks, and a sum over unpredictable walks:
\begin{equation*}
	\sum_{\boldsymbol{d}' \in \widetilde{\mathbf{D}}^{\mathcal{S}',\mathcal{L}'}_{\!R}} \, \prod_{p\mid \fprod{\boldsymbol{d}'}} \frac{1}{p} =  \sum_{\substack{\boldsymbol{d}' \in \mathbf{P}_{\!R}}} \, \prod_{p\mid \fprod{\boldsymbol{d}'}} \frac{1}{p} + \sum_{\substack{\boldsymbol{d}'\in \mathbf{U}_{\!R}}}\,\prod_{p\mid \fprod{\boldsymbol{d}'}}\, \frac{1}{p}.
\end{equation*}
The first and second sums on the right-hand side are $\ll e^{O(KJ)}V^{|\mathcal{S}'|+(\abs{\mathcal{L}'}+\abs{\mathcal{U}'})/2}$ and $\ll 1$ respectively, by \cref{prop:predictablevector} and \cref{lem:unpredictable}.

Putting everything together, we obtain that \cref{eq:afterdividebnb} is
\begin{equation*}
	\leqslant e^{O(KJ)}\sum_{0\leqslant R\leqslant K}\, \sum_{\substack{\sinterval{R}\times \sinterval{J} = \mathcal{S}'\sqcup \mathcal{L}'\sqcup \mathcal{U}'\\ \abs{\mathcal{U}'}\leqslant K^{2\varepsilon_1}\\ |\mathcal{S}| \leqslant |\mathcal{S}'| \leqslant |\mathcal{S}| +K J/3}} V^{(K-R)J/2} V^{|\mathcal{S}'|+(\abs{\mathcal{L}'}+\abs{\mathcal{U}'})/2}.
\end{equation*}
Note that
\begin{align*}
	\tfrac12 (K-R)J + |\mathcal{S}'| + \tfrac12 (\abs{\mathcal{L}'}+\abs{\mathcal{U}'}) &=\tfrac12 (K-R)J + \tfrac12 |\mathcal{S}'| + \tfrac12R J\\
	&= \tfrac12 KJ +  \tfrac12 |\mathcal{S}'|\\
	&\leqslant \tfrac23 KJ + \tfrac12 |\mathcal{S}|,
\end{align*}
using $|\mathcal{S}'| \leqslant |\mathcal{S}| +K J/3$ for the last inequality. Since there are $\leqslant e^{O(KJ)}$ choices for $R$, $\mathcal{S}'$, $\mathcal{L}'$ and $\mathcal{U}'$, we exactly get \cref{eq:tracesectionten}. This finishes the proof of \cref{prop:smalltrace}.

\begin{equation*}
	\leqslant e^{O(KJ)}\sum_{0\leqslant R\leqslant K}\, \sum_{\substack{\sinterval{R}\times \sinterval{J} = \mathcal{S}'\sqcup \mathcal{L}'\sqcup \mathcal{U}'\\ \abs{\mathcal{U}'}\leqslant K^{2\varepsilon_1}\\ |\mathcal{S}| \leqslant |\mathcal{S}'| \leqslant |\mathcal{S}| +K J/3}} V^{(K-R)J/2} V^{|\mathcal{S}'|+(\abs{\mathcal{L}'}+\abs{\mathcal{U}'})/2}.
\end{equation*}

Let $\sigma \in \{\pm1\}^{R}$ be a sequence of signs and let $\Pi$ be a partition of $\sinterval{R} \!\times\! \sinterval{J}$. For $t\in \sinterval{T}$, let $I_t\subset \sinterval{R}$ be a union of at most three discrete intervals and let $(i_t,j_t)\in \sinterval{R} \!\times\! \sinterval{J}$. Let $\kappa\in \interval{-B}{B}$. Let $f : \sinterval{T} \to \Pi$. We define $\mathbf{T}_{(\sigma,\Pi, (I_t),(i_t),(j_t),\kappa,f)}$ to be the set of all $\boldsymbol{d}\in \mathbf{T}$ such that 
\begin{itemize}
	\item $\mathrm{sign}(d_i) = \sigma_i$ for $i\in \sinterval{R}$;
	\item for all $(i,j), (i',j')\in \sinterval{R} \!\times\! \sinterval{J}$, $\pcomp{i}{j} =\pcomp{i'}{j'}$ iff $(i,j)$ and $(i',j')$ are in the same class in $\Pi$;\footnote{Recall from \cref{def:constraints}, that for $(i,j)\in \sinterval{R} \!\times\! \sinterval{J}$, write $\pcomp{i}{j}$ for the unique prime in $\mathcal{P}_j$ dividing $d_i$.}
	\item the constraints $(C_{t} (\boldsymbol{d}))_{t\in \sinterval{T}}$ are satisfied by $\boldsymbol{d}$, where $C_t(\boldsymbol{d})$ is short for $C_{I_t, i_t, j_t, \kappa} (\boldsymbol{d})$;
	\item for $t\in \sinterval{T}$, the prime\footnote{For $\alpha\in \Pi$, we write $d_{\alpha}$ for the prime $\pcomp{i}{j}$, where $(i,j)$ is any element of~$\alpha$; this is well-defined by construction.} $d_{f(t)}$ is involved in $C_{t}(\boldsymbol{d})$ but absent from $C_s(\boldsymbol{d})$ for $s<t$.
\end{itemize}
We will show that, for each such choice of $\sigma,\Pi, (I_t),(i_t),(j_t),\kappa,f$, we have
\begin{equation}
\label{eq:toproveinconstraints}
	\sum_{\boldsymbol{d}\in \mathbf{T}_{(\sigma,\Pi, (I_t),(i_t),(j_t),\kappa,f)}}  \prod_{p\mid \fprod{\boldsymbol{d}}} \frac1p \leqslant  V^{R J} H_0^{-T/2}.
\end{equation}
This is enough to prove \cref{lem:constraints}. Indeed, $\mathbf{T}$ is contained in the union of $\mathbf{T}_{(\sigma,\Pi, (I_t),(i_t),(j_t),\kappa,f)}$ over all possible choices of $\sigma,\Pi, (I_t),(i_t),(j_t),\kappa$ and $f$. Hence, to bound the sum over $\boldsymbol{d}\in \mathbf{T}$, it suffices to multiply the right-hand side of \cref{eq:toproveinconstraints} by the number of possibilities for these parameters. There are $2^{R}$ choices for $\sigma$. The number of partitions of $\sinterval{R} \!\times\! \sinterval{J}$ is $\leqslant (RJ)^{R J}$. For $t\in \sinterval{T}$, since $I_t$ is a union of at most three discrete intervals, it is uniquely determined by six elements of $\sinterval{R}$. Thus, the number of choices for $(I_t, i_t, j_t)_{t\in \sinterval{T}}$ is $\leqslant (R^{6}RJ)^{T}$. There are $\leqslant 2B+1$ choices for $\kappa\in \interval{-B}{B}$. Any function $f :  \sinterval{T} \to \Pi$ induces a function $\sinterval{T} \to\sinterval{R} \!\times\! \sinterval{J}$ which uniquely determines $f$, so there are $\leqslant (R J)^{T}$ possibilities for $f$. Therefore, assuming \cref{eq:toproveinconstraints}, we have
\begin{equation*}
	\sum_{\boldsymbol{d}\in \mathbf{T}} \prod_{p\mid \fprod{\boldsymbol{d}}} \frac1p \leqslant 3B \, 2^{R} (R J)^{R J+8T} V^{R J} H_0^{-T/2}.
\end{equation*}
By property \cref{item:primesets7} of \cref{lem:primesets} and the inequality $(a/n)^n\leqslant e^a$, we have $V^{J} \leqslant K$. Using $T \leqslant R \leqslant 2K$ and $J \ll \log\log H$, we can simplify the above to obtain
\begin{equation*}
	\sum_{\boldsymbol{d}\in \mathbf{T}} \prod_{p\mid \fprod{\boldsymbol{d}}} \frac1p \ll B K^{11R J} H_0^{-T/2}
\end{equation*}
as desired.

It remains to prove \cref{eq:toproveinconstraints}. Let $\sigma,\Pi, (I_t),(i_t),(j_t),\kappa$ and $f$ be such that the set $\mathbf{T}_{(\sigma,\Pi, (I_t),(i_t),(j_t),\kappa,f)}$ (which will henceforth be denoted by $\mathbf{T}_*$) is non-empty. Note that every class $\alpha$ of $\Pi$ is contained in $\sinterval{R} \!\times\!  \{j(\alpha)\}$ for some $j(\alpha)\in \sinterval{J}$, which is the unique integer such that $d_{\alpha} \in \mathcal{P}_{\!j(\alpha)}$ for all $\boldsymbol{d} \in \mathbf{T}_*$.

Any $\boldsymbol{d} \in\mathbf{T}_*$ is uniquely determined by the sequence of primes $(d_{\alpha})_{\alpha\in \Pi}$. 

Let $\Pi_0 := \Pi\setminus \{f(t) : t\in \sinterval{T}\}$ and, for $t\in \sinterval{T}$, let $\Pi_t := \Pi_{t-1} \cup \{f(t)\}$. 

Let $W_0$ be the set of all sequences $(p_{\alpha})_{\alpha\in \Pi_0}$ with $p_{\alpha}\in \mathcal{P}_{\!j(\alpha)}$ for all $\alpha\in \Pi_0$. For any $t\in \sinterval{T}$ and any sequence of primes $(p_{\alpha})_{\alpha\in \Pi_{t-1}}$, we define $W_t\big[ (p_{\alpha})_{\alpha\in \Pi_{t-1}}\big]$ to be the set of all primes ${p\in \mathcal{P}_{\!j(f(t))}}$ for which there is some $\boldsymbol{d}\in\mathbf{T}_*$ such that $d_{\alpha} = p_{\alpha}$ for all $\alpha\in \Pi_{t-1}$ and $d_{f(t)} = p$. 

Then, we have
\begin{equation}
\label{eq:nestedsums}
	\sum_{\boldsymbol{d}\in\mathbf{T}_*} \prod_{p\mid \fprod{\boldsymbol{d}}} \frac1p =
	\sum_{(p_{\alpha})\in W_0} \bigg(\prod_{\alpha\in \Pi_0} \frac{1}{p_{\alpha}} \bigg) \sum_{p_{f(1)}\in W_1} \frac{1}{p_{f(1)}} 
	 \sum_{p_{f(2)}\in W_2} \frac{1}{p_{f(2)}} \cdots \sum_{p_{f(T)}\in W_{T}} \frac{1}{p_{f(T)}}, 
\end{equation}
writing $W_t$ instead of $W_t\big[ (p_{\alpha})_{\alpha\in \Pi_{t-1}}\big]$ to shorten notation.

Fix some $t\in \sinterval{T}$ and some sequence $(p_{\alpha})_{\alpha\in \Pi_{t-1}}$. We claim that  
\begin{equation}
\label{eq:sumwithcond}
	\sum_{p\in W_t} \frac{1}{p} \leqslant H_0^{-1/2}.
\end{equation}
Recall that, for any $p\in W_t$, there is some $\boldsymbol{d}\in\mathbf{T}_*$ with $d_{\alpha} = p_{\alpha}$ for all $\alpha\in \Pi_{t-1}$ and $d_{f(t)} = p$. In particular, $p$ is involved in $C_t(\boldsymbol{d})$. By \cref{def:involved}, this means that $p$ is \cref{item:const1}-involved, \cref{item:const2}-involved or \cref{item:const3}-involved in $C_t(\boldsymbol{d})$.

If $p$ is \cref{item:const1}-involved in $C_t(\boldsymbol{d})$, then by definition $\sum_{i\in I_t} d_i = 0$ and $\sum_{{i\in I_t,\, p \mid d_i}} d_i \neq 0$. This means that $p$ satisfies the linear equation $Ap + B = 0$ where
\begin{equation*}
	A := \frac{1}{p}\sum_{\substack{i\in I_t\\ p \mid d_i}} d_i\qquad\text{and}\qquad B := \sum_{\substack{i\in I_t\\ p \nmid d_i}} d_i.
\end{equation*}
Observe that $A$ and $B$ are explicit expressions of the primes $(p_{\alpha})_{\alpha\in \Pi_{t-1}}$. Indeed, $f(t)$ is of the form ${f(t) = Z_t \times \{j(f(t))\}}$ for some $Z_t\subset \sinterval{R}$, and we may rewrite
\begin{equation*}
	A = \sum_{i\in I_t \cap Z_t} \prod_{\substack{j\in \sinterval{J}\setminus j(f(t))}} \pcomp{i}{j} \qquad\text{and}\qquad B = \sum_{i\in I_t\setminus Z_t} \prod_{j\in \sinterval{J}} \pcomp{i}{j}.
\end{equation*}
By definition of $f(t)$, the prime $p = d_{f(t)}$ does not appear in $A$ or $B$. By construction, the primes $d_{f(t+1)} ,.., d_{f(T)}$ are absent from $C_t(\boldsymbol{d})$, which means that $d_{f(t+1)} ,..., d_{f(T)}$ cannot be any of the primes $\pcomp{i}{j}$ occurring in $A$ or $B$ either. Hence, $A$ and $B$ are fully determined by the primes $(p_{\alpha})_{\alpha\in \Pi_{t-1}}$. Since $A\neq 0$ by assumption, the equation $Ap + B = 0$ has at most one solution $p$ in $\mathcal{P}_{\!j(f(t))}$. 

If $p$ is \cref{item:const2}-involved in $C_t(\boldsymbol{d})$, we know that $p$ must be a prime divisor of 
\begin{equation*}
	A := \sum_{\substack{i\in I_t\\ p \nmid d_i}} d_i,
\end{equation*}
and that $A\neq 0$. As before, $A$ is can be explicitly computed from the primes $(p_{\alpha})_{\alpha\in \Pi_{t-1}}$. Note that $A$ is non-zero by assumption, and $\abs{A} \leqslant R H$, so $A$ has at most $\log_2(R K)$ prime factors.

Finally, if $p$ is \cref{item:const3}-involved in $C_t(\boldsymbol{d})$, we have $\pcomp{i_t}{j_t} \mid A p + B + \kappa$ with $A$ and $B$ as in case~\cref{item:const1}, but this time we assume that $A$ is not divisible by $\pcomp{i_t}{j_t}$. Once again, $\pcomp{i_t}{j_t}$, $A$ and $B$ only depend on the primes $(p_{\alpha})_{\alpha\in \Pi_{t-1}}$, and $\kappa$ is fixed. Thus, this divisibility condition uniquely determines the congruence class of $p$ modulo the prime $\pcomp{i_t}{j_t}$. Using that $\mathcal{P} \subset (H_0, H)$, we have, for any $x$,
\begin{equation*}
	\sum_{\substack{p\in \mathcal{P} \\ p \equiv x\!\!\!\!\pmod{\pcomp{i_t}{j_t}}}} \frac{1}{p} \leqslant \sum_{\substack{1\leqslant n\leqslant H \\ n\equiv 1\!\!\!\! \pmod{H_0}}} \frac{1}{n} \leqslant \frac{10\log H}{H_0}.
\end{equation*}

Gathering the three cases, we conclude that 
\begin{equation*}
	\sum_{p\in W_t} \frac{1}{p} \leqslant \frac{1}{H_0} + \frac{\log_2(R H)}{H_0} + \frac{10\log H}{H_0} \leqslant H_0^{-1/2},
\end{equation*}
so \cref{eq:sumwithcond} is proved. Using this fact in \cref{eq:nestedsums} successively for $t = T, \,T-1,\,\ldots, \, 1$ yields
\begin{equation*}
	\sum_{\boldsymbol{d}\in\mathbf{T}_*} \prod_{p\mid \fprod{\boldsymbol{d}}} \frac1p \leqslant H_0^{-T/2}\sum_{(p_{\alpha})\in W_0} \prod_{\alpha\in \Pi_0} \frac{1}{p_{\alpha}} = H_0^{-T/2} \prod_{\alpha\in \Pi_0} V_{j(\alpha)} \leqslant H_0^{-T/2} V^{\abs{\Pi_0}}.
\end{equation*}
Equation \cref{eq:toproveinconstraints} follows, which concludes the proof.

