	A = \sum_{i\in I_t \cap Z_t} \prod_{\substack{j\in \sinterval{J}\setminus j(f(t))}} \pcomp{i}{j} \qquad\text{and}\qquad B = \sum_{i\in I_t\setminus Z_t} \prod_{j\in \sinterval{J}} \pcomp{i}{j}.
