\label{lem:sieveidentity}
Let $\mathcal{Y}$ be a finite set of arithmetic progressions in $\mathbb{Z}$. Let $\mathcal{X}$ be a non-empty collection of subsets of $\mathcal{Y}$ which is closed under containment, i.e.~if $S \in \mathcal{X}$ and $S' \subset S$ then $S' \in \mathcal{X}$. 
\begin{enumerate}
	\item If $n\not\in P$ for all $P\in \mathcal{Y}$, then
	\begin{equation*}
		\ind{n\not\in P\  \forall P\in \mathcal{Y}} = 1 = \sum_{S\in \mathcal{X}} (-1)^{|S|} \ind{n \in \cap S}.
	\end{equation*}
	\item If $n\in P_0$ for some progression $P_0\in \mathcal{Y}$, then
	\begin{equation}
		\label{eq:sieveidentity}
		\ind{n\not\in P\  \forall P\in \mathcal{Y}}  = 0  = \sum_{S\in \mathcal{X}} (-1)^{|S|} \ind{n \in \cap S}  + \sum_{\substack{P_0\in S \subset \mathcal{Y}\\ S \not\in \mathcal{X},\, S\setminus \{P_0\} \in \mathcal{X}}} (-1)^{|S|} \ind{n\in \cap S}.
	\end{equation}
\end{enumerate}

