\label{lem:rota}
Let $\mathcal{A}$ be any collection of subsets of a finite set $\Omega$. Then 
\begin{equation*}
\abs{\sum_{\substack{\mathcal{B} \subset \mathcal{A}\\ \cup \mathcal{B} = \Omega}} (-1)^{|\mathcal{B}|} } \leqslant 2^{|\Omega|}.
\end{equation*}

Observe that, given two finite sets $\Omega_1\subset \Omega_2$, we have
\begin{equation}
\label{eq:trickforcancellation}
(-1)^{|\Omega_1|} \sum_{\Omega_1 \subset W \subset \Omega_2} (-1)^{|W|} = \ind{\Omega_1=\Omega_2}.
\end{equation}
Indeed, this is obvious if $\Omega_1 = \Omega_2$, and if $\Omega_1\neq \Omega_2$ the left-hand side is the expanded form of $(1-1)^{|\Omega_2\setminus \Omega_1|}$. 

This allows us to write
\begin{equation*}
\abs{\sum_{\substack{\mathcal{B} \subset \mathcal{A}\\ \cup \mathcal{B} = \Omega}} (-1)^{|\mathcal{B}|} } = \abs{\sum_{\mathcal{B} \subset \mathcal{A} } (-1)^{|\mathcal{B}|} \sum_{\cup \mathcal{B} \subset W \subset \Omega} (-1)^{|W|} } = \abs{\sum_{W\subset \Omega } (-1)^{|W|} \sum_{\substack{\mathcal{B} \subset \mathcal{A}\\ \cup \mathcal{B} \subset W}} (-1)^{|\mathcal{B}|} }.
\end{equation*}
The inner sum has the shape of \cref{eq:trickforcancellation}, with $\Omega_1 = \emptyset$ and $\Omega_2 = \{A\in \mathcal{A} \mid A\subset W\}$, so is at most $1$ in absolute value. Since the outer sum has $\leqslant 2^{|\Omega|}$ terms, the claim follows.

\label{prop:sievesquare-free}
Let $\mathcal{Y}$ be a finite set of arithmetic progressions in $\mathbb{Z}$ with square-free moduli. Let 
\begin{equation*}
\mathcal{Y}^{\cap} := \{\cap S : S \subset \mathcal{Y}\}.
\end{equation*}

Fix a non-empty subset $X \subset \mathcal{Y}^{\cap}$ that is closed under containment, i.e.~if a progression $P\in \mathcal{Y}^{\cap}$ is an element of $X$, then so are all $P'\in \mathcal{Y}^{\cap}$ with $P' \supset P$. Let $\mathcal{X}$ be the collection of subsets of $\mathcal{Y}$ defined by\footnote{Note that $\emptyset \in \mathcal{X}$ since $\cap \emptyset = \mathbb{Z}$ by convention.}
\begin{equation*}
\mathcal{X} = \{S \subset \mathcal{Y}: \cap S \in X\}.
\end{equation*}
Then
\begin{equation}
\label{eq:bonferronilike}
	\ind{n\not\in P\  \forall P\in \mathcal{Y}}  = \sum_{S\in \mathcal{X}} (-1)^{|S|} \ind{n \in \cap S}  + O \left(\sum_{R\in \partial X }  3^{\omega(q_{R})} \ind{n\in R}\right)
\end{equation}
where
\begin{equation*}
\partial X := \{R\in \mathcal{Y}^{\cap}: R\not\in X \text{ and }R = P\cap P'\text{ for some } P\in X \text{ and }P'\in \mathcal{Y} \}.
\end{equation*}
Moreover, the first sum can be rewritten as
\begin{equation*}
\sum_{S\in \mathcal{X}} (-1)^{|S|} \ind{n \in \cap S} = \sum_{P\in X } c_{P} \ind{n\in P}
\end{equation*}
for some coefficients $c_{P}\in \mathbb{Z}$ satisfying $|c_{P}| \leqslant 2^{\omega(q_{P})}$.

\begin{equation}
\label{eq:bonferronilike}
	\ind{n\not\in P\  \forall P\in \mathcal{Y}}  = \sum_{S\in \mathcal{X}} (-1)^{|S|} \ind{n \in \cap S}  + O \left(\sum_{R\in \partial X }  3^{\omega(q_{R})} \ind{n\in R}\right)
\end{equation}

\begin{equation*}
\partial X := \{R\in \mathcal{Y}^{\cap}: R\not\in X \text{ and }R = P\cap P'\text{ for some } P\in X \text{ and }P'\in \mathcal{Y} \}.
\end{equation*}

If the left-hand side of \cref{eq:bonferronilike} is $1$, then the equality \cref{eq:bonferronilike} is true by \cref{lem:sieveidentity}. On the other hand, if the left-hand side is $0$, then by \cref{lem:sieveidentity} we have
\begin{equation*}
\ind{n\not\in P\  \forall P\in \mathcal{Y}}  = \sum_{S\in \mathcal{X}} (-1)^{|S|} \ind{n \in \cap S}  +  \sum_{\substack{P_0\in S \subset \mathcal{Y}\\ S \not\in \mathcal{X},\, S\setminus \{P_0\} \in \mathcal{X}}} (-1)^{|S|} \ind{n\in \cap S},
\end{equation*}
where, in the last sum, $P_0 \in \mathcal{Y}$ is an arbitrary progression containing $n$. We will bound the second sum at the end of this proof.

Let us analyse the first sum. We have
\begin{equation*}
\sum_{S\in \mathcal{X}} (-1)^{|S|} \ind{n \in \cap S} = \sum_{P\in X } c_{P} \ind{n\in P}
\end{equation*}
where, for $P\in X $,
\begin{equation*}
c_{P} := \sum_{\substack{S\in \mathcal{X}\\ \cap S = P}} (-1)^{|S|}  = \sum_{\substack{S\subset \{P'\in \mathcal{Y} : P'\supset P\} \\ \cap S = P}} (-1)^{|S|}.
\end{equation*}

Fix some $P\in X$. If $S$ is a set of progressions containing $P$, the condition $\cap S = P$ is equivalent to 
\begin{equation*}
	\mathrm{lcm} \{q_{P'} : P'\in S\} = q_{P}.
\end{equation*}
Since all progressions in $\mathcal{Y}$ have square-free moduli, this is in turn equivalent to
\begin{equation*}
	\bigcup_{P'\in S} \{p : p\mid q_{P'}\} = \{p : p\mid q_{P}\}.
\end{equation*}
Let $\Omega_P := \{p : p\mid q_{P}\}$,
\begin{equation*}
	\mathcal{A}_P := \Big\{ \{p : p\mid q_{P'}\} : P'\in \mathcal{Y}, P'\supset P\Big\}
\end{equation*}
and, for every set $S$ of progressions containing $P$, let 
\begin{equation*}
	\mathcal{B}_{P}(S) := \Big\{ \{p : p\mid q_{P'}\} : P'\in S\Big\}.
\end{equation*}
Note that $\mathcal{B}_P(S)$ determines $S$, since a progression $P'\in \mathcal{Y}$ with $P'\supset P$ is uniquely determined by its modulus $q_{P'}$, which in turn is uniquely determined by its set of prime factors. Therefore,
\begin{equation*}
c_P =  \sum_{\substack{S\subset \{P'\in \mathcal{Y} : P'\supset P\} \\ \cap S = P}} (-1)^{|S|} = \sum_{\substack{\mathcal{B} \subset \mathcal{A}_P \\ \cup \mathcal{B} = \Omega_P}} (-1)^{|\mathcal{B}|}.
\end{equation*}
By \cref{lem:rota}, we obtain $|c_P| \leqslant 2^{|\Omega_P|} = 2^{\omega(q_{P})}$.

We now turn to the remainder term. We suppose that $n\in P_0$ for some $P_0\in \mathcal{Y}$. We operate a change of variables and write ${S' = S \setminus \{P_0\}}$, $P = \cap S'$ and ${R = \cap S}$. The conditions $S \not\in \mathcal{X}$ and $S\setminus \{P_0\} \in \mathcal{X}$ become $R\not\in X$ and $P\in X$, respectively. Hence, we have 
\begin{equation*}
\sum_{\substack{P_0\in S \subset \mathcal{Y}\\ S \not\in \mathcal{X},\, S\setminus \{P_0\} \in \mathcal{X}}} (-1)^{|S|} \ind{n\in \cap S} 
= \sum_{\substack{R\in \mathcal{Y}^{\cap} \\ R\not \in X }}  \ind{n\in R}  \sum_{\substack{P\in X \\ R = P\cap P_0}}\sum_{\substack{S'\in \mathcal{X}\\ \cap S'= P}} (-1)^{|S'|+1}.
\end{equation*}
The inner sum is exactly $-c_P$, which is $O\big(2^{\omega(q_{P})}\big)$. Recalling that, for fixed $R$, a progression $P\supset R$ is uniquely determined by its modulus $q_{P}$, which divides $q_{R}$, we have
\begin{equation*}
\sum_{\substack{P_0\in S \subset \mathcal{Y}\\ S \not\in \mathcal{X},\, S\setminus \{P_0\} \in \mathcal{X}}} (-1)^{|S|} \ind{n\in \cap S} 
= O \left(\sum_{R\in \partial X}  \ind{n\in R}  \sum_{d\mid q_{R}} 2^{\omega(d)}\right).
\end{equation*}
The observation that $\sum_{d\mid m} 2^{\omega(d)} = 3^{\omega(m)}$ for all square-free $m\geqslant 1$ concludes the proof.

\begin{equation*}
\ind{n\not\in P\  \forall P\in \mathcal{Y}}  = \sum_{S\in \mathcal{X}} (-1)^{|S|} \ind{n \in \cap S}  +  \sum_{\substack{P_0\in S \subset \mathcal{Y}\\ S \not\in \mathcal{X},\, S\setminus \{P_0\} \in \mathcal{X}}} (-1)^{|S|} \ind{n\in \cap S},
\end{equation*}

\begin{equation*}
c_{P} := \sum_{\substack{S\in \mathcal{X}\\ \cap S = P}} (-1)^{|S|}  = \sum_{\substack{S\subset \{P'\in \mathcal{Y} : P'\supset P\} \\ \cap S = P}} (-1)^{|S|}.
\end{equation*}

\begin{equation*}
\sum_{\substack{P_0\in S \subset \mathcal{Y}\\ S \not\in \mathcal{X},\, S\setminus \{P_0\} \in \mathcal{X}}} (-1)^{|S|} \ind{n\in \cap S} 
= \sum_{\substack{R\in \mathcal{Y}^{\cap} \\ R\not \in X }}  \ind{n\in R}  \sum_{\substack{P\in X \\ R = P\cap P_0}}\sum_{\substack{S'\in \mathcal{X}\\ \cap S'= P}} (-1)^{|S'|+1}.
\end{equation*}

\begin{equation*}
\sum_{\substack{P_0\in S \subset \mathcal{Y}\\ S \not\in \mathcal{X},\, S\setminus \{P_0\} \in \mathcal{X}}} (-1)^{|S|} \ind{n\in \cap S} 
= O \left(\sum_{R\in \partial X}  \ind{n\in R}  \sum_{d\mid q_{R}} 2^{\omega(d)}\right).
\end{equation*}

\label{prop:probmodel}
Let $\varepsilon_1$, $H$, $J$, $H_0$, $(\mathcal{P}_i)$ and $(V_i)$ be as in \cref{thm:main}. Let $V := \max_i V_i$. 

Let $N \geqslant \exp\big((\log H)^{2}\big)$ and let $I_N := \mathbb{N} \cap (N, 2N]$.

For $\mathcal{I} \subset \sinterval{J}$, define $\mathcal{D}_\mathcal{I}$ to be the set of all products $\prod_{i\in \mathcal{I}}p_i$ with $p_i\in \mathcal{P}_i$ for all~$i$.
Then, for all non-empty $\mathcal{I} \subset \sinterval{J}$, we have
\begin{equation*}
 \sum_{n\in I_N}  \sum_{\substack{d\in \mathcal{D}_\mathcal{I}}}\frac{1}{d} \lambda(n) \lambda(n+d) \ll \frac{V^{J} N}{(\log H)^{1/2000}}.
\end{equation*}

We can expand the difference $S_2 - S_1$ as 
\begin{equation*}
\sum_{\substack{\emptyset \neq \mathcal{I} \subset \sinterval{J}}} S(\mathcal{I}),
\end{equation*}
where
\begin{equation*}
S(\mathcal{I}) := \sum_{n\in (N, 2N]} \sum_{(p_1,\ldots, p_{J})\in \mathcal{P}_1\times\cdots\times \mathcal{P}_{J}} \Bigg( \prod_{i\in \mathcal{I}} \frac{1}{p_i}\Bigg) \Bigg( \prod_{i\in \sinterval{J}\setminus \mathcal{I}} \ind{p_i \mid n}\Bigg) \lambda(n) \lambda(n+p_1\cdots p_{J}).
\end{equation*}
Changing variables $n = md$ with $d = \prod_{i\in \sinterval{J}\setminus \mathcal{I}}p_i$ gives
\begin{equation*}
S(\mathcal{I}) = \sum_{d\in \mathcal{D}_{\sinterval{J}\setminus \mathcal{I}}}\lambda(d)^2 \sum_{\frac{N}{d}<m\leqslant \frac{2N}{d}}\sum_{d'\in \mathcal{D}_\mathcal{I}} \frac{1}{d'} \lambda(m) \lambda(m+d').
\end{equation*}
By \cref{prop:probmodel}, the double sum over $m$ and $d'$ is 
\begin{equation*}
\ll \frac{V^{J} N/d}{(\log H)^{1/2000}}
\end{equation*}
Hence,
\begin{equation*}
S(\mathcal{I}) \ll  \frac{V^{J} N}{(\log H)^{1/2000}}\sum_{d\in \mathcal{D}_{\sinterval{J}\setminus \mathcal{I}}}\frac{1}{d} \ll \frac{\curlyLexp{2J} N}{(\log H)^{1/2000}}
\end{equation*}
for every non-empty $\mathcal{I} \subset \sinterval{J}$.
Therefore
\begin{equation*}
|S_2-S_1| \ll 2^{J} \curlyLexp{2J} \frac{N}{(\log H)^{1/2000}}.
\end{equation*}
Note that $2^J\curlyLexp{2J} \ll (\log H)^{\varepsilon_1}$ by \cref{lem:primesets}, so $|S_2-S_1| \ll \frac{N}{(\log H)^{1/2500}}$ if $\varepsilon_1$ is sufficiently small.

\label{lem:fourthmoment}
Fix a non-empty $\mathcal{I}\subset \sinterval{J}$ and let $\mathcal{D}_\mathcal{I}$ be as in \cref{prop:probmodel}. Let $M \in [H_0, H]$. Define 
\begin{equation*}
Q(\alpha) := \sum_{\substack{d\in \mathcal{D}_\mathcal{I}\\ d\in (M/2, M]}} \frac{e( \alpha d)}{d},
\end{equation*}
where, as usual, $e(x):=\exp(2\pi i x)$. Then, 
\begin{equation*}
\int_{0}^1 |Q(\alpha)|^4 \, d\alpha \ll \frac{\curlyLexp{4J}}{M (\log M)^{4}}.
\end{equation*}

By Parseval's identity, we can expand
\begin{equation*}
\int_{0}^1 |Q(\alpha)|^4 d\alpha = \int_{0}^1 \bBigg@{3}\lvert \sum_{|m|\leqslant M} \Bigg(\sum_{\substack{d_1,d_2\in \mathcal{D}_{\mathcal{I}}\\ d_1, d_2\in (M/2, M] \\boldsymbol{d}_1-d_2=m}}\frac{1}{d_1d_2}\Bigg) e(m\alpha)\bBigg@{3}\rvert^2 d\alpha = \sum_{|m|\leqslant M}  \bBigg@{3}\lvert \sum_{\substack{d_1,d_2\in \mathcal{D}_{\mathcal{I}}\\ d_1, d_2\in (M/2, M] \\boldsymbol{d}_1-d_2=m}}\frac{1}{d_1d_2} \bBigg@{3}\rvert^2.
\end{equation*}
For $m=0$, the inner sum is trivially $\ll 1/{M}$. 

Fix $m> 0$. Let $N(m, b, \mathcal{I}, M)$ denote the number pairs $(d_1, d_2)\in \mathcal{D}_{\mathcal{I}}\times \mathcal{D}_{\mathcal{I}}$ such that $d_1-d_2 = m$, $d_1\in (M/2,M]$ and ${\gcd(d_1, d_2, m) = b}$. Observe that $N(m, b, \mathcal{I}, M) = 0$ unless $b\mid m$ and $b\in \mathcal{D}_{\mathcal{I'}}$ for some $\mathcal{I'}\subset \mathcal{I}$, in which case we have
\begin{equation*}
N(m, b, \mathcal{I}, M) = N\left(\tfrac{m}{b}, 1, \mathcal{I}\setminus \mathcal{I'}, \tfrac{M}{b}\right).
\end{equation*}
We thus are led to bound the number of coprime solutions $(e_1, e_2)\in \mathcal{D}_{\mathcal{I}\setminus \mathcal{I'}}\times \mathcal{D}_{\mathcal{I}\setminus \mathcal{I'}}$ to the equation $e_1-e_2 = m/b$ with $e_1\in (M/2b, M/b]$. Let $i_+$ be the largest element of $\mathcal{I}\setminus \mathcal{I'}$. We can rewrite $e_i = n_i p_i$ where $n_i\in \mathcal{D}_{(\mathcal{I}\setminus \mathcal{I'}) \setminus \{i_+\}}$ and $p_i\in \mathcal{P}_{i_+}$ for $i\in \{1,2\}$. For fixed $n_1, n_2$, the number of solutions $(p_1, p_2)\in \mathcal{P}_{i_+}\times \mathcal{P}_{i_+}$ to the linear equation
\begin{equation*}
n_1p_1 - n_2p_2 = \frac{m}{b}
\end{equation*}
with $n_1p_1\in (M/2b, M/b]$ is 
\begin{equation*}
\ll \frac{M/b}{\varphi(n_1)\varphi(n_2)(\log M/b)^2} \cdot \frac{m/b}{\varphi(m/b)} 
\end{equation*}
by classical sieve theoretic methods, such as \cite[Proposition~6.22]{opera}. To apply this particular result, we used the fact that $\max(n_1, n_2) \leqslant (M/b)^{1/10}$, which holds by property \cref{item:primesets8} of \cref{lem:primesets}.

Note that $\varphi(n) \gg n$ if $n$ is a product of $\leqslant J$ primes, each $\geqslant H_0$. This is the case for $n_1$ and $n_2$. Therefore,
\begin{equation*}
N(m, b, \mathcal{I}, M) \ll  \sum_{n_1, n_2\in \mathcal{D}_{(\mathcal{I}\setminus \mathcal{I'})\setminus \{i_+\}}}\frac{M/b}{n_1n_2(\log M/b)^2} \cdot \frac{m/b}{\varphi(m/b)} \ll \curlyLexp{2J}\frac{M/b}{(\log M/b)^2} \cdot \frac{m}{\varphi(m)}.
\end{equation*}
We conclude that the total number of solutions $(d_1, d_2)$ to $d_1-d_2 = m$ with $d_1, d_2\in (M/2, M]$ is
\begin{equation*}
\ll \sum_{\substack{b\mid m\\ b< m}}\curlyLexp{2J}\frac{M/b}{(\log M/b)^2} \cdot \frac{m}{\varphi(m)} \ll \frac{\curlyLexp{2J} M}{(\log M)^2}\cdot \frac{\sigma_1(m)}{\varphi(m)}.
\end{equation*}

We thus obtain
\begin{equation*}
\int_{0}^1 |Q(\alpha)|^4 d\alpha \ll \frac{1}{M^2} + \left(\frac{\curlyLexp{2J}}{M(\log M)^2}\right)^2 \sum_{m=1}^{M} \left(\frac{\sigma_1(m)}{\varphi(m)}\right)^2 \ll \frac{\curlyLexp{4J}}{M (\log M)^4},
\end{equation*}
where we used the elementary estimate \cite[Corollary~3.6]{tenenbaum} in the last inequality.

\begin{equation*}
\int_{0}^1 |Q(\alpha)|^4 d\alpha = \int_{0}^1 \bBigg@{3}\lvert \sum_{|m|\leqslant M} \Bigg(\sum_{\substack{d_1,d_2\in \mathcal{D}_{\mathcal{I}}\\ d_1, d_2\in (M/2, M] \\boldsymbol{d}_1-d_2=m}}\frac{1}{d_1d_2}\Bigg) e(m\alpha)\bBigg@{3}\rvert^2 d\alpha = \sum_{|m|\leqslant M}  \bBigg@{3}\lvert \sum_{\substack{d_1,d_2\in \mathcal{D}_{\mathcal{I}}\\ d_1, d_2\in (M/2, M] \\boldsymbol{d}_1-d_2=m}}\frac{1}{d_1d_2} \bBigg@{3}\rvert^2.
\end{equation*}

\begin{equation*}
N(m, b, \mathcal{I}, M) \ll  \sum_{n_1, n_2\in \mathcal{D}_{(\mathcal{I}\setminus \mathcal{I'})\setminus \{i_+\}}}\frac{M/b}{n_1n_2(\log M/b)^2} \cdot \frac{m/b}{\varphi(m/b)} \ll \curlyLexp{2J}\frac{M/b}{(\log M/b)^2} \cdot \frac{m}{\varphi(m)}.
\end{equation*}

\begin{equation*}
\ll \sum_{\substack{b\mid m\\ b< m}}\curlyLexp{2J}\frac{M/b}{(\log M/b)^2} \cdot \frac{m}{\varphi(m)} \ll \frac{\curlyLexp{2J} M}{(\log M)^2}\cdot \frac{\sigma_1(m)}{\varphi(m)}.
\end{equation*}

Let $V_{[M]} :=\sum_{\substack{d\in \mathcal{D}_{\mathcal{I}}\cap (M/2, M]}}1/d$. It suffices to show that
\begin{equation}
\label{eq:dyadicsufficient}
 	T_{M} := \sum_{n\in I_N}  \sum_{\substack{d\in \mathcal{D}_{\mathcal{I}}\\ d\in (M/2, M]}}\frac{1}{d} \lambda(n) \lambda(n+d) \ll  \left(\frac{V^{J}}{\log M}+V_{[M]}\right) \frac{N}{(\log H)^{1/1750}}
\end{equation}
