\begin{equation*}
\sum_{n\in I_N}  \sum_{\substack{d\in \mathcal{D}_{\mathcal{I}}}}\frac{1}{d} \lambda(n) \lambda(n+d) \ll \Big(V^{J}(\log \log H)+V^{J} \Big) \frac{N}{(\log H)^{1/1750}} \ll \frac{V^{J} N}{(\log H)^{1/2000}}.
\end{equation*}

To prove \cref{eq:dyadicsufficient}, we start by introducing a new average over shifts $m\leqslant M$ and use the circle method:
\begin{align*}
	T_{M} &= \frac{1}{M} \sum_{m\leqslant M} \sum_{n\in I_N}   \sum_{\substack{d\in \mathcal{D}_{\mathcal{I}}\\ d\in (M/2, M]}}\frac{1}{d} \lambda(n+m) \lambda(n+m+d) + O(MV^{J})\\
	&= \frac{1}{M} \sum_{n\in I_N} \int_0^1 Q(\alpha) F_n(\alpha) G_n(\alpha) d\alpha + O(MV^{J}),
\end{align*}
with $F_n(\alpha):=\sum_{m\leqslant M}\lambda(n+m)e(\alpha m)$, $G_n(\alpha):=\sum_{k\leqslant 2M}\lambda(n+k)e(-\alpha k)$ and $Q(\alpha)$ as in \cref{lem:fourthmoment}.
The error term $O(MV^{J})$ is clearly negligible. 

Let $\varepsilon>0$ be a parameter that will be fixed later, and let $E_\varepsilon := \{\alpha\in [0, 1] : |Q(\alpha)| > \varepsilon\}$. Outside of $E_{\varepsilon}$, the function $|Q|$ is small and we have 
\begin{equation*}
\sum_{n\in I_N} \int_{[0, 1]\setminus E_{\varepsilon}} |Q||F_n| |G_n| \leqslant \varepsilon N \norm{F_n}_2 \norm{G_n}_2 \ll \varepsilon M N.
\end{equation*}
On the other hand, the Lebesgue measure of $E_{\varepsilon}$ is $\ll \curlyLexp{4J}/(\varepsilon^4 M (\log M)^4)$ by \cref{lem:fourthmoment} and Markov's inequality. Hence
\begin{equation*}
\sum_{n\in I_N} \int_{E_{\varepsilon}} |Q||F_n| |G_n| \ll \frac{\curlyLexp{4J} \norm{Q}_{\infty} }{\varepsilon^4 M (\log M)^4} \norm{\sum_{n\in I_N} |F_n||G_n|}_{\infty}\!\! \ll \frac{\curlyLexp{4J}  \, V_{[M]}}{\varepsilon^4 M (\log M)^4} M \norm{\sum_{n\in I_N} |F_n|}_{\infty}.
\end{equation*}
We now make crucial use of \cite[Theorem~1.3]{MRT} to obtain
\begin{equation*}
 	\norm{\sum_{n\in I_N} |F_n|}_{\infty} \!\! = \sup_{\alpha\in \mathbb{R}}\, \sum_{n\in I_N} \abs{\sum_{n\leqslant n'\leqslant n+M} \lambda(n') e(\alpha n')} \ll \left((\log M)^{-1/2} + (\log N)^{-1/700} \right) M N.
\end{equation*}
Since $M \geqslant H_0$ and $\log N \geqslant (\log H)^2$, this upper bound is $\ll (\log H)^{-c'}$ where $c' = 1/350$.

Putting everything together, we conclude that 
\begin{equation*}
T_{M}  \ll \left(\varepsilon +\frac{\curlyLexp{4J}\, V_{[M]}}{\varepsilon^4 (\log M )^4 (\log H)^{c'}} \right) N.
\end{equation*}
We choose $\varepsilon = V^{J} (\log M )^{-1} (\log H)^{-c'/5}$ and deduce the claimed bound \cref{eq:dyadicsufficient}.

