The first step is to bound the derivatives of the test function $\varphi(x) := \ind{[-1, 1]}(x) f(x)$, where
\begin{equation*}
f(z) :=  \exp \left(\frac{2}{z^2-1}\right).
\end{equation*}
This can be done using Cauchy's inequality for holomorphic functions. 

For $0 < x < 1$, we choose the radius $R(x) = (1-x)/2$. Note that $\tfrac{2}{z^2-1} = \tfrac{1}{z-1} - \tfrac{1}{z+1}$. For any $z\in \mathbb{C}$ with $|z-x| = R(x)$, we have
\begin{equation*}
|f(z)| = \exp \left(\mathrm{Re} \left(\frac{1}{z-1}\right)\right) \exp \left(\mathrm{Re} \left(\frac{-1}{z+1}\right)\right) \ll \exp \left( \frac{1}{x-R(x)-1}\right) = \exp \left(\frac{-1}{3R(x)}\right).
\end{equation*}
In particular, for any integer $a\geqslant 1$ we have $\abs{f(z)}\ll a! (3R(x))^a$. Cauchy's inequality then gives 
\begin{equation*}
\abs{f^{(a)}(x)} \ll \frac{a!}{R(x)^{a}} a! (3R(x))^a \ll \left(O(a)\right)^a.
\end{equation*}
Therefore $\norm{\varphi^{(a)}} _{\infty} \leqslant \left(O(a)\right)^a$.

Let $T := JV$. We now define $W$ as the convolution
\begin{equation*}
W(x) := \tfrac{4}{T}\varphi\left(\tfrac{4}{T}x\right)*\ind{\left[\tfrac{T}{4}, \tfrac{7T}{4}\right]}(x) .
\end{equation*}
Using $\frac{d}{dx}(F*G)=\big(\frac{d}{dx}F\big)*G$ and $\norm{F*G}_{\infty} \leqslant \norm{F}_{\infty}\norm{G}_1$ we get the bound 
\begin{equation*}
\norm{W^{(a)}}_{\infty} \leqslant \left(\frac{Ca}{T}\right)^a
\end{equation*}
for the derivatives of $W$, where $C>0$ is an absolute constant.

For powers of $W$, we use the generalised Leibniz rule to get
\begin{equation*}
\norm{(W^m)^{(a)}}_{\infty} \leqslant \sum_{\substack{b_1+ \ldots +b_m = a\\ b_i\in \mathbb{Z}^{\geqslant 0}}} \frac{a!}{b_1!\cdots b_m!} \prod_{i=1}^{m} \norm{W^{(b_i)}}_{\infty}. 
\end{equation*}
This sum has ${a+m-1\choose m-1}\leqslant 2^{a+m}$ terms, and each of them is 
\begin{equation*}
\leqslant \frac{a!}{b_1!\cdots b_m!}   \prod_{i=1}^{m} \left(\frac{Cb_i}{T}\right)^{b_i} \leqslant \left(\frac{O(a)}{T}\right)^{a}.
\end{equation*}
The inequality follows, and the other properties of $W$ are clear.


\label{lem:flst}
Let $z, D, \kappa > 0$. Let $P$ be a set of primes $p\leqslant z$. Let $(a_n)$ be a sequence of non-negative real numbers. Suppose that, for every square-free $d\leqslant D$ all of whose prime factors are in $P$, we have
