	\sum_{d\mid n} a_n = g(d)M + R_d
\end{equation*} 
with $g$ a non-negative multiplicative function such that, for all $2\leqslant w\leqslant z$, 
\begin{equation*}
	\prod_{\substack{w\leqslant p < z \\ p\in P}} (1-g(p))^{-1} \leqslant A \left(\frac{\log z}{\log w}\right)^{\kappa},
\end{equation*}
where $A > 1$ is a constant. Let $s = {\log D}/\log z$, and assume $9\kappa - s < -1$. Then 
\begin{equation*}
\sum_{p\nmid n \, \forall p\in P} a_n = \prod_{p\in P}\left(1-g(p)\right) \cdot M \cdot \left(1+O(e^{9\kappa - s}A^{10})\right) + O \Bigg(\sum_{\substack{d\leqslant D\\p\mid d \Rightarrow p\in P}} \mu(d)^2|R_d|\Bigg),
\end{equation*}
where the implied constants are $\leqslant 1$ in absolute value.

\begin{equation*}
	\prod_{\substack{w\leqslant p < z \\ p\in P}} (1-g(p))^{-1} \leqslant A \left(\frac{\log z}{\log w}\right)^{\kappa},
\end{equation*}

\begin{equation*}
\sum_{p\nmid n \, \forall p\in P} a_n = \prod_{p\in P}\left(1-g(p)\right) \cdot M \cdot \left(1+O(e^{9\kappa - s}A^{10})\right) + O \Bigg(\sum_{\substack{d\leqslant D\\p\mid d \Rightarrow p\in P}} \mu(d)^2|R_d|\Bigg),
\end{equation*}

\label{cor:flst}
Let $z,\kappa>0$. Let $P$ be a set of primes $p\leqslant z$. Let $(a_n)$ be a of sequence of non-negative real numbers. 

Suppose that, for every square-free $d$ all of whose prime factors are in $P$, we have
\begin{equation*}
	\sum_{d\mid n} a_n = \frac{\rho(d)}{d}M + R_d,
\end{equation*} 
where 
\begin{itemize}
	\item $\rho$ is a non-negative multiplicative function;
	\item $|R_d| \ll \rho(d)$ for all square-free $d$ all of whose prime factors are in $P$;
	\item $\rho(p) \leqslant \min (p-1, \kappa)$ for every $p\in P$.
\end{itemize}
There exists an absolute constant $C>1$ such that the following holds. Let $u = {\log M}/\log z$ and assume that $\log M \geqslant C\kappa \log z$. Then
\begin{equation*}
\sum_{p\nmid n \, \forall p\in P} a_n = M\prod_{p\in P}\left(1-\frac{\rho(p)}{p}\right) \cdot \left(1+O\left(e^{-u/2}\right)\right),
\end{equation*}
where the implied constant is absolute.

\begin{equation*}
\sum_{p\nmid n \, \forall p\in P} a_n = M\prod_{p\in P}\left(1-\frac{\rho(p)}{p}\right) \cdot \left(1+O\left(e^{-u/2}\right)\right),
\end{equation*}

On the one hand, note that
\begin{equation*}
\prod_{p\in P} \left(1-\frac{\rho(p)}{p}\right)^{-1} \leqslant \prod_{p\leqslant 2\kappa} p \prod_{2\kappa < p\leqslant z} \left(1-\frac{\kappa}{p}\right)^{-1} \leqslant \exp \Big(O(\kappa) + \kappa (\log \log z + O(1))\Big) \leqslant e^{O(\kappa)}(\log z)^{\kappa}.
\end{equation*}
It is an easy exercise to adapt this computation and obtain, for any $2\leqslant w\leqslant z$, 
\begin{equation*}
\prod_{\substack{p\in P\\p\geqslant w}} \left(1-\frac{\rho(p)}{p}\right)^{-1}  \leqslant e^{O(\kappa)}\left(\frac{\log z}{\log w}\right)^{\kappa}.
\end{equation*}

On the other hand, for any $D\geqslant 1$ we have
\begin{equation*}
\sum_{\substack{d\leqslant D\\p\mid d \Rightarrow p\in P}} \mu(d)^2|R_d| \ll D\!\!\!\sum_{\substack{d\leqslant D\\p\mid d \Rightarrow p\in P}} \mu(d)^2\frac{|\rho(d)|}{d} \leqslant D \prod_{p\in P} \left(1+\frac{\rho(p)}{p}\right) \leqslant D \exp \Big(\kappa (\log \log z+O(1))\Big),
\end{equation*}
which is $\ll D (\log z)^{\kappa}$.

Choose $D = M^{2/3}$ and apply \cref{lem:flst} with $g(d) = \rho(d)/d$ and $A = e^{O(\kappa)} (\log z)^{\kappa}$. Note that
\begin{equation*}
s= \frac{\tfrac23 \log M}{\log z} \geqslant C\kappa
\end{equation*}
by assumption. So, if $C$ is sufficiently large, 
\begin{equation*}
\sum_{p\nmid n \, \forall p\in P} a_n = M\prod_{p\in P}\left(1-\frac{\rho(p)}{p}\right) \cdot \left(1+O\left(e^{-u/2}\right)\right) + O\left(M^{2/3} (\log z)^{\kappa}\right).
\end{equation*}
To obtain the desired conclusion, it remains to check that 
\begin{equation*}
M^{2/3} (\log z)^{\kappa} \ll \frac{M}{e^{O(\kappa)}(\log z)^{\kappa}} e^{-u/2},
\end{equation*}
which also follows from our assumption $\log M \geqslant C\kappa \log z$.

\begin{equation*}
\prod_{p\in P} \left(1-\frac{\rho(p)}{p}\right)^{-1} \leqslant \prod_{p\leqslant 2\kappa} p \prod_{2\kappa < p\leqslant z} \left(1-\frac{\kappa}{p}\right)^{-1} \leqslant \exp \Big(O(\kappa) + \kappa (\log \log z + O(1))\Big) \leqslant e^{O(\kappa)}(\log z)^{\kappa}.
\end{equation*}

\begin{equation*}
\sum_{\substack{d\leqslant D\\p\mid d \Rightarrow p\in P}} \mu(d)^2|R_d| \ll D\!\!\!\sum_{\substack{d\leqslant D\\p\mid d \Rightarrow p\in P}} \mu(d)^2\frac{|\rho(d)|}{d} \leqslant D \prod_{p\in P} \left(1+\frac{\rho(p)}{p}\right) \leqslant D \exp \Big(\kappa (\log \log z+O(1))\Big),
\end{equation*}

