\sum_{p\nmid n \, \forall p\in P} a_n = M\prod_{p\in P}\left(1-\frac{\rho(p)}{p}\right) \cdot \left(1+O\left(e^{-u/2}\right)\right) + O\left(M^{2/3} (\log z)^{\kappa}\right).
\end{equation*}

\label{lem:kubilius}
Let $X$ be a subset of $\mathcal{P} \times \sinterval{K}$. Suppose that 
\begin{equation*}
|\mathrm{pr}_1(X)| \leqslant 2KJ V.
\end{equation*}

Let $\mathbf{n}$ be a random variable taking values in $\prod_{p\in \mathcal{P}} \mathbb{Z}/p\mathbb{Z}$ with the uniform distribution. Then
\begin{equation*}
 \frac1N\sum_{n\in I_N}\ind{\substack{p\mid n+b_i\, \forall (p, i)\in X  \\ p\nmid n+b_i\, \forall (p, i)\notin X}} 
 =  \mathbb{P} \left(
	\begin{aligned}\forall (p, i)\in X, \, p\mid \mathbf{n}+b_i \, \ \mathrm{and}\\ \forall (p, i)\notin X, \, p\nmid \mathbf{n}+b_i \ \ \  \ \ \ 
	\end{aligned}
\right) \cdot \left(1+O\left(e^{-\sqrt{\log N}}\right)\right).
\end{equation*}

\begin{equation*}
 \frac1N\sum_{n\in I_N}\ind{\substack{p\mid n+b_i\, \forall (p, i)\in X  \\ p\nmid n+b_i\, \forall (p, i)\notin X}} 
 =  \mathbb{P} \left(
	\begin{aligned}\forall (p, i)\in X, \, p\mid \mathbf{n}+b_i \, \ \mathrm{and}\\ \forall (p, i)\notin X, \, p\nmid \mathbf{n}+b_i \ \ \  \ \ \ 
	\end{aligned}
\right) \cdot \left(1+O\left(e^{-\sqrt{\log N}}\right)\right).
\end{equation*}

We can assume that $X$ satisfies the following consistency constraints (otherwise both sides are zero and there is nothing to prove):
\begin{itemize}
	\item If $b_i, b_j\in A$ are congruent modulo $p\in \mathcal{P}$, then $(p, i) \in X$ if and only if $(p, j) \in X$.
	\item If $b_i, b_j\in A$ are not congruent modulo $p\in \mathcal{P}$, and $(p, i) \in X$, then $(p, j) \notin X$.
	\item If $\boldsymbol{b}$ covers all residue classes modulo $p\in \mathcal{P}$, then $(p, i) \in X$ for at least one $i\in \sinterval{K}$.
\end{itemize}

We now split $\mathcal{P}$ into two subsets: $\mathcal{P}^+$, the set of $p\in \mathcal{P}$ such that $(p, i) \in X$ for at least one $i\in\sinterval{K}$; and its complement $\mathcal{P}^- := \mathcal{P} \setminus \mathcal{P}^+$.

By the Chinese remainder theorem, there is a progression $a+q\mathbb{Z}$, with $q =\prod_{p\in \mathcal{P}^+} p$ such that 
\begin{equation*}
\frac{1}{N} \sum_{n\in I_N} \ind{\substack{p\mid n+b_i\, \forall (p, i)\in X \\ p\nmid n+b_i\, \forall (p, i)\notin X}} = \frac{1}{N} \sum_{n\in I_N \cap (a+q\mathbb{Z})} \ind{p\nmid n+b_i\, \forall p\in \mathcal{P}^- \forall i\in \sinterval{K}}.
\end{equation*}
We can rewrite the latter sum as $\sum_{p\nmid m\, \forall p\in \mathcal{P}^-} a_m$ where 
\begin{equation*}
a_m := \sum_{n\in I_N\cap (a+q\mathbb{Z})}\ind{m = \prod_{i\in \sinterval{K}} (n+b_i) }.
\end{equation*}

We wish to use \cref{cor:flst}. It is easy to show that
\begin{equation*}
\sum_{d\mid m} a_m = \sum_{n\in I_N \cap (a+q\mathbb{Z})} \ind{d\mid \prod_{i\in \sinterval{K}} (n+b_i)} = \frac{\rho(d)}{d} \frac{N}{q} + O(\rho(d)),
\end{equation*}
where the multiplicative function $\rho(d)$ counts the number of solutions to $\prod_{i\in\sinterval{K}} (x+b_i)\equiv 0 \pmod d$. Note that $\rho(p) \leqslant K$ for all $p\in \mathcal{P}^{-}$ and $\rho(p) \leqslant p-1$ since $\boldsymbol{b}$ does not cover all residue classes modulo $p \in \mathcal{P}^{-}$ by one of our preliminary assumptions. 

We now apply the Fundamental Lemma in the form of \cref{cor:flst}, with ${g(d) = \rho(d)/d}$, ${M = {N}/{q}}$, $z=H$ and $\kappa = K$. The hypothesis $\log M \geqslant C\kappa \log z$ is satisfied, since it can be rewritten as ${\log N \geqslant \log q + CK \log H}$ and we know that $q \leqslant H^{2KJ V} \leqslant N^{1/2}$ by our choice of parameters.
We conclude that
\begin{equation*}
\frac{1}{N} \sum_{n\in I_N} \ind{\substack{p\mid n+b_i\, \forall (p, i)\in X \\ p\nmid n+b_i\, \forall (p, i)\notin X}} = \prod_{p\in \mathcal{P}^{+}}\frac 1p \prod_{p\in \mathcal{P}^{-}}\left(1-\frac{\rho(p)}{p}\right) \cdot \left(1+O\left(e^{-\sqrt{\log N}}\right)\right),
\end{equation*}
which is exactly what we wanted by definition of the random variable $\mathbf{n}$ and the consistency constraints above.

