We start by removing, in \cref{eq:traceexpressionX}, the condition that $n+b_i\in I_N$ for every $i$, and only require the starting vertex $n$ to be in $I_N$. Since $|b_i| \leqslant K H$ for all $i\in \sinterval{K}$, we have
\begin{equation*}
\sum_{\substack{\boldsymbol{d}\in \mathbf{D}_{\!K}}}  \sum_{\substack{n\in I_N\\ \exists i,\, n+b_i \not\in I_N}} \!\!1 \ll (2H)^{K} \cdot  K H \ll N.
\end{equation*}

Given $\boldsymbol{d}\in \mathbf{D}_{\!K}$ and a subset $X$ of $\mathcal{P}\times \sinterval{K}$, write $I_N(X, \boldsymbol{d})$ for the set of all $n\in I_N$ such that, for all $(p, i)\in \mathcal{P}\times \sinterval{K}$,
\begin{equation*}
	p\mid n+b_i \iff (p,i)\in X.
\end{equation*}
Summing over all possibilities for $X$, the expression \cref{eq:traceexpressionX} becomes
\begin{equation*}
\mathrm{Tr} \big((\mathrm{Ad}_{G})^{K}\big) = \sum_{\substack{\boldsymbol{d}\in \mathbf{D}_{\!K}}}\,  \sum_{\substack{X\subset \mathcal{P}\times \sinterval{K}}}\, \sum_{n\in I_N(X, \boldsymbol{d})}w_{\boldsymbol{d}}(n) \ + \, O(N).
\end{equation*}

The important observation is that, for fixed $\boldsymbol{d}$ and $X$, the term $w_{\boldsymbol{d}}(n)$ is independent of~$n\in I_N(X, \boldsymbol{d})$. We may thus call it $w_{\boldsymbol{d}}(X)$, and rewrite the triple sum as
\begin{equation}
\label{eq:summingoverDiv}
\sum_{\substack{\boldsymbol{d}\in \mathbf{D}_{\!K}}}\, \sum_{\substack{X\subset \mathcal{P}\times \sinterval{K}}} w_{\boldsymbol{d}}(X) \abs{I_N(X, \boldsymbol{d})}.
\end{equation}

If $|\mathrm{pr}_1(X)| > 2KJ V$ ($\mathrm{pr}_1$ being the projection on the first coordinate), the coefficient $w_{\boldsymbol{d}}(X)$ is zero, since in that case one of the factors $W$ vanishes. Otherwise, by \cref{lem:kubilius}, 
\begin{equation*}
\abs{I_N(X, \boldsymbol{d})} = N\cdot  \mathbb{P} \left(
	\begin{aligned}\forall (p, i)\in X, \, p\mid \mathbf{n}+b_i \, \text{ and}\\ \forall (p, i)\notin X, \, p\nmid \mathbf{n}+b_i \hspace{1pt} \ \ \ \ \ \ 
	\end{aligned}
\right) \cdot \left(1+O\left(e^{-\sqrt{\log N}}\right)\right).
\end{equation*}

Hence, we can interpret the sum over $X$ as the expected value of $w_{\boldsymbol{d}}(\mathbf{n})$, with a small error term. More precisely, \cref{eq:summingoverDiv} is
\begin{equation*}
N \sum_{\substack{\boldsymbol{d}\in \mathbf{D}_{\!K}}}\mathbb{E}\left[w_{\boldsymbol{d}}(\mathbf{n})\right] + O\left(Ne^{-\sqrt{\log N}}\right) \sum_{\substack{\boldsymbol{d}\in \mathbf{D}_{\!K}}} \mathbb{E}\left[ \abs{ w_{\boldsymbol{d}}(\mathbf{n})   }\right],
\end{equation*}
which concludes the proof of \cref{lem:useflst}.

\begin{equation*}
\sum_{\substack{\boldsymbol{d}\in \mathbf{D}_{\!K}}}  \sum_{\substack{n\in I_N\\ \exists i,\, n+b_i \not\in I_N}} \!\!1 \ll (2H)^{K} \cdot  K H \ll N.
